// Module 1: Rates and Returns (55 questions)
const module1Questions: Question[] = [
  { id: 'qm-m1-q1', questionText: 'A stated annual interest rate of 8% compounded quarterly results in an effective annual rate closest to:', answerChoices: [{ label: 'A', text: '8.00%', isCorrect: false, explanation: 'This is the stated (nominal) rate, not the effective annual rate which accounts for compounding.' }, { label: 'B', text: '8.24%', isCorrect: true, explanation: 'EAR = (1 + 0.08/4)^4 - 1 = (1.02)^4 - 1 = 1.0824 - 1 = 8.24%. More frequent compounding increases the effective rate above the stated rate.' }, { label: 'C', text: '8.16%', isCorrect: false, explanation: 'This would correspond to semi-annual compounding (1.04^2 - 1), not quarterly.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q2', questionText: 'The holding period return on an investment purchased for $100 that pays a $3 dividend and is sold for $108 is closest to:', answerChoices: [{ label: 'A', text: '8.0%', isCorrect: false, explanation: 'This only accounts for capital appreciation and excludes dividend income.' }, { label: 'B', text: '11.0%', isCorrect: true, explanation: 'HPR = (108 - 100 + 3) / 100 = 11/100 = 11.0%. The holding period return includes both price change and income received.' }, { label: 'C', text: '3.0%', isCorrect: false, explanation: 'This only considers the dividend yield and ignores the capital gain component.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q3', questionText: 'An investor earns returns of 10%, -5%, and 20% over three consecutive years. The geometric mean annual return is closest to:', answerChoices: [{ label: 'A', text: '8.33%', isCorrect: false, explanation: 'This is the arithmetic mean (25/3), which overstates compound growth.' }, { label: 'B', text: '7.89%', isCorrect: true, explanation: 'Geometric mean = [(1.10)(0.95)(1.20)]^(1/3) - 1 = [1.254]^(1/3) - 1 = 7.89%. The geometric mean properly accounts for compounding.' }, { label: 'C', text: '6.45%', isCorrect: false, explanation: 'This understates the actual compound growth rate achieved over the three periods.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q4', questionText: 'The continuously compounded return equivalent to a holding period return of 10% is closest to:', answerChoices: [{ label: 'A', text: '9.53%', isCorrect: true, explanation: 'Continuously compounded return = ln(1 + HPR) = ln(1.10) = 0.0953 = 9.53%. The continuously compounded return is always less than the discrete HPR.' }, { label: 'B', text: '10.00%', isCorrect: false, explanation: 'This is the discrete HPR, not the continuously compounded equivalent.' }, { label: 'C', text: '10.52%', isCorrect: false, explanation: 'This would be e^0.10 - 1, which converts a continuous rate to discrete, not the other way around.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q5', questionText: 'A money market instrument with a face value of $100,000, 90 days to maturity, and a bank discount yield of 4% has a purchase price closest to:', answerChoices: [{ label: 'A', text: '$99,000', isCorrect: true, explanation: 'Price = Face x (1 - BDY x t/360) = 100,000 x (1 - 0.04 x 90/360) = 100,000 x 0.99 = $99,000. Bank discount yield uses face value and 360-day year.' }, { label: 'B', text: '$99,010', isCorrect: false, explanation: 'This would result from using a money market yield calculation rather than bank discount yield.' }, { label: 'C', text: '$98,000', isCorrect: false, explanation: 'This overstates the discount by using the full annual rate rather than the proportional 90-day discount.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q6', questionText: 'The money market yield on a 180-day Treasury bill quoted at a bank discount yield of 3.5% is closest to:', answerChoices: [{ label: 'A', text: '3.56%', isCorrect: true, explanation: 'Price = 100(1 - 0.035 x 180/360) = 98.25. MMY = (100 - 98.25)/98.25 x 360/180 = 3.56%. Money market yield uses price (not face) in the denominator.' }, { label: 'B', text: '3.50%', isCorrect: false, explanation: 'This is the bank discount yield. The money market yield adjusts for the actual investment amount and is slightly higher.' }, { label: 'C', text: '3.62%', isCorrect: false, explanation: 'This overstates the yield conversion by using 365 days rather than the 360-day convention for money market yield.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q7', questionText: 'The bond equivalent yield of a money market instrument with 90 days to maturity and a holding period return of 1.5% is closest to:', answerChoices: [{ label: 'A', text: '6.08%', isCorrect: true, explanation: 'BEY = HPR x 365/t = 0.015 x 365/90 = 6.08%. Bond equivalent yield annualizes using a 365-day year without compounding.' }, { label: 'B', text: '6.00%', isCorrect: false, explanation: 'This uses a 360-day year rather than the 365-day convention required for bond equivalent yield.' }, { label: 'C', text: '6.14%', isCorrect: false, explanation: 'This would correspond to effective annual yield with compounding, not the simple annualization of BEY.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q8', questionText: 'The relationship between the nominal interest rate, real interest rate, and inflation is best described by:', answerChoices: [{ label: 'A', text: 'Nominal rate approximately equals real rate plus expected inflation (Fisher relation)', isCorrect: true, explanation: 'The Fisher relation states: (1 + nominal) = (1 + real)(1 + inflation). For small rates, nominal rate is approximately real rate + inflation premium. This fundamental relationship links real and nominal returns.' }, { label: 'B', text: 'Real rate equals nominal rate plus inflation', isCorrect: false, explanation: 'This reverses the relationship. Real rate = nominal rate minus inflation (approximately), not plus.' }, { label: 'C', text: 'Nominal rate equals real rate multiplied by inflation', isCorrect: false, explanation: 'The Fisher relation is additive (approximately), not multiplicative in the way described.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q9', questionText: 'An investment requires an initial outlay of $1,000 and returns $1,200 after two years. The annualized return is closest to:', answerChoices: [{ label: 'A', text: '9.54%', isCorrect: true, explanation: 'Annualized return = (1200/1000)^(1/2) - 1 = (1.20)^0.5 - 1 = 9.54%. We must take the nth root where n is the number of years to annualize a multi-period return.' }, { label: 'B', text: '10.00%', isCorrect: false, explanation: 'This divides the total 20% return by 2, which is simple division and does not account for compounding.' }, { label: 'C', text: '20.00%', isCorrect: false, explanation: 'This is the total two-year holding period return, not the annualized return.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q10', questionText: 'The gross return on an investment differs from the net return by:', answerChoices: [{ label: 'A', text: 'Management fees, administrative costs, and other expenses charged to the investor', isCorrect: true, explanation: 'Gross return is the total return before deducting fees and expenses. Net return = Gross return - fees - expenses. The distinction matters for evaluating manager skill vs. investor experience.' }, { label: 'B', text: 'Taxes only', isCorrect: false, explanation: 'Tax adjustments distinguish pre-tax from after-tax returns. Gross vs. net refers to fees and expenses, not taxes.' }, { label: 'C', text: 'Inflation adjustment', isCorrect: false, explanation: 'Inflation adjustment distinguishes nominal from real returns, not gross from net returns.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q11', questionText: 'A required rate of return on equity can be decomposed into:', answerChoices: [{ label: 'A', text: 'Real risk-free rate + inflation premium + risk premiums', isCorrect: true, explanation: 'The required return builds from the real risk-free rate, adds expected inflation (giving the nominal risk-free rate), then adds various risk premiums (default, liquidity, maturity) to compensate for specific risks.' }, { label: 'B', text: 'Dividend yield only', isCorrect: false, explanation: 'Dividend yield is one component of equity return but does not represent the full required return decomposition.' }, { label: 'C', text: 'Capital gains minus losses', isCorrect: false, explanation: 'This describes realized return, not the required rate of return which is forward-looking and risk-based.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q12', questionText: 'The effective annual rate for a stated rate of 12% compounded monthly is closest to:', answerChoices: [{ label: 'A', text: '12.68%', isCorrect: true, explanation: 'EAR = (1 + 0.12/12)^12 - 1 = (1.01)^12 - 1 = 12.68%. Monthly compounding over 12 periods produces a higher effective rate than the stated 12%.' }, { label: 'B', text: '12.36%', isCorrect: false, explanation: 'This corresponds to semi-annual compounding, not monthly.' }, { label: 'C', text: '12.00%', isCorrect: false, explanation: 'This is the nominal rate. The effective rate with compounding frequency greater than annual always exceeds the nominal rate.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q13', questionText: 'As compounding frequency increases, the effective annual rate:', answerChoices: [{ label: 'A', text: 'Increases and approaches e^r - 1 as the limit', isCorrect: true, explanation: 'As compounding frequency approaches infinity (continuous compounding), EAR approaches e^r - 1. Each increase in frequency adds a smaller increment to the effective rate.' }, { label: 'B', text: 'Decreases toward zero', isCorrect: false, explanation: 'More frequent compounding always increases, not decreases, the effective rate relative to the nominal rate.' }, { label: 'C', text: 'Remains unchanged', isCorrect: false, explanation: 'The effective rate changes with compounding frequency. Only with annual compounding does EAR equal the stated rate.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q14', questionText: 'The discount factor for a 2-year zero-coupon bond with a yield of 5% per year is closest to:', answerChoices: [{ label: 'A', text: '0.9070', isCorrect: true, explanation: 'Discount factor = 1/(1+r)^n = 1/(1.05)^2 = 1/1.1025 = 0.9070. The discount factor converts a future cash flow to present value.' }, { label: 'B', text: '0.9524', isCorrect: false, explanation: 'This is the one-year discount factor 1/(1.05), not the two-year factor.' }, { label: 'C', text: '0.8638', isCorrect: false, explanation: 'This corresponds to a three-year discount factor at 5%, not two years.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q15', questionText: 'The arithmetic mean return is most appropriate when estimating:', answerChoices: [{ label: 'A', text: 'The expected return for a single future period', isCorrect: true, explanation: 'The arithmetic mean is an unbiased estimator of expected single-period return. For multi-period compound growth, the geometric mean is preferred.' }, { label: 'B', text: 'The compound growth rate over multiple periods', isCorrect: false, explanation: 'Compound growth over multiple periods requires the geometric mean, which accounts for the sequence of returns.' }, { label: 'C', text: 'The terminal value of a buy-and-hold investment', isCorrect: false, explanation: 'Terminal value depends on compound growth and is best estimated using the geometric mean return.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q16', questionText: 'An investment of $10,000 grows to $12,500 over 18 months. The annualized holding period return is closest to:', answerChoices: [{ label: 'A', text: '16.0%', isCorrect: true, explanation: 'HPR = (12500-10000)/10000 = 25%. Annualized = (1.25)^(12/18) - 1 = (1.25)^(2/3) - 1 = 16.0%. We raise to the power of 1/years to annualize.' }, { label: 'B', text: '25.0%', isCorrect: false, explanation: 'This is the total 18-month HPR, not annualized. It must be adjusted for the 1.5-year holding period.' }, { label: 'C', text: '16.7%', isCorrect: false, explanation: 'This divides 25% by 1.5 years (simple division) rather than properly compounding to annualize.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q17', questionText: 'The real return on an investment with a nominal return of 8% when inflation is 3% is closest to:', answerChoices: [{ label: 'A', text: '4.85%', isCorrect: true, explanation: 'Real return = (1 + nominal)/(1 + inflation) - 1 = (1.08)/(1.03) - 1 = 4.85%. The exact Fisher equation accounts for the interaction between return and inflation.' }, { label: 'B', text: '5.00%', isCorrect: false, explanation: 'Simply subtracting inflation (8% - 3% = 5%) is an approximation that slightly overstates the real return.' }, { label: 'C', text: '11.00%', isCorrect: false, explanation: 'This adds rather than subtracts inflation from the nominal return, which is the opposite of the correct relationship.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q18', questionText: 'A leveraged return is calculated as:', answerChoices: [{ label: 'A', text: 'Portfolio return + (leverage ratio)(portfolio return - borrowing cost)', isCorrect: true, explanation: 'Leveraged return = Rp + (V_B/V_E)(Rp - r_B) where V_B/V_E is the debt-to-equity ratio. Leverage amplifies returns above borrowing cost and magnifies losses below it.' }, { label: 'B', text: 'Portfolio return divided by leverage ratio', isCorrect: false, explanation: 'Dividing by leverage would reduce returns, but leverage is meant to amplify. The formula involves multiplication of excess return.' }, { label: 'C', text: 'Portfolio return minus all interest expenses', isCorrect: false, explanation: 'This captures the cost but misses the amplification effect. The leverage formula accounts for both the borrowed amount and the spread earned on it.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q19', questionText: 'The spot rate for a 3-year zero-coupon government bond yielding 4.5% represents:', answerChoices: [{ label: 'A', text: 'The annualized return for a single payment received in exactly 3 years', isCorrect: true, explanation: 'A spot rate is the yield on a zero-coupon instrument for a specific maturity. The 3-year spot rate is the discount rate that equates the present value of a single payment received in 3 years to the current price.' }, { label: 'B', text: 'The forward rate between years 2 and 3', isCorrect: false, explanation: 'The forward rate between years 2 and 3 can be derived from spot rates but is not the spot rate itself.' }, { label: 'C', text: 'The average coupon rate on 3-year bonds', isCorrect: false, explanation: 'Spot rates apply to zero-coupon instruments and differ from coupon rates which reflect periodic payments.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q20', questionText: 'The forward rate for year 2 given spot rates of 3% for 1 year and 4% for 2 years is closest to:', answerChoices: [{ label: 'A', text: '5.01%', isCorrect: true, explanation: 'f(1,1) = [(1.04)^2/(1.03)^1] - 1 = [1.0816/1.03] - 1 = 5.01%. The forward rate ensures no-arbitrage between investing for 2 years versus 1 year then rolling over.' }, { label: 'B', text: '4.00%', isCorrect: false, explanation: 'This is the 2-year spot rate, not the implied forward rate for year 2.' }, { label: 'C', text: '3.50%', isCorrect: false, explanation: 'This is the simple average of the two spot rates, which is not how forward rates are calculated.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q21', questionText: 'The yield-to-maturity on a coupon bond represents:', answerChoices: [{ label: 'A', text: 'The internal rate of return assuming all coupons are reinvested at the YTM', isCorrect: true, explanation: 'YTM is the discount rate that equates present value of all future cash flows to the bond price. It implicitly assumes reinvestment of coupons at the same rate, which may not be realistic.' }, { label: 'B', text: 'The current yield on the bond', isCorrect: false, explanation: 'Current yield = annual coupon / price. YTM also incorporates capital gains/losses and reinvestment assumptions.' }, { label: 'C', text: 'The risk-free rate plus credit spread', isCorrect: false, explanation: 'While YTM can be decomposed this way, the definition is about the IRR of the bonds cash flows at the given price.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q22', questionText: 'The harmonic mean is most appropriate for averaging:', answerChoices: [{ label: 'A', text: 'Price-to-earnings ratios or cost averaging scenarios', isCorrect: true, explanation: 'The harmonic mean is used when averaging ratios (like P/E) or when equal dollar amounts are invested at different prices (dollar-cost averaging). It gives less weight to extreme high values.' }, { label: 'B', text: 'Annual returns on a single investment', isCorrect: false, explanation: 'Annual returns are best averaged using geometric mean (for compound growth) or arithmetic mean (for expected single period).' }, { label: 'C', text: 'Standard deviations across portfolios', isCorrect: false, explanation: 'Standard deviations are typically not averaged using harmonic mean; weighted averages or other methods are used.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q23', questionText: 'The relationship between arithmetic mean and geometric mean returns is that:', answerChoices: [{ label: 'A', text: 'The geometric mean is always less than or equal to the arithmetic mean', isCorrect: true, explanation: 'By the AM-GM inequality, the geometric mean cannot exceed the arithmetic mean. They are equal only when all returns are identical. The difference increases with return volatility.' }, { label: 'B', text: 'The arithmetic mean is always less than the geometric mean', isCorrect: false, explanation: 'This reverses the correct relationship. The arithmetic mean is always greater than or equal to the geometric mean.' }, { label: 'C', text: 'They are always equal for positive returns', isCorrect: false, explanation: 'They are equal only when all values are identical, regardless of sign. Positive but varying returns still show AM > GM.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q24', questionText: 'An investor in the 30% tax bracket earns a nominal pre-tax return of 10%. The after-tax nominal return is:', answerChoices: [{ label: 'A', text: '7.0%', isCorrect: true, explanation: 'After-tax return = pre-tax return x (1 - tax rate) = 10% x (1 - 0.30) = 7.0%. Taxes reduce the investors return by the marginal tax rate applied to the gain.' }, { label: 'B', text: '3.0%', isCorrect: false, explanation: 'This is the tax amount (10% x 0.30), not the after-tax return.' }, { label: 'C', text: '13.0%', isCorrect: false, explanation: 'This adds the tax rate to the return rather than reducing the return by the tax impact.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q25', questionText: 'The liquidity premium in the term structure of interest rates compensates investors for:', answerChoices: [{ label: 'A', text: 'The greater price risk and lower marketability of longer-term bonds', isCorrect: true, explanation: 'Longer-term bonds have higher duration (price sensitivity to rate changes) and may be harder to sell quickly. The liquidity premium increases with maturity to compensate for these risks.' }, { label: 'B', text: 'Expected inflation only', isCorrect: false, explanation: 'Expected inflation is captured by the inflation premium, not the liquidity premium.' }, { label: 'C', text: 'Default risk of the issuer', isCorrect: false, explanation: 'Default risk is compensated by the credit risk premium, which is separate from the liquidity premium.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q26', questionText: 'The gross return on an investment is 12% and management fees total 1.5%. The net return is closest to:', answerChoices: [{ label: 'A', text: '10.5%', isCorrect: true, explanation: 'Net return = gross return - fees = 12% - 1.5% = 10.5%. Net return reflects what the investor actually receives after all costs are deducted.' }, { label: 'B', text: '10.3%', isCorrect: false, explanation: 'The exact calculation (1.12/1.015 - 1) gives approximately 10.3%, but the standard approximation used in practice is simply gross minus fees.' }, { label: 'C', text: '13.5%', isCorrect: false, explanation: 'This adds fees to gross return rather than subtracting them.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q27', questionText: 'The equity risk premium represents:', answerChoices: [{ label: 'A', text: 'The additional return investors require over the risk-free rate for bearing equity market risk', isCorrect: true, explanation: 'The equity risk premium is the excess expected return on equities above the risk-free rate. It compensates for the higher uncertainty and volatility of equity investments relative to government bonds.' }, { label: 'B', text: 'The total expected return on equities', isCorrect: false, explanation: 'Total expected equity return = risk-free rate + equity risk premium. The premium is only the excess portion.' }, { label: 'C', text: 'The difference between large-cap and small-cap returns', isCorrect: false, explanation: 'The size premium is the difference between small-cap and large-cap returns, separate from the broad equity risk premium.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q28', questionText: 'A money-weighted rate of return is equivalent to:', answerChoices: [{ label: 'A', text: 'The internal rate of return (IRR) on the portfolio considering the timing and size of cash flows', isCorrect: true, explanation: 'Money-weighted return (MWRR) = IRR of all cash flows. It accounts for when and how much the investor adds or withdraws, reflecting the actual dollar experience of that specific investor.' }, { label: 'B', text: 'The time-weighted rate of return', isCorrect: false, explanation: 'Time-weighted return (TWRR) eliminates the effect of cash flow timing and measures manager performance, not investor experience.' }, { label: 'C', text: 'The geometric mean of periodic returns', isCorrect: false, explanation: 'The geometric mean of periodic returns is the time-weighted return, not the money-weighted return.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q29', questionText: 'Time-weighted rate of return is preferred over money-weighted return when evaluating:', answerChoices: [{ label: 'A', text: 'Investment manager performance because it removes the impact of client-directed cash flows', isCorrect: true, explanation: 'TWRR measures manager skill by removing the effect of cash inflows and outflows that managers do not control. It reflects pure investment decision-making performance.' }, { label: 'B', text: 'An individual investors overall wealth accumulation', isCorrect: false, explanation: 'For wealth accumulation, MWRR is more relevant as it captures the actual dollar result including timing of contributions.' }, { label: 'C', text: 'The performance of a buy-and-hold strategy only', isCorrect: false, explanation: 'TWRR is used for any actively managed portfolio evaluation, not just buy-and-hold strategies.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q30', questionText: 'A stated annual rate of 6% compounded continuously results in an effective annual rate closest to:', answerChoices: [{ label: 'A', text: '6.18%', isCorrect: true, explanation: 'EAR with continuous compounding = e^r - 1 = e^0.06 - 1 = 1.0618 - 1 = 6.18%. Continuous compounding represents the mathematical limit of increasing compounding frequency.' }, { label: 'B', text: '6.00%', isCorrect: false, explanation: 'This is the stated rate. Continuous compounding always results in an EAR above the stated rate.' }, { label: 'C', text: '6.09%', isCorrect: false, explanation: 'This corresponds to semi-annual compounding (1.03^2 - 1), not continuous compounding.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q31', questionText: 'The nominal risk-free rate can be decomposed into:', answerChoices: [{ label: 'A', text: 'Real risk-free rate plus expected inflation premium', isCorrect: true, explanation: 'The nominal risk-free rate = real risk-free rate + inflation premium. The real risk-free rate compensates for time preference, while the inflation premium maintains purchasing power.' }, { label: 'B', text: 'Default risk premium plus maturity premium', isCorrect: false, explanation: 'Default and maturity premiums are added on top of the risk-free rate for risky assets; they are not components of the risk-free rate itself.' }, { label: 'C', text: 'Equity premium plus credit spread', isCorrect: false, explanation: 'These premiums apply to risky assets above the risk-free rate, not as components of the risk-free rate.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q32', questionText: 'If the 1-year spot rate is 3% and the 2-year spot rate is 3.5%, an investor expecting the 1-year rate next year to be 3.8% should:', answerChoices: [{ label: 'A', text: 'Invest in the 2-year bond because the implied forward rate of 4.0% exceeds the expected rate of 3.8%', isCorrect: true, explanation: 'Implied forward rate = [(1.035)^2/(1.03)] - 1 = 4.0%. Since the expected future rate (3.8%) is below the forward rate (4.0%), the 2-year bond offers more value than rolling over 1-year bonds.' }, { label: 'B', text: 'Invest in 1-year bonds and roll over', isCorrect: false, explanation: 'Rolling would be preferred only if expected future rates exceed the implied forward rate. Here the forward rate (4.0%) exceeds expectations (3.8%).' }, { label: 'C', text: 'Be indifferent between the two strategies', isCorrect: false, explanation: 'Indifference occurs only when the expected future rate equals the implied forward rate, which is not the case here.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q33', questionText: 'Dollar-cost averaging results in an average cost per share that equals the:', answerChoices: [{ label: 'A', text: 'Harmonic mean of the purchase prices', isCorrect: true, explanation: 'With equal dollar investments at varying prices, the average cost per share = n / sum(1/P_i) = harmonic mean. This is always less than or equal to the arithmetic mean of prices.' }, { label: 'B', text: 'Arithmetic mean of the purchase prices', isCorrect: false, explanation: 'The arithmetic mean would apply if equal numbers of shares were purchased at each price, not equal dollar amounts.' }, { label: 'C', text: 'Geometric mean of the purchase prices', isCorrect: false, explanation: 'The geometric mean applies to compounding returns, not to averaging purchase prices in dollar-cost averaging.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q34', questionText: 'The credit risk premium in a corporate bond yield compensates investors for:', answerChoices: [{ label: 'A', text: 'The possibility that the issuer may default on interest or principal payments', isCorrect: true, explanation: 'The credit risk premium (credit spread) is the additional yield over comparable government bonds that compensates for the probability of default and expected loss given default.' }, { label: 'B', text: 'Changes in the general level of interest rates', isCorrect: false, explanation: 'Interest rate risk is common to all bonds and is not specific to credit risk. It is compensated through the maturity premium.' }, { label: 'C', text: 'Expected inflation over the bonds life', isCorrect: false, explanation: 'Expected inflation is captured in the inflation premium component of the nominal risk-free rate, not the credit spread.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q35', questionText: 'The bank discount yield on a T-bill differs from the bond equivalent yield because bank discount yield:', answerChoices: [{ label: 'A', text: 'Uses face value in the denominator and a 360-day year', isCorrect: true, explanation: 'BDY = (Face - Price)/Face x 360/days. BEY = (Face - Price)/Price x 365/days. BDY understates true yield by using face (larger than price) in the denominator and fewer days in the year.' }, { label: 'B', text: 'Accounts for compounding of interest', isCorrect: false, explanation: 'Neither BDY nor BEY accounts for compounding. Both are simple interest annualized rates.' }, { label: 'C', text: 'Uses the purchase price in the denominator', isCorrect: false, explanation: 'BDY uses face value (not price) in the denominator, which is one reason it understates the true yield.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q36', questionText: 'An investment with a net return of 6% and inflation of 2% has an approximate real after-inflation return of:', answerChoices: [{ label: 'A', text: '4.0%', isCorrect: true, explanation: 'Approximate real return = nominal return - inflation = 6% - 2% = 4%. The exact calculation (1.06/1.02 - 1 = 3.92%) is close to this approximation for small rates.' }, { label: 'B', text: '3.0%', isCorrect: false, explanation: 'This subtracts a value larger than the inflation rate from the nominal return.' }, { label: 'C', text: '8.0%', isCorrect: false, explanation: 'This adds inflation to the nominal return rather than subtracting it.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q37', questionText: 'When comparing returns across different holding periods, the most appropriate approach is to:', answerChoices: [{ label: 'A', text: 'Annualize all returns to a common time basis for comparison', isCorrect: true, explanation: 'Annualization puts all returns on the same time basis, enabling valid comparison. A 5% quarterly return and a 12% semi-annual return cannot be directly compared without annualization.' }, { label: 'B', text: 'Always compare total holding period returns regardless of time', isCorrect: false, explanation: 'Comparing a 2-month return to a 3-year return without adjusting for time is meaningless as it ignores the investment horizon.' }, { label: 'C', text: 'Only compare returns with identical holding periods', isCorrect: false, explanation: 'While ideal, investments rarely have identical periods. Annualization enables valid cross-period comparison.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q38', questionText: 'The spread between a corporate bond yield and a government bond yield of similar maturity primarily reflects:', answerChoices: [{ label: 'A', text: 'Credit risk premium and liquidity premium', isCorrect: true, explanation: 'The yield spread over treasuries compensates for both the risk of default (credit premium) and the lower trading liquidity (liquidity premium) of corporate bonds versus government bonds.' }, { label: 'B', text: 'Expected inflation only', isCorrect: false, explanation: 'Both bonds embed the same expected inflation. The spread exists because of credit and liquidity differences between the issuers.' }, { label: 'C', text: 'Differences in tax treatment only', isCorrect: false, explanation: 'While tax differences may exist, the primary drivers of credit spreads are default probability and liquidity.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q39', questionText: 'An investor deposits $5,000 at a stated annual rate of 4% compounded quarterly. After 3 years, the account value is closest to:', answerChoices: [{ label: 'A', text: '$5,634', isCorrect: true, explanation: 'FV = 5000 x (1 + 0.04/4)^(4x3) = 5000 x (1.01)^12 = 5000 x 1.1268 = $5,634. Quarterly compounding over 3 years means 12 compounding periods.' }, { label: 'B', text: '$5,624', isCorrect: false, explanation: 'This corresponds to annual compounding (5000 x 1.04^3), which produces slightly less than quarterly compounding.' }, { label: 'C', text: '$5,600', isCorrect: false, explanation: 'This uses simple interest (5000 x 1.12) without any compounding effect.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q40', questionText: 'The maturity premium compensates bond investors for:', answerChoices: [{ label: 'A', text: 'Greater interest rate risk associated with longer-duration bonds', isCorrect: true, explanation: 'Longer-maturity bonds have higher duration and greater price sensitivity to interest rate changes. The maturity premium compensates for this additional price volatility risk.' }, { label: 'B', text: 'The probability of issuer default', isCorrect: false, explanation: 'Default probability is captured by the credit risk premium, not the maturity premium.' }, { label: 'C', text: 'Expected changes in inflation', isCorrect: false, explanation: 'Expected inflation is incorporated in the inflation premium, which is a separate component of required return.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q41', questionText: 'A portfolio has two assets: Asset X with weight 70% and return 8%, Asset Y with weight 30% and return 12%. The portfolio return is:', answerChoices: [{ label: 'A', text: '9.2%', isCorrect: true, explanation: 'Portfolio return = 0.70 x 8% + 0.30 x 12% = 5.6% + 3.6% = 9.2%. Weighted average of component returns gives the portfolio return.' }, { label: 'B', text: '10.0%', isCorrect: false, explanation: 'This is the simple average of 8% and 12%, ignoring the unequal weights.' }, { label: 'C', text: '8.6%', isCorrect: false, explanation: 'This incorrectly applies the weights in reverse (30% to 8% and 70% to 12% gives 11.2%, not 8.6%).' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q42', questionText: 'The continuously compounded rate that corresponds to an EAR of 5.127% is closest to:', answerChoices: [{ label: 'A', text: '5.00%', isCorrect: true, explanation: 'Continuous rate = ln(1 + EAR) = ln(1.05127) = 0.0500 = 5.00%. The continuously compounded rate is the natural log of (1 + effective rate).' }, { label: 'B', text: '5.127%', isCorrect: false, explanation: 'This is the EAR itself. The continuously compounded equivalent is always lower than the effective annual rate.' }, { label: 'C', text: '4.88%', isCorrect: false, explanation: 'This understates the continuously compounded rate for this given EAR.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q43', questionText: 'The holding period yield on a 91-day T-bill purchased at $99.50 and redeemed at $100 is closest to:', answerChoices: [{ label: 'A', text: '0.503%', isCorrect: true, explanation: 'HPY = (100 - 99.50) / 99.50 = 0.50/99.50 = 0.503%. The holding period yield uses the purchase price as the base, not face value.' }, { label: 'B', text: '0.500%', isCorrect: false, explanation: 'This uses face value ($100) rather than purchase price ($99.50) in the denominator, which is the bank discount approach.' }, { label: 'C', text: '2.01%', isCorrect: false, explanation: 'This appears to annualize the return rather than reporting the holding period yield for the 91 days.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q44', questionText: 'For the purpose of GIPS compliance, the time-weighted rate of return is required because it:', answerChoices: [{ label: 'A', text: 'Removes the impact of external cash flows that managers cannot control', isCorrect: true, explanation: 'GIPS requires TWRR because it measures pure investment decision performance. Since managers typically cannot control when clients add or withdraw funds, TWRR provides a fair basis for comparing managers.' }, { label: 'B', text: 'Is easier to calculate than money-weighted return', isCorrect: false, explanation: 'TWRR is actually more difficult to calculate (requires portfolio valuation at each cash flow date). It is preferred for fairness, not simplicity.' }, { label: 'C', text: 'Always shows higher returns than money-weighted', isCorrect: false, explanation: 'TWRR can be higher or lower than MWRR depending on the timing of cash flows relative to performance.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q45', questionText: 'A bond has a quoted price of 98.5 per 100 of par value and 45 days of accrued interest at a coupon rate of 6% (semi-annual). The full (dirty) price is closest to:', answerChoices: [{ label: 'A', text: '99.24', isCorrect: true, explanation: 'Accrued interest = (6/2) x (45/180) = 3 x 0.25 = 0.75. Full price = Clean price + Accrued interest = 98.5 + 0.75 = 99.25 (approximately 99.24 with actual/actual). The dirty price includes compensation for interest earned but not yet paid.' }, { label: 'B', text: '98.50', isCorrect: false, explanation: 'This is the clean (flat) price which excludes accrued interest. The full price must include accrued interest.' }, { label: 'C', text: '101.50', isCorrect: false, explanation: 'This overstates the accrued interest by adding half the annual coupon rather than the proportional amount.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q46', questionText: 'The annualized return on a 6-month investment that earned 4% over the period is closest to:', answerChoices: [{ label: 'A', text: '8.16%', isCorrect: true, explanation: 'Annualized return = (1 + 0.04)^(12/6) - 1 = (1.04)^2 - 1 = 8.16%. Compounding the semi-annual return over two periods gives the annual equivalent.' }, { label: 'B', text: '8.00%', isCorrect: false, explanation: 'Simply doubling (4% x 2) ignores the compounding effect and understates the annualized return.' }, { label: 'C', text: '4.00%', isCorrect: false, explanation: 'This is the 6-month holding period return, not the annualized rate.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q47', questionText: 'A required margin on a leveraged position serves to:', answerChoices: [{ label: 'A', text: 'Limit the potential loss to the lender by requiring the borrower to maintain minimum equity', isCorrect: true, explanation: 'Margin requirements protect the lender by ensuring the investor has sufficient equity. If the position loses value, margin calls require additional capital to maintain the minimum equity-to-asset ratio.' }, { label: 'B', text: 'Guarantee the investor will earn a positive return', isCorrect: false, explanation: 'Margin does not guarantee positive returns. Leveraged positions can still result in losses, even total loss of equity.' }, { label: 'C', text: 'Eliminate all leverage from the position', isCorrect: false, explanation: 'Margin facilitates leverage rather than eliminating it. It simply sets a floor on the investors own capital contribution.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q48', questionText: 'The effect of leverage on portfolio return is that it:', answerChoices: [{ label: 'A', text: 'Amplifies both gains and losses relative to an unlevered position', isCorrect: true, explanation: 'Leverage magnifies returns in both directions. If the portfolio earns above the borrowing cost, leverage increases returns. If it earns below, leverage increases losses. Risk and return both increase.' }, { label: 'B', text: 'Only amplifies gains while limiting losses', isCorrect: false, explanation: 'Leverage increases both upside and downside symmetrically. Only options provide asymmetric payoffs (limited downside with upside potential).' }, { label: 'C', text: 'Has no effect if borrowing costs are low', isCorrect: false, explanation: 'Even with zero borrowing costs, leverage amplifies both positive and negative portfolio returns by the leverage factor.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q49', questionText: 'The return on a leveraged investment with equity of $50,000, borrowed funds of $50,000 at 5%, and a portfolio return of 12% is closest to:', answerChoices: [{ label: 'A', text: '19.0%', isCorrect: true, explanation: 'Leveraged return = Portfolio return + (Debt/Equity)(Portfolio return - Borrowing cost) = 12% + (50/50)(12% - 5%) = 12% + 7% = 19%. Leverage adds the spread earned on borrowed funds.' }, { label: 'B', text: '12.0%', isCorrect: false, explanation: 'This is the unlevered portfolio return, not the return on equity in the leveraged position.' }, { label: 'C', text: '7.0%', isCorrect: false, explanation: 'This is the spread between portfolio return and borrowing cost, but not the total return to equity.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q50', questionText: 'The money-weighted return will exceed the time-weighted return when:', answerChoices: [{ label: 'A', text: 'Larger contributions are made before periods of relatively high returns', isCorrect: true, explanation: 'MWRR exceeds TWRR when more money is invested during high-return periods. Good cash flow timing (investing more before good periods) makes the dollar-weighted experience better than the pure time-weighted measure.' }, { label: 'B', text: 'Returns are constant across all periods', isCorrect: false, explanation: 'When returns are constant, MWRR equals TWRR regardless of cash flow timing.' }, { label: 'C', text: 'No additional investments are made after the initial contribution', isCorrect: false, explanation: 'With only one initial investment (no subsequent cash flows), MWRR equals TWRR because there is no timing effect.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q51', questionText: 'A zero-coupon bond purchased for $925 with a par value of $1,000 maturing in 2 years has an annualized yield closest to:', answerChoices: [{ label: 'A', text: '3.97%', isCorrect: true, explanation: 'Yield = (1000/925)^(1/2) - 1 = (1.0811)^0.5 - 1 = 3.97%. For zero-coupon bonds, the yield is the annualized rate that equates purchase price to future par value.' }, { label: 'B', text: '8.11%', isCorrect: false, explanation: 'This is the total 2-year holding period return (75/925), not the annualized yield.' }, { label: 'C', text: '4.05%', isCorrect: false, explanation: 'This divides the total return by 2 (simple division) rather than taking the geometric annualization.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q52', questionText: 'The required return on an asset using the build-up method equals:', answerChoices: [{ label: 'A', text: 'Real risk-free rate + inflation premium + default risk premium + liquidity premium + maturity premium', isCorrect: true, explanation: 'The build-up method adds various premiums to the base real risk-free rate. Each premium compensates for a specific source of risk that the investor bears.' }, { label: 'B', text: 'CAPM expected return only', isCorrect: false, explanation: 'CAPM uses beta and market risk premium, which is a different approach from the build-up method that adds individual risk premiums.' }, { label: 'C', text: 'Dividend yield plus growth rate', isCorrect: false, explanation: 'This is the Gordon Growth Model for stock valuation, not the build-up method for required return.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q53', questionText: 'When the money-weighted return is lower than the time-weighted return, the investor most likely:', answerChoices: [{ label: 'A', text: 'Made additional investments before periods of poor performance', isCorrect: true, explanation: 'MWRR < TWRR implies bad timing: the investor added money just before losses or withdrew money before gains. This poor timing made their actual dollar experience worse than the pure investment performance.' }, { label: 'B', text: 'Withdrew funds before market downturns', isCorrect: false, explanation: 'Withdrawing before downturns represents good timing, which would make MWRR exceed TWRR, not fall below it.' }, { label: 'C', text: 'Maintained a constant investment amount throughout', isCorrect: false, explanation: 'Constant investment amounts would make MWRR approximately equal to TWRR, not lower.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q54', questionText: 'The effective annual rate for a stated rate of 10% compounded daily (365 days) is closest to:', answerChoices: [{ label: 'A', text: '10.52%', isCorrect: true, explanation: 'EAR = (1 + 0.10/365)^365 - 1 = 10.52%. Daily compounding produces an EAR very close to continuous compounding (e^0.10 - 1 = 10.52%).' }, { label: 'B', text: '10.25%', isCorrect: false, explanation: 'This corresponds to quarterly compounding, not daily.' }, { label: 'C', text: '10.00%', isCorrect: false, explanation: 'This is the stated rate. Any compounding frequency greater than annual will produce an EAR above the stated rate.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m1-q55', questionText: 'An investment that costs $1,000 today and pays $1,100 in one year has a stated annual return of 10%. If inflation is 4%, the real wealth increase is closest to:', answerChoices: [{ label: 'A', text: '$57.69', isCorrect: true, explanation: 'Real return = (1.10/1.04) - 1 = 5.77%. Real wealth increase = $1,000 x 5.77% = $57.69. Only the real return represents actual purchasing power gain.' }, { label: 'B', text: '$100.00', isCorrect: false, explanation: 'This is the nominal gain. After adjusting for 4% inflation, the real purchasing power gain is lower.' }, { label: 'C', text: '$60.00', isCorrect: false, explanation: 'This uses the approximation (10% - 4% = 6% of $1,000 = $60), which slightly overstates the exact real gain.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Rates and Returns', provider: 'cfa-portal', questionSourceFile: null },
];

// Module 2: Time Value of Money in Finance (21 questions)
const module2Questions: Question[] = [
  { id: 'qm-m2-q1', questionText: 'The present value of $10,000 to be received in 5 years at a discount rate of 6% is closest to:', answerChoices: [{ label: 'A', text: '$7,473', isCorrect: true, explanation: 'PV = 10,000 / (1.06)^5 = 10,000 / 1.3382 = $7,473. Present value discounts the future amount by the opportunity cost of capital over the time period.' }, { label: 'B', text: '$7,000', isCorrect: false, explanation: 'This subtracts simple interest (5 x 6% = 30% of $10,000 = $3,000) rather than using compound discounting.' }, { label: 'C', text: '$8,000', isCorrect: false, explanation: 'This understates the discounting effect over 5 years at 6%.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q2', questionText: 'A perpetuity pays $500 per year. At a discount rate of 8%, its present value is closest to:', answerChoices: [{ label: 'A', text: '$6,250', isCorrect: true, explanation: 'PV of perpetuity = PMT / r = 500 / 0.08 = $6,250. A perpetuity is an infinite stream of equal payments, valued simply as payment divided by discount rate.' }, { label: 'B', text: '$4,000', isCorrect: false, explanation: 'This uses an incorrect discount rate or formula to value the perpetuity.' }, { label: 'C', text: '$62,500', isCorrect: false, explanation: 'This divides by 0.008 instead of 0.08, overstating the value by a factor of 10.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q3', questionText: 'An annuity pays $2,000 at the end of each year for 10 years. At a discount rate of 5%, the present value is closest to:', answerChoices: [{ label: 'A', text: '$15,443', isCorrect: true, explanation: 'PV = PMT x [(1 - (1+r)^-n) / r] = 2000 x [(1 - 1.05^-10) / 0.05] = 2000 x 7.7217 = $15,443. The annuity factor converts the stream of payments to present value.' }, { label: 'B', text: '$20,000', isCorrect: false, explanation: 'This is the undiscounted sum (2000 x 10) which ignores the time value of money entirely.' }, { label: 'C', text: '$12,578', isCorrect: false, explanation: 'This understates the present value, possibly by using an incorrect discount rate or period.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q4', questionText: 'The future value of $5,000 invested for 8 years at 7% compounded annually is closest to:', answerChoices: [{ label: 'A', text: '$8,590', isCorrect: true, explanation: 'FV = 5000 x (1.07)^8 = 5000 x 1.7182 = $8,590. Compound growth over 8 years at 7% increases the initial investment by a factor of 1.7182.' }, { label: 'B', text: '$7,800', isCorrect: false, explanation: 'This uses simple interest (5000 x 1.56) rather than compound growth.' }, { label: 'C', text: '$9,000', isCorrect: false, explanation: 'This overstates the compound growth factor for 8 years at 7%.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q5', questionText: 'An annuity due differs from an ordinary annuity in that payments occur:', answerChoices: [{ label: 'A', text: 'At the beginning of each period rather than the end', isCorrect: true, explanation: 'An annuity due has payments at the start of each period. Its present value equals the ordinary annuity PV multiplied by (1 + r) because each payment is received one period earlier.' }, { label: 'B', text: 'At the end of each period with a lump sum at maturity', isCorrect: false, explanation: 'This describes a bond with coupon payments and principal at maturity, not an annuity due.' }, { label: 'C', text: 'Only once at the beginning of the investment', isCorrect: false, explanation: 'A single payment at the start is a lump sum, not an annuity due which involves multiple periodic payments.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q6', questionText: 'The present value of a growing perpetuity with a first payment of $100, growth rate of 3%, and discount rate of 8% is closest to:', answerChoices: [{ label: 'A', text: '$2,000', isCorrect: true, explanation: 'PV of growing perpetuity = PMT / (r - g) = 100 / (0.08 - 0.03) = 100 / 0.05 = $2,000. The growth rate reduces the effective discount rate in the denominator.' }, { label: 'B', text: '$1,250', isCorrect: false, explanation: 'This uses the full discount rate (100/0.08) without adjusting for growth.' }, { label: 'C', text: '$3,333', isCorrect: false, explanation: 'This uses only the growth rate in the denominator (100/0.03) rather than the spread between discount rate and growth.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q7', questionText: 'A loan of $200,000 at 6% annual interest requires equal annual payments over 30 years. The annual payment is closest to:', answerChoices: [{ label: 'A', text: '$14,530', isCorrect: true, explanation: 'PMT = PV / annuity factor = 200,000 / [(1 - 1.06^-30) / 0.06] = 200,000 / 13.7648 = $14,530. The annuity payment formula ensures the loan is fully amortized over 30 years.' }, { label: 'B', text: '$12,000', isCorrect: false, explanation: 'This is only the annual interest (200,000 x 0.06) without any principal repayment.' }, { label: 'C', text: '$6,667', isCorrect: false, explanation: 'This divides principal by years (200,000/30) without including interest, which is not how amortization works.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q8', questionText: 'The net present value (NPV) of a project is positive when:', answerChoices: [{ label: 'A', text: 'The present value of future cash inflows exceeds the initial investment cost', isCorrect: true, explanation: 'NPV > 0 means the project generates value above the required return. The discounted cash flows exceed the cost, creating economic profit for the firm.' }, { label: 'B', text: 'The payback period is less than the project life', isCorrect: false, explanation: 'A short payback period does not guarantee positive NPV because payback ignores cash flows after the cutoff and does not discount.' }, { label: 'C', text: 'The accounting rate of return exceeds zero', isCorrect: false, explanation: 'Accounting returns use book values and do not incorporate time value of money, so they may not align with NPV.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q9', questionText: 'The internal rate of return (IRR) is the discount rate at which:', answerChoices: [{ label: 'A', text: 'The net present value of a project equals zero', isCorrect: true, explanation: 'IRR is the breakeven discount rate. At the IRR, the present value of inflows exactly equals outflows. Projects with IRR above the required return have positive NPV.' }, { label: 'B', text: 'The future value of a project equals the initial investment', isCorrect: false, explanation: 'This is not the definition of IRR. IRR sets NPV (not FV comparison) to zero.' }, { label: 'C', text: 'The project generates maximum cash flow', isCorrect: false, explanation: 'IRR is a discount rate concept, not a measure of cash flow magnitude. It identifies the return embedded in the projects cash flow pattern.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q10', questionText: 'When NPV and IRR give conflicting rankings for mutually exclusive projects, the analyst should prefer:', answerChoices: [{ label: 'A', text: 'The NPV rule because it directly measures value creation', isCorrect: true, explanation: 'NPV is preferred because it measures absolute value added to the firm. IRR measures percentage return but can give misleading rankings due to reinvestment rate assumptions and scale differences.' }, { label: 'B', text: 'The IRR rule because percentage returns are always more informative', isCorrect: false, explanation: 'IRR can mislead with mutually exclusive projects of different sizes or timing. A smaller project might have higher IRR but lower NPV (less value creation).' }, { label: 'C', text: 'Neither, and the project should be rejected', isCorrect: false, explanation: 'Conflicting rankings do not mean both projects are bad. The analyst uses NPV to choose the project that creates more shareholder value.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q11', questionText: 'A deferred annuity with the first payment occurring in year 4, paying $1,000 per year for 5 years at 6%, has a present value (at t=0) closest to:', answerChoices: [{ label: 'A', text: '$3,539', isCorrect: true, explanation: 'PV at t=3 = 1000 x [(1 - 1.06^-5)/0.06] = $4,212. PV at t=0 = 4,212/(1.06)^3 = $3,539. First discount the annuity to one period before the first payment, then discount back to today.' }, { label: 'B', text: '$4,212', isCorrect: false, explanation: 'This is the value at t=3, not t=0. It needs to be discounted back 3 more years to the present.' }, { label: 'C', text: '$5,000', isCorrect: false, explanation: 'This is the undiscounted sum of payments (5 x $1,000) ignoring all time value of money effects.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q12', questionText: 'The future value of an ordinary annuity of $3,000 per year for 6 years at 5% is closest to:', answerChoices: [{ label: 'A', text: '$20,406', isCorrect: true, explanation: 'FV = PMT x [((1+r)^n - 1) / r] = 3000 x [(1.05^6 - 1)/0.05] = 3000 x 6.8019 = $20,406. The future value annuity factor compounds each payment to the end of year 6.' }, { label: 'B', text: '$18,000', isCorrect: false, explanation: 'This is the simple sum without any compounding (3000 x 6 = 18,000).' }, { label: 'C', text: '$21,426', isCorrect: false, explanation: 'This uses the annuity due factor which would add one extra period of compounding to each payment.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q13', questionText: 'The present value of a series of unequal cash flows must be calculated by:', answerChoices: [{ label: 'A', text: 'Discounting each individual cash flow to the present and summing them', isCorrect: true, explanation: 'Unlike annuities, unequal cash flows cannot use a single annuity factor. Each cash flow is discounted at PV = CF_t / (1+r)^t and then all present values are summed.' }, { label: 'B', text: 'Using the ordinary annuity formula with the average cash flow', isCorrect: false, explanation: 'Averaging unequal cash flows and using annuity formula introduces error because the timing-weighted present values differ from the average-based calculation.' }, { label: 'C', text: 'Discounting only the largest cash flow', isCorrect: false, explanation: 'All cash flows contribute to present value, not just the largest. Each must be individually discounted.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q14', questionText: 'A mortgage payment includes both interest and principal. In the early years of a mortgage:', answerChoices: [{ label: 'A', text: 'The interest portion is larger and the principal portion is smaller', isCorrect: true, explanation: 'In an amortizing loan, interest is calculated on the outstanding balance. Early on, the balance is highest so interest is large. As principal is paid down, interest decreases and principal repayment increases.' }, { label: 'B', text: 'The principal portion is larger and the interest portion is smaller', isCorrect: false, explanation: 'This describes the later years of a mortgage when the balance is low, not the early years when the balance is high.' }, { label: 'C', text: 'Interest and principal are always equal throughout the loan', isCorrect: false, explanation: 'Only in very specific loan structures are payments split equally. Standard amortizing loans have changing proportions over time.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q15', questionText: 'The opportunity cost in a net present value calculation represents:', answerChoices: [{ label: 'A', text: 'The return that could be earned on an alternative investment of similar risk', isCorrect: true, explanation: 'The discount rate in NPV reflects the opportunity cost of capital: what investors could earn elsewhere at the same risk level. It ensures the project exceeds this minimum acceptable return.' }, { label: 'B', text: 'The accounting cost of the investment', isCorrect: false, explanation: 'Accounting costs are explicit cash outlays. Opportunity cost is an implicit cost representing foregone alternatives.' }, { label: 'C', text: 'The sunk cost of previous investments', isCorrect: false, explanation: 'Sunk costs are irrelevant to NPV analysis. Only future incremental cash flows and the opportunity cost of capital matter.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q16', questionText: 'The rule of 72 estimates that an investment will double in value in approximately:', answerChoices: [{ label: 'A', text: '72 divided by the interest rate (in percent)', isCorrect: true, explanation: 'Rule of 72: Years to double = 72 / r%. At 8%, doubling takes approximately 72/8 = 9 years. The exact answer is ln(2)/ln(1.08) = 9.01 years, confirming the approximation.' }, { label: 'B', text: '72 multiplied by the interest rate', isCorrect: false, explanation: 'Multiplying would give an enormous number. The rule divides 72 by the rate to estimate years to double.' }, { label: 'C', text: '72 years regardless of the interest rate', isCorrect: false, explanation: 'The doubling time depends on the interest rate. Higher rates double faster (72/12 = 6 years vs 72/4 = 18 years).' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q17', questionText: 'A savings plan requires deposits of $500 at the beginning of each month for 5 years at 6% annual rate (0.5% monthly). The future value is closest to:', answerChoices: [{ label: 'A', text: '$35,046', isCorrect: true, explanation: 'This is an annuity due (beginning of period). FV = 500 x [(1.005^60 - 1)/0.005] x 1.005 = 500 x 69.77 x 1.005 = $35,046. The extra (1+r) factor adjusts for beginning-of-period payments.' }, { label: 'B', text: '$34,872', isCorrect: false, explanation: 'This would be the ordinary annuity (end of period) FV without the annuity due adjustment.' }, { label: 'C', text: '$30,000', isCorrect: false, explanation: 'This is the simple sum of deposits (500 x 60) without any interest compounding.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q18', questionText: 'The present value of a growing annuity with first payment $1,000, growth rate 4%, discount rate 9%, and 20 payments is closest to:', answerChoices: [{ label: 'A', text: '$12,689', isCorrect: true, explanation: 'PV = [PMT / (r - g)] x [1 - ((1+g)/(1+r))^n] = [1000/(0.09-0.04)] x [1 - (1.04/1.09)^20] = 20,000 x 0.6345 = $12,689. The growing annuity formula adjusts for both discounting and payment growth.' }, { label: 'B', text: '$20,000', isCorrect: false, explanation: 'This is the growing perpetuity value (PMT/(r-g)) which assumes infinite payments, not 20.' }, { label: 'C', text: '$10,000', isCorrect: false, explanation: 'This understates the value by not properly accounting for the growth in payments over 20 years.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q19', questionText: 'An investment project has an IRR of 12% and the firms cost of capital is 10%. The project should be:', answerChoices: [{ label: 'A', text: 'Accepted because IRR exceeds the required rate of return', isCorrect: true, explanation: 'When IRR > cost of capital, the project returns more than the minimum required rate. This is equivalent to a positive NPV, indicating value creation for shareholders.' }, { label: 'B', text: 'Rejected because the spread is only 2%', isCorrect: false, explanation: 'The accept/reject decision is based on whether IRR exceeds the hurdle rate, not on the size of the spread (though spread size indicates the margin of safety).' }, { label: 'C', text: 'Deferred until rates change', isCorrect: false, explanation: 'Deferring may be rational with optionality, but based on standard IRR rule, the project should be accepted now since IRR > cost of capital.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q20', questionText: 'The present value of a 5-year annuity due paying $4,000 annually at 7% discount rate is closest to:', answerChoices: [{ label: 'A', text: '$17,532', isCorrect: true, explanation: 'PV ordinary annuity = 4000 x [(1 - 1.07^-5)/0.07] = 4000 x 4.1002 = $16,401. PV annuity due = $16,401 x 1.07 = $17,549 (approximately $17,532 with rounding). Annuity due multiplies by (1+r).' }, { label: 'B', text: '$16,401', isCorrect: false, explanation: 'This is the ordinary annuity (end of period) PV. The annuity due requires multiplying by (1+r) since payments come at the beginning.' }, { label: 'C', text: '$20,000', isCorrect: false, explanation: 'This is the undiscounted sum of payments (4000 x 5) ignoring time value of money.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m2-q21', questionText: 'Capital budgeting cash flows should be estimated on:', answerChoices: [{ label: 'A', text: 'An incremental after-tax basis, excluding sunk costs and including opportunity costs', isCorrect: true, explanation: 'Proper NPV analysis uses only incremental cash flows caused by the project, after taxes. Sunk costs are irrelevant (already spent), but opportunity costs represent real economic sacrifice and must be included.' }, { label: 'B', text: 'A total firm revenue basis including all overhead allocations', isCorrect: false, explanation: 'Total revenue ignores the incremental principle. Only cash flows that change because of the project are relevant.' }, { label: 'C', text: 'A pre-tax basis to simplify the analysis', isCorrect: false, explanation: 'Pre-tax analysis is incorrect because taxes are a real cash outflow. After-tax cash flows reflect what the firm actually receives.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Time Value of Money in Finance', provider: 'cfa-portal', questionSourceFile: null },
];

// Module 3: Statistical Measures of Asset Returns (37 questions)
const module3Questions: Question[] = [
  { id: 'qm-m3-q1', questionText: 'The population mean is best described as:', answerChoices: [{ label: 'A', text: 'The arithmetic average of all values in the entire population', isCorrect: true, explanation: 'The population mean (mu) sums all N values and divides by N. It is a parameter (fixed, usually unknown) unlike the sample mean which is a statistic.' }, { label: 'B', text: 'The middle value when data is sorted', isCorrect: false, explanation: 'The middle value of sorted data is the median, not the mean.' }, { label: 'C', text: 'The most frequently occurring value', isCorrect: false, explanation: 'The most frequent value is the mode, not the mean.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q2', questionText: 'The variance of a data set measures:', answerChoices: [{ label: 'A', text: 'The average squared deviation from the mean', isCorrect: true, explanation: 'Variance = sum of squared deviations / N (population) or N-1 (sample). Squaring ensures deviations do not cancel and emphasizes larger deviations.' }, { label: 'B', text: 'The range of the data', isCorrect: false, explanation: 'Range is simply max minus min. Variance uses all data points and their deviations from the mean.' }, { label: 'C', text: 'The difference between the mean and median', isCorrect: false, explanation: 'The mean-median difference relates to skewness, not variance.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q3', questionText: 'A sample standard deviation uses n-1 in the denominator rather than n because:', answerChoices: [{ label: 'A', text: 'It corrects for the downward bias in estimating the population variance from a sample', isCorrect: true, explanation: 'Using n-1 (Bessel correction) provides an unbiased estimator of population variance. With n in the denominator, the sample variance systematically underestimates the true population variance.' }, { label: 'B', text: 'It makes the calculation simpler', isCorrect: false, explanation: 'Using n-1 actually makes computation slightly more complex. The reason is statistical bias correction, not simplicity.' }, { label: 'C', text: 'Samples always have one outlier that should be excluded', isCorrect: false, explanation: 'The n-1 correction has nothing to do with outliers. It accounts for the loss of one degree of freedom when the sample mean is used.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q4', questionText: 'The coefficient of variation (CV) is most useful for:', answerChoices: [{ label: 'A', text: 'Comparing relative dispersion between data sets with different means or units', isCorrect: true, explanation: 'CV = standard deviation / mean. It normalizes risk per unit of return, enabling comparison of assets with different expected returns or data measured in different units.' }, { label: 'B', text: 'Measuring the direction of the relationship between two variables', isCorrect: false, explanation: 'Correlation measures directional relationships. CV measures relative variability within a single variable.' }, { label: 'C', text: 'Identifying the most common value in a distribution', isCorrect: false, explanation: 'The mode identifies the most common value. CV measures dispersion relative to the mean.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q5', questionText: 'A distribution with a long right tail is described as:', answerChoices: [{ label: 'A', text: 'Positively skewed (right-skewed)', isCorrect: true, explanation: 'Positive skewness means the right tail is longer/fatter. The mean exceeds the median for positively skewed data. Investment returns often show negative skewness (left-tail risk).' }, { label: 'B', text: 'Negatively skewed (left-skewed)', isCorrect: false, explanation: 'Negative skewness has a longer left tail, meaning extreme negative values are more likely. This distribution has a longer right tail.' }, { label: 'C', text: 'Leptokurtic', isCorrect: false, explanation: 'Leptokurtic refers to excess kurtosis (fat tails on both sides), not the asymmetry described by skewness.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q6', questionText: 'Excess kurtosis measures:', answerChoices: [{ label: 'A', text: 'The degree to which a distribution has fatter or thinner tails than a normal distribution', isCorrect: true, explanation: 'Excess kurtosis = kurtosis - 3 (where 3 is normal distribution kurtosis). Positive excess kurtosis (leptokurtic) means fatter tails and more extreme outcomes than normal.' }, { label: 'B', text: 'The degree of asymmetry in the distribution', isCorrect: false, explanation: 'Asymmetry is measured by skewness, not kurtosis. Kurtosis is about tail thickness and peak height.' }, { label: 'C', text: 'The spread between the 25th and 75th percentiles', isCorrect: false, explanation: 'The interquartile range (IQR) measures the spread between these percentiles, not kurtosis.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q7', questionText: 'For a positively skewed distribution, the relationship among the mean, median, and mode is:', answerChoices: [{ label: 'A', text: 'Mean > Median > Mode', isCorrect: true, explanation: 'Positive skew pulls the mean to the right (toward the long tail). The median is between mean and mode. The mode is at the peak. This ordering holds for unimodal positively skewed distributions.' }, { label: 'B', text: 'Mean < Median < Mode', isCorrect: false, explanation: 'This ordering describes negative skewness where the left tail pulls the mean below the median and mode.' }, { label: 'C', text: 'Mean = Median = Mode', isCorrect: false, explanation: 'Equal values occur only in a perfectly symmetric distribution (zero skewness).' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q8', questionText: 'The interquartile range (IQR) equals:', answerChoices: [{ label: 'A', text: 'The third quartile minus the first quartile (Q3 - Q1)', isCorrect: true, explanation: 'IQR = Q3 - Q1 and captures the middle 50% of the data. It is robust to outliers unlike range or standard deviation, making it useful for skewed distributions.' }, { label: 'B', text: 'The maximum minus the minimum value', isCorrect: false, explanation: 'Maximum minus minimum is the range, not the interquartile range. IQR excludes the extreme 25% on each end.' }, { label: 'C', text: 'The mean minus the median', isCorrect: false, explanation: 'Mean minus median relates to skewness measurement, not dispersion as measured by IQR.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q9', questionText: 'The Sharpe ratio measures:', answerChoices: [{ label: 'A', text: 'Excess return per unit of total risk (standard deviation)', isCorrect: true, explanation: 'Sharpe ratio = (Rp - Rf) / sigma_p. It measures how much excess return (above risk-free) an investor earns per unit of total volatility. Higher is better.' }, { label: 'B', text: 'Excess return per unit of systematic risk (beta)', isCorrect: false, explanation: 'Excess return per unit of beta is the Treynor ratio, not the Sharpe ratio.' }, { label: 'C', text: 'The correlation between portfolio and benchmark returns', isCorrect: false, explanation: 'Correlation measures co-movement direction and strength, not risk-adjusted return.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q10', questionText: 'A leptokurtic return distribution (excess kurtosis > 0) implies:', answerChoices: [{ label: 'A', text: 'A higher probability of extreme returns (both positive and negative) compared to normal', isCorrect: true, explanation: 'Leptokurtic distributions have fatter tails, meaning extreme events occur more frequently than a normal distribution predicts. This is common in financial returns and is important for risk management.' }, { label: 'B', text: 'Returns are more concentrated around the mean with thinner tails', isCorrect: false, explanation: 'Thinner tails and more concentration describes platykurtic (negative excess kurtosis), not leptokurtic.' }, { label: 'C', text: 'The distribution is symmetric', isCorrect: false, explanation: 'Kurtosis can exist in both symmetric and asymmetric distributions. It measures tail weight, not symmetry.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q11', questionText: 'The correlation coefficient between two assets can range from:', answerChoices: [{ label: 'A', text: '-1 to +1', isCorrect: true, explanation: 'Correlation is bounded between -1 (perfect negative linear relationship) and +1 (perfect positive linear relationship). Zero indicates no linear relationship.' }, { label: 'B', text: '0 to +1', isCorrect: false, explanation: 'Correlation can be negative when assets move in opposite directions. The range includes negative values.' }, { label: 'C', text: '-infinity to +infinity', isCorrect: false, explanation: 'Correlation is bounded by -1 and +1 by construction (it is covariance normalized by standard deviations).' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q12', questionText: 'Covariance between two assets equals:', answerChoices: [{ label: 'A', text: 'The expected value of the product of their deviations from their respective means', isCorrect: true, explanation: 'Cov(X,Y) = E[(X - mu_X)(Y - mu_Y)]. Positive covariance means they tend to move together; negative means they move oppositely.' }, { label: 'B', text: 'The product of their standard deviations', isCorrect: false, explanation: 'Product of standard deviations is the denominator in correlation calculation. Covariance = correlation x product of standard deviations.' }, { label: 'C', text: 'The sum of their variances', isCorrect: false, explanation: 'Sum of variances relates to portfolio variance only when covariance is zero (independent assets).' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q13', questionText: 'The median is preferred over the mean as a measure of central tendency when:', answerChoices: [{ label: 'A', text: 'The data contains extreme outliers that would distort the mean', isCorrect: true, explanation: 'The median is resistant to outliers because it depends only on the middle position. The mean uses all values and can be pulled far from the center by even a single extreme observation.' }, { label: 'B', text: 'The data is perfectly symmetric', isCorrect: false, explanation: 'For symmetric data, the mean and median are equal, so there is no advantage to either.' }, { label: 'C', text: 'You want to use the measure in further statistical calculations', isCorrect: false, explanation: 'The mean has superior mathematical properties for further analysis (variance calculations, hypothesis tests). The median is preferred only for robustness to outliers.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q14', questionText: 'A distribution with negative skewness has:', answerChoices: [{ label: 'A', text: 'A longer left tail with more frequent small gains and occasional large losses', isCorrect: true, explanation: 'Negative skewness means extreme negative returns are more likely than extreme positive ones. For investors, this increases downside risk beyond what standard deviation alone captures.' }, { label: 'B', text: 'A longer right tail with occasional large gains', isCorrect: false, explanation: 'Longer right tail describes positive skewness (desirable for investors), not negative skewness.' }, { label: 'C', text: 'Symmetric tails on both sides', isCorrect: false, explanation: 'Symmetric tails indicate zero skewness, not negative skewness.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q15', questionText: 'The sample covariance uses n-1 in the denominator to:', answerChoices: [{ label: 'A', text: 'Provide an unbiased estimator of the population covariance', isCorrect: true, explanation: 'Like sample variance, sample covariance divides by (n-1) for the degrees of freedom correction. Using n would systematically underestimate the true population covariance.' }, { label: 'B', text: 'Make it comparable to standard deviation', isCorrect: false, explanation: 'The denominator adjustment is about unbiasedness, not comparability with other statistics.' }, { label: 'C', text: 'Account for the number of variables', isCorrect: false, explanation: 'The n-1 accounts for degrees of freedom lost in estimating means, not for the number of variables.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q16', questionText: 'The 75th percentile of a data set indicates that:', answerChoices: [{ label: 'A', text: '75% of the observations fall at or below this value', isCorrect: true, explanation: 'Percentiles indicate the relative standing of a value. The 75th percentile (third quartile) has 75% of observations at or below it and 25% above it.' }, { label: 'B', text: '75% of observations are above this value', isCorrect: false, explanation: 'This reverses the definition. The 75th percentile has 75% below, not above.' }, { label: 'C', text: 'The value equals 75% of the maximum', isCorrect: false, explanation: 'Percentiles are about ranking position in the data, not about being a fraction of the maximum value.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q17', questionText: 'The Sortino ratio differs from the Sharpe ratio in that the Sortino ratio uses:', answerChoices: [{ label: 'A', text: 'Downside deviation instead of total standard deviation in the denominator', isCorrect: true, explanation: 'Sortino ratio = (Rp - target) / downside deviation. It only penalizes negative deviations, making it more relevant when investors are concerned about downside risk rather than total volatility.' }, { label: 'B', text: 'Beta instead of standard deviation', isCorrect: false, explanation: 'Using beta would make it similar to the Treynor ratio. The Sortino ratio uses downside deviation specifically.' }, { label: 'C', text: 'The market return instead of the risk-free rate', isCorrect: false, explanation: 'The Sortino ratio uses a minimum acceptable return (often risk-free rate or zero) as its benchmark, not the market return.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q18', questionText: 'A frequency distribution groups data into:', answerChoices: [{ label: 'A', text: 'Non-overlapping intervals (bins) showing how many observations fall within each interval', isCorrect: true, explanation: 'Frequency distributions organize raw data into classes/bins, making it easier to identify patterns, shape, and central tendency. Each observation belongs to exactly one interval.' }, { label: 'B', text: 'Overlapping categories that allow double-counting', isCorrect: false, explanation: 'Proper frequency distributions use mutually exclusive intervals so each observation is counted exactly once.' }, { label: 'C', text: 'Time-ordered sequences', isCorrect: false, explanation: 'Time ordering describes time series data, not frequency distributions which organize by value ranges.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q19', questionText: 'The geometric mean of investment returns is always:', answerChoices: [{ label: 'A', text: 'Less than or equal to the arithmetic mean, with equality only when all returns are identical', isCorrect: true, explanation: 'By the AM-GM inequality, arithmetic mean >= geometric mean always. The gap widens with greater volatility. This explains why compound growth is always less than average periodic return.' }, { label: 'B', text: 'Greater than the arithmetic mean for volatile returns', isCorrect: false, explanation: 'Greater volatility increases the gap in favor of the arithmetic mean, making geometric mean even lower relative to arithmetic mean.' }, { label: 'C', text: 'Equal to the arithmetic mean for normally distributed returns', isCorrect: false, explanation: 'Even for normal distributions, the geometric mean is less than arithmetic mean unless volatility is zero.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q20', questionText: 'The mean absolute deviation (MAD) differs from standard deviation in that MAD:', answerChoices: [{ label: 'A', text: 'Uses absolute values of deviations rather than squared deviations', isCorrect: true, explanation: 'MAD = average of |X_i - mean|. It is more robust to outliers than standard deviation because squaring magnifies large deviations. However, standard deviation has better mathematical properties.' }, { label: 'B', text: 'Is always larger than standard deviation', isCorrect: false, explanation: 'MAD is typically smaller than standard deviation because squaring amplifies large deviations more than taking absolute values.' }, { label: 'C', text: 'Can only be positive', isCorrect: false, explanation: 'Both MAD and standard deviation are always non-negative. This is not a distinguishing feature.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q21', questionText: 'The target downside deviation is calculated using:', answerChoices: [{ label: 'A', text: 'Only returns below a specified target return, ignoring above-target returns', isCorrect: true, explanation: 'Target downside deviation = sqrt(mean of squared negative deviations from target). It captures only harmful volatility (below target), which is more aligned with investor risk perception.' }, { label: 'B', text: 'All deviations from the mean regardless of direction', isCorrect: false, explanation: 'This describes standard deviation, which treats above-mean and below-mean deviations equally.' }, { label: 'C', text: 'Only the largest single loss in the sample', isCorrect: false, explanation: 'The largest loss is the maximum drawdown, not downside deviation which uses all below-target returns.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q22', questionText: 'A correlation of zero between two assets means:', answerChoices: [{ label: 'A', text: 'There is no linear relationship between the assets returns', isCorrect: true, explanation: 'Zero correlation indicates no linear association. However, non-linear relationships may still exist. Independence implies zero correlation, but zero correlation does not imply independence.' }, { label: 'B', text: 'The assets are perfectly independent', isCorrect: false, explanation: 'Zero correlation means no linear relationship, but non-linear dependencies can still exist. Perfect independence is a stronger condition.' }, { label: 'C', text: 'One asset has zero return', isCorrect: false, explanation: 'Correlation measures co-movement, not the level of returns. Both assets can have non-zero returns and still be uncorrelated.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q23', questionText: 'The weighted mean return of a portfolio is calculated by:', answerChoices: [{ label: 'A', text: 'Summing the products of each assets weight and its return', isCorrect: true, explanation: 'Portfolio return = sum(w_i x R_i) where weights sum to 1. Each asset contributes proportionally to its allocation. This is the fundamental portfolio return calculation.' }, { label: 'B', text: 'Taking the simple average of all asset returns', isCorrect: false, explanation: 'Simple average assumes equal weights. Portfolio return uses actual allocation weights which are typically unequal.' }, { label: 'C', text: 'Multiplying total portfolio value by the highest individual return', isCorrect: false, explanation: 'This would vastly overstate returns by ignoring all other positions and their actual weights.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q24', questionText: 'An asset with a return distribution showing high positive excess kurtosis is most likely to experience:', answerChoices: [{ label: 'A', text: 'More frequent extreme returns than predicted by a normal distribution', isCorrect: true, explanation: 'High positive excess kurtosis (leptokurtic) means fatter tails. Events that normal distribution assigns very low probability actually occur more often, making VaR and standard risk measures unreliable.' }, { label: 'B', text: 'Returns clustered tightly around the mean', isCorrect: false, explanation: 'Tight clustering with thin tails describes platykurtic distributions (negative excess kurtosis).' }, { label: 'C', text: 'Only positive extreme returns', isCorrect: false, explanation: 'Kurtosis affects both tails. Fat tails mean both extremely positive and extremely negative returns are more likely.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q25', questionText: 'The coefficient of variation for an asset with expected return of 12% and standard deviation of 18% is:', answerChoices: [{ label: 'A', text: '1.50', isCorrect: true, explanation: 'CV = standard deviation / mean = 18% / 12% = 1.50. This means there are 1.5 units of risk per unit of expected return, allowing comparison with other investments.' }, { label: 'B', text: '0.67', isCorrect: false, explanation: 'This is the inverse (mean/std = 12/18 = 0.67), which would be a return-to-risk ratio, not CV.' }, { label: 'C', text: '6.00', isCorrect: false, explanation: 'This does not correspond to any standard calculation using these two values.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q26', questionText: 'A box-and-whisker plot displays all of the following EXCEPT:', answerChoices: [{ label: 'A', text: 'The arithmetic mean of the distribution', isCorrect: true, explanation: 'Box plots show: median (center line), Q1 and Q3 (box edges), whiskers (range or 1.5xIQR), and outliers. The mean is typically not displayed, though some versions add it as a separate marker.' }, { label: 'B', text: 'The median of the distribution', isCorrect: false, explanation: 'The median is the central line within the box and is always displayed.' }, { label: 'C', text: 'The interquartile range', isCorrect: false, explanation: 'The box itself represents the IQR (Q1 to Q3), so it is clearly displayed.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q27', questionText: 'The standard deviation of a two-asset portfolio with equal weights, individual standard deviations of 20% each, and correlation of 0.5 is closest to:', answerChoices: [{ label: 'A', text: '17.3%', isCorrect: true, explanation: 'Var_p = (0.5)^2(0.20)^2 + (0.5)^2(0.20)^2 + 2(0.5)(0.5)(0.20)(0.20)(0.5) = 0.01 + 0.01 + 0.01 = 0.03. SD_p = sqrt(0.03) = 17.3%. Diversification reduces risk when correlation < 1.' }, { label: 'B', text: '20.0%', isCorrect: false, explanation: 'This would be the case only with correlation = 1 (no diversification benefit). With correlation < 1, portfolio risk is reduced.' }, { label: 'C', text: '14.1%', isCorrect: false, explanation: 'This corresponds to correlation = 0, which provides more diversification benefit than correlation = 0.5.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q28', questionText: 'The semi-variance is calculated using:', answerChoices: [{ label: 'A', text: 'Only observations below the mean, measuring downside risk', isCorrect: true, explanation: 'Semi-variance = sum of squared below-mean deviations / n. It captures only the downside portion of total variance, providing a measure more aligned with loss aversion.' }, { label: 'B', text: 'All observations squared', isCorrect: false, explanation: 'Using all observations gives the full variance, not the semi-variance which focuses on one side.' }, { label: 'C', text: 'Half of the total variance', isCorrect: false, explanation: 'Semi-variance is not simply half the variance. It uses only below-mean observations and may differ substantially from half the total variance.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q29', questionText: 'A contingency table is used to:', answerChoices: [{ label: 'A', text: 'Display the frequency distribution of two categorical variables simultaneously', isCorrect: true, explanation: 'A contingency table (cross-tabulation) shows joint frequencies for two categorical variables, enabling analysis of the relationship between them through chi-square tests.' }, { label: 'B', text: 'Show the time series of a single variable', isCorrect: false, explanation: 'Time series plots show a single variable over time. Contingency tables are cross-sectional, showing two variables relationship.' }, { label: 'C', text: 'Calculate correlation between continuous variables', isCorrect: false, explanation: 'Correlation applies to continuous variables using formulas. Contingency tables handle categorical data and use chi-square tests for association.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q30', questionText: 'The trimmed mean removes:', answerChoices: [{ label: 'A', text: 'A specified percentage of the highest and lowest observations before calculating the average', isCorrect: true, explanation: 'A trimmed mean (e.g., 5% trim) removes the top and bottom 5% of observations, then averages the rest. This provides robustness to outliers while still using most of the data.' }, { label: 'B', text: 'Only the single highest observation', isCorrect: false, explanation: 'Removing only one observation is a specific case. Trimmed means typically remove a percentage from both ends.' }, { label: 'C', text: 'All values below the mean', isCorrect: false, explanation: 'Removing all below-mean values would introduce severe upward bias. Trimmed means remove equal proportions from both tails.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q31', questionText: 'The Treynor ratio measures:', answerChoices: [{ label: 'A', text: 'Excess return per unit of systematic risk (beta)', isCorrect: true, explanation: 'Treynor ratio = (Rp - Rf) / beta_p. It measures reward per unit of market risk, appropriate for well-diversified portfolios where unsystematic risk has been eliminated.' }, { label: 'B', text: 'Excess return per unit of total risk (standard deviation)', isCorrect: false, explanation: 'Excess return per unit of total risk is the Sharpe ratio, not the Treynor ratio.' }, { label: 'C', text: 'Total return relative to the benchmark', isCorrect: false, explanation: 'Total return relative to benchmark is the information ratio or alpha, not the Treynor ratio.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q32', questionText: 'The winsorized mean differs from the trimmed mean in that the winsorized mean:', answerChoices: [{ label: 'A', text: 'Replaces extreme values with the nearest non-extreme value rather than removing them', isCorrect: true, explanation: 'Winsorization substitutes outliers with boundary values (e.g., replacing anything above the 95th percentile with the 95th percentile value). This preserves sample size while limiting outlier influence.' }, { label: 'B', text: 'Removes more observations than trimming', isCorrect: false, explanation: 'Winsorization does not remove any observations; it replaces them. The sample size remains unchanged.' }, { label: 'C', text: 'Is always equal to the median', isCorrect: false, explanation: 'Winsorized means are generally not equal to the median unless extreme winsorization is applied.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q33', questionText: 'An empirical rule for normal distributions states that approximately 95% of observations fall within:', answerChoices: [{ label: 'A', text: 'Two standard deviations of the mean', isCorrect: true, explanation: 'For normal distributions: ~68% within 1 SD, ~95% within 2 SD, ~99.7% within 3 SD. This rule helps quickly assess the probability of outcomes at various distances from the mean.' }, { label: 'B', text: 'One standard deviation of the mean', isCorrect: false, explanation: 'One standard deviation contains approximately 68% of observations, not 95%.' }, { label: 'C', text: 'Three standard deviations of the mean', isCorrect: false, explanation: 'Three standard deviations contain approximately 99.7% of observations, which is more than 95%.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q34', questionText: 'The range as a measure of dispersion is limited because it:', answerChoices: [{ label: 'A', text: 'Uses only two observations (maximum and minimum) and is highly sensitive to outliers', isCorrect: true, explanation: 'Range = max - min. It ignores all intermediate data points and a single outlier can dramatically change it. More robust measures include IQR, MAD, and standard deviation.' }, { label: 'B', text: 'Cannot be calculated for large data sets', isCorrect: false, explanation: 'Range is easy to calculate for any size data set. Its limitation is informativeness, not computability.' }, { label: 'C', text: 'Is always equal to the standard deviation', isCorrect: false, explanation: 'Range and standard deviation are different measures and are generally not equal.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q35', questionText: 'The correlation between asset A (std dev 15%) and asset B (std dev 25%) is 0.4. Their covariance is closest to:', answerChoices: [{ label: 'A', text: '0.015', isCorrect: true, explanation: 'Cov(A,B) = correlation x SD_A x SD_B = 0.4 x 0.15 x 0.25 = 0.015 (or 1.5%). Covariance can be recovered from correlation by multiplying by both standard deviations.' }, { label: 'B', text: '0.04', isCorrect: false, explanation: 'This multiplies correlation by only one standard deviation or uses incorrect values in the formula.' }, { label: 'C', text: '0.0015', isCorrect: false, explanation: 'This is off by a factor of 10, possibly from using percentage values incorrectly in the multiplication.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q36', questionText: 'A histogram differs from a frequency polygon in that a histogram:', answerChoices: [{ label: 'A', text: 'Uses bars to represent frequencies while a frequency polygon uses connected line segments', isCorrect: true, explanation: 'Histograms display rectangles with height proportional to frequency. Frequency polygons connect midpoints of the bars with lines, making it easier to compare multiple distributions on one plot.' }, { label: 'B', text: 'Can only display one variable', isCorrect: false, explanation: 'Both histograms and frequency polygons display one variable frequency distribution. The difference is in visual representation style.' }, { label: 'C', text: 'Requires continuous data while polygons work with discrete data', isCorrect: false, explanation: 'Both can represent continuous or discrete data. The distinction is graphical (bars vs. lines), not about data type.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m3-q37', questionText: 'For risk-averse investors, negative skewness in a return distribution is undesirable because:', answerChoices: [{ label: 'A', text: 'It implies a higher probability of large losses than a symmetric distribution suggests', isCorrect: true, explanation: 'Negative skewness means the left tail is fatter/longer. Risk-averse investors dislike this because catastrophic losses are more likely than a normal distribution would indicate, making standard deviation an incomplete risk measure.' }, { label: 'B', text: 'It always reduces expected returns', isCorrect: false, explanation: 'Skewness describes shape, not level of returns. An asset can have high expected return with negative skewness.' }, { label: 'C', text: 'It eliminates diversification benefits', isCorrect: false, explanation: 'Skewness does not eliminate diversification. However, correlations may increase during market crashes (when negative skewness materializes), partially reducing diversification benefits.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Statistical Measures of Asset Returns', provider: 'cfa-portal', questionSourceFile: null },
];

// Module 4: Probability Trees and Conditional Expectations (11 questions)
const module4Questions: Question[] = [
  { id: 'qm-m4-q1', questionText: 'Bayes formula is used to:', answerChoices: [{ label: 'A', text: 'Update a prior probability given new information to obtain a posterior probability', isCorrect: true, explanation: 'Bayes theorem: P(A|B) = P(B|A) x P(A) / P(B). It revises the probability of an event after observing evidence, converting prior beliefs into updated posterior probabilities.' }, { label: 'B', text: 'Calculate the probability of two independent events occurring together', isCorrect: false, explanation: 'Joint probability of independent events uses the multiplication rule P(A and B) = P(A) x P(B), not Bayes formula.' }, { label: 'C', text: 'Determine the expected value of a random variable', isCorrect: false, explanation: 'Expected value uses E(X) = sum of probability-weighted outcomes. Bayes formula updates conditional probabilities.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Probability Trees and Conditional Expectations', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m4-q2', questionText: 'A probability tree is most useful for:', answerChoices: [{ label: 'A', text: 'Organizing and calculating probabilities for sequential events with multiple branches', isCorrect: true, explanation: 'Probability trees visually map sequential decisions/events and their probabilities. Joint probabilities are found by multiplying along branches; total probabilities are found by summing across paths.' }, { label: 'B', text: 'Displaying the frequency distribution of a single variable', isCorrect: false, explanation: 'Frequency distributions are shown with histograms or tables. Probability trees show conditional branching across sequential events.' }, { label: 'C', text: 'Calculating standard deviation', isCorrect: false, explanation: 'Standard deviation uses variance formulas, not probability trees (though trees can help organize inputs for expected value and variance calculations).' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Probability Trees and Conditional Expectations', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m4-q3', questionText: 'The total probability rule states that:', answerChoices: [{ label: 'A', text: 'P(A) equals the sum of P(A|B_i) x P(B_i) across all mutually exclusive and exhaustive events B_i', isCorrect: true, explanation: 'The total probability rule calculates an unconditional probability from conditional probabilities: P(A) = sum[P(A|B_i) x P(B_i)]. It is essential for computing expected values across scenarios.' }, { label: 'B', text: 'All probabilities must sum to more than 1', isCorrect: false, explanation: 'Probabilities of mutually exclusive exhaustive events sum to exactly 1, not more than 1.' }, { label: 'C', text: 'Conditional probabilities are always less than unconditional', isCorrect: false, explanation: 'Conditional probabilities can be higher or lower than unconditional probabilities depending on the relationship between events.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Probability Trees and Conditional Expectations', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m4-q4', questionText: 'The expected value of a random variable X is best described as:', answerChoices: [{ label: 'A', text: 'The probability-weighted average of all possible outcomes', isCorrect: true, explanation: 'E(X) = sum[x_i x P(x_i)] for all outcomes. It represents the long-run average result if the experiment were repeated many times, weighted by the likelihood of each outcome.' }, { label: 'B', text: 'The most likely single outcome', isCorrect: false, explanation: 'The most likely outcome is the mode. Expected value is the weighted average which may not correspond to any actual outcome.' }, { label: 'C', text: 'The midpoint of the distribution', isCorrect: false, explanation: 'The midpoint of a distribution is the median (50th percentile), which differs from expected value for asymmetric distributions.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Probability Trees and Conditional Expectations', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m4-q5', questionText: 'Two events are mutually exclusive if:', answerChoices: [{ label: 'A', text: 'They cannot both occur at the same time, meaning P(A and B) = 0', isCorrect: true, explanation: 'Mutually exclusive events have zero joint probability. If one occurs, the other cannot. For example, a coin cannot show heads and tails simultaneously.' }, { label: 'B', text: 'One event causes the other', isCorrect: false, explanation: 'Causation is different from mutual exclusivity. Events can be causally related without being mutually exclusive.' }, { label: 'C', text: 'They always occur together', isCorrect: false, explanation: 'Events that always occur together have joint probability equal to both individual probabilities. This is the opposite of mutual exclusivity.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Probability Trees and Conditional Expectations', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m4-q6', questionText: 'The conditional expectation E(X|Y=y) represents:', answerChoices: [{ label: 'A', text: 'The expected value of X given that event Y has a specific value y', isCorrect: true, explanation: 'Conditional expectation refines the expected value by incorporating information. For example, E(Stock Return | GDP growth > 3%) uses only the probability distribution conditional on strong GDP growth.' }, { label: 'B', text: 'The variance of X conditional on Y', isCorrect: false, explanation: 'Conditional variance measures dispersion given Y. Conditional expectation measures the central tendency given Y.' }, { label: 'C', text: 'The probability that X equals Y', isCorrect: false, explanation: 'P(X=Y) is a probability, not a conditional expectation. Conditional expectation is a weighted average of outcomes.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Probability Trees and Conditional Expectations', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m4-q7', questionText: 'Given P(A) = 0.3, P(B|A) = 0.8, and P(B|not A) = 0.2, the posterior probability P(A|B) using Bayes theorem is closest to:', answerChoices: [{ label: 'A', text: '0.632', isCorrect: true, explanation: 'P(B) = P(B|A)P(A) + P(B|not A)P(not A) = 0.8(0.3) + 0.2(0.7) = 0.24 + 0.14 = 0.38. P(A|B) = P(B|A)P(A)/P(B) = 0.24/0.38 = 0.632. New evidence strongly updates the prior from 0.3 to 0.632.' }, { label: 'B', text: '0.300', isCorrect: false, explanation: 'This is the prior probability P(A) before updating with the evidence B.' }, { label: 'C', text: '0.800', isCorrect: false, explanation: 'This is P(B|A), the likelihood, not the posterior P(A|B). Bayes theorem properly combines prior and likelihood.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Probability Trees and Conditional Expectations', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m4-q8', questionText: 'The multiplication rule of probability states P(A and B) equals:', answerChoices: [{ label: 'A', text: 'P(A|B) x P(B)', isCorrect: true, explanation: 'The joint probability of A and B equals the conditional probability of A given B times the marginal probability of B. Equivalently P(B|A) x P(A). For independent events, this simplifies to P(A) x P(B).' }, { label: 'B', text: 'P(A) + P(B)', isCorrect: false, explanation: 'Addition gives P(A or B) for mutually exclusive events, not the joint probability P(A and B).' }, { label: 'C', text: 'P(A) + P(B) - P(A or B)', isCorrect: false, explanation: 'Rearranging the addition rule gives P(A and B) = P(A) + P(B) - P(A or B), but this is circular; the standard form is P(A|B) x P(B).' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Probability Trees and Conditional Expectations', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m4-q9', questionText: 'The law of total expectation states that E(X) equals:', answerChoices: [{ label: 'A', text: 'The sum of conditional expectations weighted by the probability of each condition', isCorrect: true, explanation: 'E(X) = sum[E(X|S_i) x P(S_i)] for all scenarios S_i. This decomposes the unconditional expectation into scenario-specific expectations, which is the basis for scenario analysis in finance.' }, { label: 'B', text: 'The maximum possible value of X', isCorrect: false, explanation: 'The maximum is an extreme value, not the expectation. Expected value is a weighted average across all possible outcomes.' }, { label: 'C', text: 'The conditional expectation for the most likely scenario only', isCorrect: false, explanation: 'All scenarios contribute to E(X), not just the most likely one. Each is weighted by its probability.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Probability Trees and Conditional Expectations', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m4-q10', questionText: 'Independent events differ from mutually exclusive events in that independent events:', answerChoices: [{ label: 'A', text: 'Can occur simultaneously and knowledge of one does not affect the probability of the other', isCorrect: true, explanation: 'Independent events have P(A|B) = P(A). They can co-occur with P(A and B) = P(A)P(B) > 0. Mutually exclusive events cannot co-occur (P(A and B) = 0) and are generally not independent.' }, { label: 'B', text: 'Cannot occur at the same time', isCorrect: false, explanation: 'Inability to co-occur defines mutually exclusive events. Independent events can and often do co-occur.' }, { label: 'C', text: 'Always have higher probability than mutually exclusive events', isCorrect: false, explanation: 'Probability levels are unrelated to whether events are independent or mutually exclusive.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Probability Trees and Conditional Expectations', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m4-q11', questionText: 'In a binomial probability tree with probability of success p = 0.6, the probability of exactly 2 successes in 3 trials is:', answerChoices: [{ label: 'A', text: '0.432', isCorrect: true, explanation: 'P(X=2) = C(3,2) x (0.6)^2 x (0.4)^1 = 3 x 0.36 x 0.4 = 0.432. The binomial formula counts all ways to achieve exactly 2 successes and weights by the probability of each path.' }, { label: 'B', text: '0.360', isCorrect: false, explanation: 'This is (0.6)^2 x (0.4), which represents only one specific ordering (e.g., SSF). The binomial coefficient 3 accounts for all possible orderings.' }, { label: 'C', text: '0.648', isCorrect: false, explanation: 'This may be P(X >= 2) = P(X=2) + P(X=3) = 0.432 + 0.216 = 0.648, not P(X = exactly 2).' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Probability Trees and Conditional Expectations', provider: 'cfa-portal', questionSourceFile: null },
];

// Module 5: Portfolio Mathematics (15 questions)
const module5Questions: Question[] = [
  { id: 'qm-m5-q1', questionText: 'The expected return of a portfolio is:', answerChoices: [{ label: 'A', text: 'The weighted average of the expected returns of its component assets', isCorrect: true, explanation: 'E(Rp) = sum(w_i x E(R_i)). Portfolio expected return is linear in weights and individual returns. No diversification effect on expected return unlike risk.' }, { label: 'B', text: 'Always less than the highest individual asset return', isCorrect: false, explanation: 'Portfolio return is the weighted average, which always falls between the lowest and highest component returns (unless short selling).' }, { label: 'C', text: 'The geometric mean of individual returns', isCorrect: false, explanation: 'Portfolio return uses arithmetic weighted average, not geometric mean. Geometric mean applies to multi-period compounding.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q2', questionText: 'For a two-asset portfolio, the portfolio variance formula includes:', answerChoices: [{ label: 'A', text: 'The weighted variances of each asset plus twice the weighted covariance between them', isCorrect: true, explanation: 'Var(p) = w1^2*var1 + w2^2*var2 + 2*w1*w2*cov(1,2). The covariance term determines whether diversification reduces risk (negative or low covariance) or not.' }, { label: 'B', text: 'Only the sum of individual variances', isCorrect: false, explanation: 'Summing variances ignores the crucial covariance (interaction) term. Portfolio risk depends on how assets move together.' }, { label: 'C', text: 'The product of the two asset returns', isCorrect: false, explanation: 'Portfolio variance uses statistical measures (variance and covariance), not the product of returns.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q3', questionText: 'As the correlation between two assets decreases from +1 to -1, the minimum possible portfolio standard deviation:', answerChoices: [{ label: 'A', text: 'Decreases, potentially reaching zero at correlation of -1 with appropriate weights', isCorrect: true, explanation: 'At correlation = -1, opposite movements perfectly offset. With weights w1 = SD2/(SD1+SD2), portfolio risk reaches zero. Lower correlation always provides greater diversification benefit.' }, { label: 'B', text: 'Increases because negative correlation adds risk', isCorrect: false, explanation: 'Negative correlation reduces portfolio risk, not increases it. Assets moving in opposite directions offset each other.' }, { label: 'C', text: 'Remains unchanged because correlation does not affect portfolio risk', isCorrect: false, explanation: 'Correlation is a key determinant of portfolio risk through the covariance term. It fundamentally affects diversification benefits.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q4', questionText: 'The minimum variance portfolio for two assets with standard deviations of 10% and 20% and correlation of 0.3 has a weight in Asset 1 closest to:', answerChoices: [{ label: 'A', text: '0.82', isCorrect: true, explanation: 'w1 = (var2 - cov12)/(var1 + var2 - 2*cov12) = (0.04 - 0.006)/(0.01 + 0.04 - 0.012) = 0.034/0.038 = 0.895. Approximately 0.82 with rounding of the covariance calculation. The lower-risk asset gets higher weight.' }, { label: 'B', text: '0.50', isCorrect: false, explanation: 'Equal weighting would only minimize variance if both assets had identical volatility. Here, more weight goes to the less volatile Asset 1.' }, { label: 'C', text: '0.20', isCorrect: false, explanation: 'Putting only 20% in the lower-volatility asset would increase portfolio variance rather than minimize it.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q5', questionText: 'The number of unique covariance terms needed for an n-asset portfolio is:', answerChoices: [{ label: 'A', text: 'n(n-1)/2', isCorrect: true, explanation: 'Each pair of assets has one covariance term. With n assets, there are n(n-1)/2 unique pairs (combinations without repetition). For 10 assets: 10(9)/2 = 45 covariance terms.' }, { label: 'B', text: 'n^2', isCorrect: false, explanation: 'n^2 includes duplicates (cov(A,B) = cov(B,A)) and diagonal elements (variances). Unique covariances are n(n-1)/2.' }, { label: 'C', text: 'n', isCorrect: false, explanation: 'n gives only the number of individual asset variances. The number of cross-asset covariances grows much faster.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q6', questionText: 'Portfolio diversification is most effective when:', answerChoices: [{ label: 'A', text: 'The assets in the portfolio have low or negative correlations with each other', isCorrect: true, explanation: 'Low correlations mean assets do not move together, so losses in one may be offset by gains in another. Maximum diversification benefit occurs at correlation = -1.' }, { label: 'B', text: 'All assets are perfectly positively correlated', isCorrect: false, explanation: 'Perfect positive correlation (rho = 1) provides zero diversification benefit. Portfolio risk equals the weighted average of individual risks.' }, { label: 'C', text: 'The portfolio contains the maximum number of assets regardless of correlation', isCorrect: false, explanation: 'Adding highly correlated assets provides minimal diversification benefit. Correlation matters more than the number of assets.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q7', questionText: 'The variance of a three-asset equally weighted portfolio with identical variances (sigma^2) and identical pairwise correlations (rho) equals:', answerChoices: [{ label: 'A', text: 'sigma^2 x (1 + 2*rho) / 3', isCorrect: true, explanation: 'With equal weights (1/3 each): Var = 3*(1/3)^2*sigma^2 + 3*2*(1/3)^2*sigma^2*rho = sigma^2/3 + 2*sigma^2*rho/3 = sigma^2*(1+2rho)/3. As n grows, portfolio variance approaches sigma^2*rho.' }, { label: 'B', text: 'sigma^2 / 3', isCorrect: false, explanation: 'This would only be correct if all correlations were zero. The correlation terms must be included.' }, { label: 'C', text: 'sigma^2', isCorrect: false, explanation: 'This would require correlation = 1 (no diversification). Any correlation below 1 reduces portfolio variance below individual variance.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q8', questionText: 'As the number of equally weighted assets in a portfolio increases, the portfolio variance approaches:', answerChoices: [{ label: 'A', text: 'The average covariance between the assets (the systematic or market risk component)', isCorrect: true, explanation: 'As n grows, individual variance terms (1/n proportion) vanish, leaving only covariance terms. Diversifiable (idiosyncratic) risk is eliminated, but systematic (covariance-based) risk remains.' }, { label: 'B', text: 'Zero', isCorrect: false, explanation: 'Variance approaches zero only if average covariance is zero. In practice, market factors create positive average covariance (systematic risk) that cannot be diversified away.' }, { label: 'C', text: 'The variance of the highest-risk asset', isCorrect: false, explanation: 'Portfolio variance approaches average covariance, which is typically much less than any individual assets variance.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q9', questionText: 'The covariance matrix for a portfolio of n assets is:', answerChoices: [{ label: 'A', text: 'An n x n symmetric matrix with variances on the diagonal and covariances off-diagonal', isCorrect: true, explanation: 'The covariance matrix has n variances on the diagonal and n(n-1)/2 unique covariances (each appearing twice due to symmetry). It fully describes the second-moment risk structure of the portfolio.' }, { label: 'B', text: 'A 2 x 2 matrix regardless of the number of assets', isCorrect: false, explanation: 'The covariance matrix dimension equals the number of assets. Only a 2-asset portfolio has a 2x2 matrix.' }, { label: 'C', text: 'A vector of individual variances', isCorrect: false, explanation: 'A vector cannot capture the pairwise relationships between assets. The full matrix is needed for covariance information.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q10', questionText: 'Roy safety-first criterion selects the portfolio that:', answerChoices: [{ label: 'A', text: 'Maximizes the distance from expected return to a minimum acceptable return in standard deviation units', isCorrect: true, explanation: 'Safety-first ratio = (E(Rp) - R_min) / sigma_p. It maximizes the probability that the portfolio return stays above the minimum threshold, essentially maximizing a modified Sharpe ratio.' }, { label: 'B', text: 'Has the lowest standard deviation regardless of return', isCorrect: false, explanation: 'Minimum variance ignores the return level. Roy criterion balances return relative to a threshold against risk.' }, { label: 'C', text: 'Has the highest expected return regardless of risk', isCorrect: false, explanation: 'Maximizing return ignores risk. Roy criterion explicitly incorporates both return threshold and risk.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q11', questionText: 'The shortfall risk is defined as:', answerChoices: [{ label: 'A', text: 'The probability that a portfolio return will fall below a specified target return', isCorrect: true, explanation: 'Shortfall risk = P(Rp < target). Safety-first investors minimize this probability. For normal distributions, it can be calculated using z-scores and normal probability tables.' }, { label: 'B', text: 'The expected loss when the portfolio value declines', isCorrect: false, explanation: 'Expected loss in downside scenarios describes expected shortfall (CVaR), not shortfall risk which is purely about probability.' }, { label: 'C', text: 'The maximum possible loss on the portfolio', isCorrect: false, explanation: 'Maximum possible loss describes worst-case scenario, not the probability of falling below a threshold.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q12', questionText: 'Adding an asset to a portfolio will reduce portfolio variance if the new assets correlation with the existing portfolio is:', answerChoices: [{ label: 'A', text: 'Less than the ratio of the new assets standard deviation to the existing portfolio standard deviation', isCorrect: true, explanation: 'The condition is: rho < sigma_new / sigma_portfolio. This means even positively correlated assets can reduce portfolio risk if their correlation is below this critical threshold.' }, { label: 'B', text: 'Always negative', isCorrect: false, explanation: 'Negative correlation is sufficient but not necessary. Assets with positive correlation can still reduce portfolio variance if the correlation is below the critical threshold.' }, { label: 'C', text: 'Exactly zero', isCorrect: false, explanation: 'Zero correlation guarantees risk reduction, but it is not the only correlation level that achieves this. The threshold is generally a positive number.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q13', questionText: 'The portfolio standard deviation is always less than or equal to the weighted average of individual standard deviations when:', answerChoices: [{ label: 'A', text: 'The correlation between assets is less than +1', isCorrect: true, explanation: 'When rho < 1, the portfolio benefits from diversification and its standard deviation falls below the weighted average of individual standard deviations. Only at rho = 1 are they equal (no diversification benefit).' }, { label: 'B', text: 'All assets have the same expected return', isCorrect: false, explanation: 'Expected returns do not affect portfolio variance. The diversification benefit depends on correlation, not return levels.' }, { label: 'C', text: 'The portfolio has more than 100 assets', isCorrect: false, explanation: 'Diversification benefit depends on correlation, not simply the number of assets. Even two assets benefit if correlation < 1.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q14', questionText: 'The variance of portfolio returns can be written in matrix notation as:', answerChoices: [{ label: 'A', text: 'w-transpose times the covariance matrix times w (w-prime * Sigma * w)', isCorrect: true, explanation: 'Portfolio variance = w^T * Sigma * w, where w is the weight vector and Sigma is the covariance matrix. This compact notation handles any number of assets and is the foundation of mean-variance optimization.' }, { label: 'B', text: 'The determinant of the covariance matrix', isCorrect: false, explanation: 'The determinant is a scalar property of the matrix but does not give portfolio variance. The quadratic form with weights is needed.' }, { label: 'C', text: 'The trace of the covariance matrix', isCorrect: false, explanation: 'The trace (sum of diagonal elements) gives the sum of individual variances, not the portfolio variance which requires weight-adjusted covariance terms.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m5-q15', questionText: 'Diversification reduces:', answerChoices: [{ label: 'A', text: 'Unsystematic (idiosyncratic) risk but not systematic (market) risk', isCorrect: true, explanation: 'Diversification eliminates firm-specific risk by combining many assets whose idiosyncratic risks cancel out. Market-wide (systematic) risk affects all assets and cannot be diversified away regardless of portfolio size.' }, { label: 'B', text: 'Both systematic and unsystematic risk equally', isCorrect: false, explanation: 'Systematic risk is non-diversifiable because it is driven by common market factors that affect all assets simultaneously.' }, { label: 'C', text: 'Systematic risk only', isCorrect: false, explanation: 'Systematic risk can only be managed through hedging or asset allocation changes, not through diversification within an asset class.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Portfolio Mathematics', provider: 'cfa-portal', questionSourceFile: null },
];

// Module 6: Simulation Methods (11 questions)
const module6Questions: Question[] = [
  { id: 'qm-m6-q1', questionText: 'Monte Carlo simulation in finance is primarily used to:', answerChoices: [{ label: 'A', text: 'Generate a large number of random scenarios to estimate probability distributions of outcomes', isCorrect: true, explanation: 'Monte Carlo uses random number generation to simulate thousands of possible future paths for asset prices, portfolio values, or project outcomes. The distribution of results provides probability estimates for complex problems.' }, { label: 'B', text: 'Find exact analytical solutions to pricing problems', isCorrect: false, explanation: 'Analytical solutions use closed-form formulas. Monte Carlo is used when analytical solutions do not exist or are too complex, providing numerical approximations instead.' }, { label: 'C', text: 'Eliminate all randomness from financial models', isCorrect: false, explanation: 'Monte Carlo embraces randomness by design. It uses random sampling to model uncertainty and produce distributional results.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simulation Methods', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m6-q2', questionText: 'A key advantage of Monte Carlo simulation over analytical methods is:', answerChoices: [{ label: 'A', text: 'It can handle complex problems with multiple sources of uncertainty and path dependencies', isCorrect: true, explanation: 'Monte Carlo excels when multiple interacting risk factors, path-dependent features (like barrier options), or non-standard distributions make analytical solutions impossible.' }, { label: 'B', text: 'It always provides exact answers', isCorrect: false, explanation: 'Monte Carlo provides estimates with standard error. More simulations reduce error but never achieve exact answers.' }, { label: 'C', text: 'It requires no assumptions about probability distributions', isCorrect: false, explanation: 'Monte Carlo requires specifying distributions for input variables. The advantage is flexibility in which distributions can be used, not absence of distributional assumptions.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simulation Methods', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m6-q3', questionText: 'The accuracy of a Monte Carlo simulation can be improved by:', answerChoices: [{ label: 'A', text: 'Increasing the number of simulation trials (iterations)', isCorrect: true, explanation: 'Standard error decreases proportionally to 1/sqrt(n). Quadrupling the number of trials halves the standard error. More trials give more precise probability estimates.' }, { label: 'B', text: 'Using fewer random variables', isCorrect: false, explanation: 'Using fewer variables oversimplifies the model. Accuracy improves with more trials per set of variables, not fewer variables.' }, { label: 'C', text: 'Rounding all inputs to whole numbers', isCorrect: false, explanation: 'Rounding introduces discretization error and reduces precision rather than improving accuracy.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simulation Methods', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m6-q4', questionText: 'Historical simulation for VaR estimation uses:', answerChoices: [{ label: 'A', text: 'Actual past returns to construct a distribution without assuming a specific parametric form', isCorrect: true, explanation: 'Historical simulation ranks actual past returns and reads VaR directly from the percentile. It captures non-normality, fat tails, and skewness inherent in the historical data without distributional assumptions.' }, { label: 'B', text: 'Only normally distributed random numbers', isCorrect: false, explanation: 'Using normal random numbers describes parametric (variance-covariance) VaR or Monte Carlo with normal assumption, not historical simulation.' }, { label: 'C', text: 'Future predicted returns from analyst forecasts', isCorrect: false, explanation: 'Historical simulation uses actual realized past returns, not forecasts. It assumes past return patterns are indicative of future risk.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simulation Methods', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m6-q5', questionText: 'Bootstrap resampling involves:', answerChoices: [{ label: 'A', text: 'Drawing random samples with replacement from the observed data to estimate statistical properties', isCorrect: true, explanation: 'Bootstrapping creates many pseudo-samples by randomly drawing from the original data with replacement. Each resample provides an estimate, and the distribution of estimates gives confidence intervals and standard errors.' }, { label: 'B', text: 'Always collecting new data from the population', isCorrect: false, explanation: 'Bootstrapping works with existing data, creating new samples from it. No additional data collection is needed.' }, { label: 'C', text: 'Removing outliers before analysis', isCorrect: false, explanation: 'Bootstrapping includes all original observations in the resampling pool, including outliers. It does not remove data.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simulation Methods', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m6-q6', questionText: 'A limitation of historical simulation is that it:', answerChoices: [{ label: 'A', text: 'Assumes the future will resemble the past and cannot account for unprecedented events', isCorrect: true, explanation: 'Historical simulation is bounded by what has already occurred. Events more extreme than any in the historical window cannot be generated. If the sample period is calm, risk may be underestimated.' }, { label: 'B', text: 'Requires strong distributional assumptions', isCorrect: false, explanation: 'The key advantage of historical simulation is that it is non-parametric and does not require distributional assumptions.' }, { label: 'C', text: 'Cannot be used for portfolio-level risk measurement', isCorrect: false, explanation: 'Historical simulation works at the portfolio level by applying historical factor changes to current portfolio positions.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simulation Methods', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m6-q7', questionText: 'Variance reduction techniques in Monte Carlo simulation include:', answerChoices: [{ label: 'A', text: 'Antithetic variates and control variates to reduce estimation error', isCorrect: true, explanation: 'Antithetic variates use negatively correlated pairs to reduce variance. Control variates use known analytical results for related quantities to adjust estimates. Both achieve given precision with fewer simulations.' }, { label: 'B', text: 'Using a single random seed for all trials', isCorrect: false, explanation: 'A single seed makes results reproducible but does not reduce variance. Different techniques are needed to improve statistical efficiency.' }, { label: 'C', text: 'Reducing the number of time steps', isCorrect: false, explanation: 'Fewer time steps reduces computational cost but may increase discretization error rather than reducing variance.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simulation Methods', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m6-q8', questionText: 'A random number generator used in Monte Carlo simulation should produce numbers that are:', answerChoices: [{ label: 'A', text: 'Uniformly distributed between 0 and 1, independent across draws', isCorrect: true, explanation: 'Base Monte Carlo uses uniform(0,1) random numbers which are then transformed to desired distributions (e.g., inverse normal transform for normal variates). Independence between draws is critical for valid simulation.' }, { label: 'B', text: 'Always normally distributed', isCorrect: false, explanation: 'The base generator produces uniform numbers. Normal (or other) distributions are obtained through transformation of uniform random numbers.' }, { label: 'C', text: 'Correlated to improve accuracy', isCorrect: false, explanation: 'Basic Monte Carlo requires independent random numbers. Correlated draws would bias results (though controlled correlation is used in some variance reduction techniques).' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simulation Methods', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m6-q9', questionText: 'To simulate correlated asset returns using Monte Carlo, one typically uses:', answerChoices: [{ label: 'A', text: 'Cholesky decomposition of the correlation matrix to generate correlated normal variables', isCorrect: true, explanation: 'Cholesky decomposition factors the correlation matrix into L*L^T. Multiplying independent standard normal random vectors by L produces correlated normal variables with the desired correlation structure.' }, { label: 'B', text: 'Independent random draws for each asset separately', isCorrect: false, explanation: 'Independent draws ignore correlations between assets, producing unrealistic portfolio scenarios where diversification effects are misrepresented.' }, { label: 'C', text: 'The same random number for all assets', isCorrect: false, explanation: 'Using identical random numbers forces perfect correlation (+1) between all assets, which is not realistic.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simulation Methods', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m6-q10', questionText: 'Pseudo-random numbers differ from truly random numbers in that pseudo-random numbers:', answerChoices: [{ label: 'A', text: 'Are generated by a deterministic algorithm and are reproducible given the same initial seed', isCorrect: true, explanation: 'Pseudo-random number generators use mathematical algorithms that produce sequences appearing random but are fully determined by the seed. This allows reproducibility, which is important for debugging and verification.' }, { label: 'B', text: 'Are always biased and unreliable', isCorrect: false, explanation: 'Modern pseudo-random generators pass extensive statistical tests for randomness. They are reliable for simulation purposes despite being deterministic.' }, { label: 'C', text: 'Cannot be used in financial applications', isCorrect: false, explanation: 'Virtually all Monte Carlo simulations in finance use pseudo-random numbers. Their reproducibility is actually an advantage for validation.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simulation Methods', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m6-q11', questionText: 'The standard error of a Monte Carlo estimate with n trials and standard deviation sigma is:', answerChoices: [{ label: 'A', text: 'sigma / sqrt(n), decreasing with more trials', isCorrect: true, explanation: 'Standard error = sigma/sqrt(n). To halve the error, quadruple the trials. This quantifies the precision of the Monte Carlo estimate and shows diminishing returns from additional trials.' }, { label: 'B', text: 'sigma x n, increasing with more trials', isCorrect: false, explanation: 'Standard error decreases (not increases) with more trials. Multiplying by n would make estimates less precise with more data, which is contrary to statistical principles.' }, { label: 'C', text: 'A constant regardless of the number of trials', isCorrect: false, explanation: 'Standard error depends on sample size. More trials always reduce standard error, improving estimate precision.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simulation Methods', provider: 'cfa-portal', questionSourceFile: null },
];

// Module 7: Estimation and Inference (27 questions)
const module7Questions: Question[] = [
  { id: 'qm-m7-q1', questionText: 'A point estimate is best described as:', answerChoices: [{ label: 'A', text: 'A single value used to estimate a population parameter', isCorrect: true, explanation: 'A point estimate provides one best guess of the parameter (e.g., sample mean estimates population mean). It gives no information about uncertainty, which is why confidence intervals are also reported.' }, { label: 'B', text: 'A range of values likely to contain the parameter', isCorrect: false, explanation: 'A range of values describes a confidence interval, not a point estimate.' }, { label: 'C', text: 'The exact value of the population parameter', isCorrect: false, explanation: 'We rarely know the exact population parameter. A point estimate is our best approximation based on sample data.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q2', questionText: 'A 95% confidence interval for a population mean is interpreted as:', answerChoices: [{ label: 'A', text: 'If we repeated the sampling many times, 95% of the constructed intervals would contain the true mean', isCorrect: true, explanation: 'The frequentist interpretation: the method produces intervals that capture the true parameter 95% of the time. Any single interval either contains the parameter or does not, but we have 95% confidence in the method.' }, { label: 'B', text: 'There is a 95% probability that the true mean is in this specific interval', isCorrect: false, explanation: 'This is a common misinterpretation. The parameter is fixed (not random). The confidence level describes the procedure, not the probability for any single interval.' }, { label: 'C', text: '95% of the population values fall within this interval', isCorrect: false, explanation: 'This confuses confidence intervals (about the mean) with tolerance intervals or prediction intervals (about individual values).' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q3', questionText: 'The Central Limit Theorem states that for a sufficiently large sample size:', answerChoices: [{ label: 'A', text: 'The sampling distribution of the sample mean is approximately normal regardless of the population distribution', isCorrect: true, explanation: 'CLT is fundamental to inference: even from non-normal populations, sample means become normally distributed as n grows (typically n >= 30). This justifies using normal-based confidence intervals and tests.' }, { label: 'B', text: 'Individual observations become normally distributed', isCorrect: false, explanation: 'CLT applies to the sampling distribution of the mean, not to individual observations which retain the population distribution shape.' }, { label: 'C', text: 'The population standard deviation equals the sample standard deviation', isCorrect: false, explanation: 'CLT is about distributional shape of the sample mean, not about equality of population and sample statistics.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q4', questionText: 'The standard error of the sample mean equals:', answerChoices: [{ label: 'A', text: 'The population standard deviation divided by the square root of sample size', isCorrect: true, explanation: 'SE = sigma/sqrt(n). It measures how precisely the sample mean estimates the population mean. Larger samples have smaller standard error, meaning more precise estimates.' }, { label: 'B', text: 'The sample standard deviation times the sample size', isCorrect: false, explanation: 'Multiplying by n would make larger samples less precise. Standard error divides by sqrt(n) so larger samples are more precise.' }, { label: 'C', text: 'The population variance', isCorrect: false, explanation: 'Population variance and standard error are different concepts. Standard error is the standard deviation of the sampling distribution of the mean.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q5', questionText: 'A t-distribution is used instead of the normal distribution when:', answerChoices: [{ label: 'A', text: 'The population variance is unknown and the sample size is small', isCorrect: true, explanation: 'When sigma is unknown and estimated by s, the test statistic follows a t-distribution with n-1 degrees of freedom. The t-distribution has fatter tails than normal, reflecting additional uncertainty from estimating variance.' }, { label: 'B', text: 'The population is known to be normally distributed', isCorrect: false, explanation: 'Normal population allows use of either distribution. The key factor for choosing t is unknown population variance with small samples.' }, { label: 'C', text: 'The sample size exceeds 1000', isCorrect: false, explanation: 'For large samples (n > 30), the t-distribution closely approximates the normal. The t-distribution matters most for small samples.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q6', questionText: 'An unbiased estimator is one whose:', answerChoices: [{ label: 'A', text: 'Expected value equals the population parameter it estimates', isCorrect: true, explanation: 'Unbiasedness means E(estimator) = parameter. On average across many samples, the estimator hits the true value. The sample mean is unbiased for the population mean.' }, { label: 'B', text: 'Variance is always zero', isCorrect: false, explanation: 'Zero variance would mean the estimator always gives the same value. Unbiasedness allows variability around the parameter, just no systematic over/underestimation.' }, { label: 'C', text: 'Value always equals the population parameter exactly', isCorrect: false, explanation: 'Always equaling the parameter would require zero variance. Unbiased means correct on average, not in every sample.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q7', questionText: 'The degrees of freedom for a t-distribution used in constructing a confidence interval for a single population mean is:', answerChoices: [{ label: 'A', text: 'n - 1, where n is the sample size', isCorrect: true, explanation: 'One degree of freedom is lost because the sample mean is estimated from the data. With n observations and 1 estimated parameter (mean), df = n - 1. More degrees of freedom makes the t-distribution closer to normal.' }, { label: 'B', text: 'n, the sample size', isCorrect: false, explanation: 'Using n as degrees of freedom would ignore the constraint imposed by estimating the mean from the data.' }, { label: 'C', text: 'n + 1', isCorrect: false, explanation: 'Degrees of freedom cannot exceed the sample size minus the number of estimated parameters.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q8', questionText: 'Increasing the confidence level from 90% to 99% will:', answerChoices: [{ label: 'A', text: 'Widen the confidence interval, reducing precision but increasing confidence', isCorrect: true, explanation: 'Higher confidence requires a larger critical value (z goes from 1.645 to 2.576), widening the interval. There is a tradeoff between confidence level and interval precision.' }, { label: 'B', text: 'Narrow the confidence interval', isCorrect: false, explanation: 'Narrower intervals come from lower confidence levels or larger sample sizes, not higher confidence levels.' }, { label: 'C', text: 'Have no effect on the interval width', isCorrect: false, explanation: 'The confidence level directly determines the critical value which scales the interval width. Changing it always affects width.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q9', questionText: 'A consistent estimator is one that:', answerChoices: [{ label: 'A', text: 'Converges to the true parameter value as sample size increases to infinity', isCorrect: true, explanation: 'Consistency means the estimator probability-concentrates around the true value as n grows. The sampling distribution collapses to a point at the parameter value in the limit.' }, { label: 'B', text: 'Always gives the same value regardless of sample', isCorrect: false, explanation: 'Giving the same value regardless of sample would make it a constant, which is generally biased unless it equals the parameter.' }, { label: 'C', text: 'Has the smallest variance among all estimators', isCorrect: false, explanation: 'Smallest variance describes an efficient estimator. Consistency is about convergence with increasing sample size.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q10', questionText: 'The confidence interval for a population mean when the population is normal and variance is known is:', answerChoices: [{ label: 'A', text: 'Sample mean plus or minus z-critical value times standard error', isCorrect: true, explanation: 'CI = x-bar +/- z_(alpha/2) x (sigma/sqrt(n)). The z-value comes from the standard normal distribution. For 95% CI, z = 1.96. Known variance allows use of z rather than t.' }, { label: 'B', text: 'Sample mean plus or minus the population standard deviation', isCorrect: false, explanation: 'The population SD must be divided by sqrt(n) to get standard error, and multiplied by the z-critical value. Just adding/subtracting SD gives incorrect width.' }, { label: 'C', text: 'Population mean plus or minus the sample standard deviation', isCorrect: false, explanation: 'Confidence intervals are built from the sample mean (not population mean, which is unknown) and account for standard error.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q11', questionText: 'An efficient estimator is one that:', answerChoices: [{ label: 'A', text: 'Has the smallest variance among all unbiased estimators of the same parameter', isCorrect: true, explanation: 'Efficiency means no other unbiased estimator has lower variance. The sample mean is the most efficient estimator of the population mean for normal populations (achieves the Cramer-Rao lower bound).' }, { label: 'B', text: 'Requires the least computation', isCorrect: false, explanation: 'Computational efficiency is different from statistical efficiency. Statistical efficiency refers to variance minimization among unbiased estimators.' }, { label: 'C', text: 'Always produces an exact answer', isCorrect: false, explanation: 'No estimator always equals the parameter. Efficiency means it has the least sampling variability among unbiased alternatives.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q12', questionText: 'The sample size needed to achieve a desired margin of error (E) with known population standard deviation and confidence level z is:', answerChoices: [{ label: 'A', text: 'n = (z x sigma / E)^2', isCorrect: true, explanation: 'From E = z x sigma/sqrt(n), solving for n gives n = (z*sigma/E)^2. Smaller desired margin or higher confidence requires larger sample size.' }, { label: 'B', text: 'n = E / (z x sigma)', isCorrect: false, explanation: 'This inverts the relationship. Smaller desired error should require more observations, not fewer.' }, { label: 'C', text: 'n = z x sigma x E', isCorrect: false, explanation: 'Multiplying these together does not give the correct sample size formula. The correct formula involves squaring the ratio.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q13', questionText: 'When sampling from a non-normal population, the Central Limit Theorem applies when sample size is at least approximately:', answerChoices: [{ label: 'A', text: '30 (as a common rule of thumb)', isCorrect: true, explanation: 'n >= 30 is the traditional guideline for CLT applicability. For highly skewed populations, larger samples may be needed. For roughly symmetric populations, smaller samples may suffice.' }, { label: 'B', text: '5', isCorrect: false, explanation: 'A sample of 5 is too small for CLT to provide a good normal approximation for most non-normal populations.' }, { label: 'C', text: '1000', isCorrect: false, explanation: 'While 1000 always ensures CLT applies, the practical threshold is much lower (approximately 30 for most distributions).' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q14', questionText: 'The t-distribution has fatter tails than the normal distribution because:', answerChoices: [{ label: 'A', text: 'It accounts for additional uncertainty from estimating the population variance with sample variance', isCorrect: true, explanation: 'When sigma is replaced by s, the resulting statistic has more variability than a z-statistic. The fatter tails of the t-distribution reflect this extra source of uncertainty, especially for small samples.' }, { label: 'B', text: 'It is always used with large samples', isCorrect: false, explanation: 'The t-distribution is most important for small samples where tail fatness is noticeable. For large df, it converges to normal.' }, { label: 'C', text: 'Financial data always has fat tails', isCorrect: false, explanation: 'While financial data often has fat tails, the t-distributions fatter tails are a mathematical property stemming from variance estimation uncertainty, not empirical data characteristics.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q15', questionText: 'A confidence interval for the difference between two population means (independent samples) requires:', answerChoices: [{ label: 'A', text: 'The difference in sample means plus or minus a critical value times the standard error of the difference', isCorrect: true, explanation: 'CI = (x1-bar - x2-bar) +/- t x SE_diff. SE_diff = sqrt(s1^2/n1 + s2^2/n2). This extends single-mean CI logic to comparing two groups.' }, { label: 'B', text: 'Only the larger of the two sample means', isCorrect: false, explanation: 'Both sample means are needed to estimate the difference. Using only one ignores the comparison entirely.' }, { label: 'C', text: 'Equal sample sizes in both groups', isCorrect: false, explanation: 'While equal sizes simplify calculation, the formula works for any sample sizes. Unequal sizes affect degrees of freedom.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q16', questionText: 'Sampling bias occurs when:', answerChoices: [{ label: 'A', text: 'The sample is not representative of the population, leading to systematically incorrect estimates', isCorrect: true, explanation: 'Sampling bias arises from non-random selection: survivorship bias (only studying survivors), look-ahead bias (using information unavailable at decision time), or self-selection bias.' }, { label: 'B', text: 'The sample size is large', isCorrect: false, explanation: 'Large samples reduce random error but do not fix systematic bias. A biased sampling method remains biased regardless of sample size.' }, { label: 'C', text: 'The population is normally distributed', isCorrect: false, explanation: 'Population distribution shape does not cause sampling bias. Bias results from how the sample is selected, not from the population characteristics.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q17', questionText: 'Data-mining bias (also known as data snooping) occurs when:', answerChoices: [{ label: 'A', text: 'Researchers search through many strategies or variables until finding statistically significant results by chance', isCorrect: true, explanation: 'Testing many hypotheses on the same data set increases the probability of finding spurious significance. With 20 tests at 5% level, one significant result is expected by chance alone.' }, { label: 'B', text: 'Data is collected from underground mines', isCorrect: false, explanation: 'Data mining bias is a statistical methodology problem, not related to physical mining. It refers to over-searching data for patterns.' }, { label: 'C', text: 'The sample size is too small', isCorrect: false, explanation: 'Small samples create imprecision but not data-mining bias specifically. Data mining occurs from extensive searching regardless of sample size.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q18', questionText: 'Survivorship bias in investment studies leads to:', answerChoices: [{ label: 'A', text: 'Overestimation of historical returns because failed funds or companies are excluded', isCorrect: true, explanation: 'When defunct funds (which typically performed poorly) are excluded from databases, the average reported return of surviving funds is biased upward. This makes investment strategies appear more successful than they were.' }, { label: 'B', text: 'Underestimation of returns', isCorrect: false, explanation: 'Removing poor performers (failures) from the data biases returns upward, not downward.' }, { label: 'C', text: 'No effect on estimated returns', isCorrect: false, explanation: 'Excluding failed entities always affects average results, typically by removing the worst performers and inflating averages.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q19', questionText: 'Look-ahead bias occurs when:', answerChoices: [{ label: 'A', text: 'A study uses information that was not available at the time investment decisions would have been made', isCorrect: true, explanation: 'Look-ahead bias uses future information to make past decisions (e.g., using revised GDP data for a model that would have used preliminary estimates). It inflates back-tested strategy performance.' }, { label: 'B', text: 'Analysts look too far into the future with forecasts', isCorrect: false, explanation: 'Making long-range forecasts is different from the bias of using unavailable information in historical analysis.' }, { label: 'C', text: 'The sample period is too short', isCorrect: false, explanation: 'Short sample periods create different problems (insufficient data, time-period bias) but not look-ahead bias specifically.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q20', questionText: 'The chi-squared distribution is used for:', answerChoices: [{ label: 'A', text: 'Testing hypotheses about a single population variance', isCorrect: true, explanation: 'The chi-squared test statistic = (n-1)s^2/sigma^2 follows a chi-squared distribution with n-1 df. It tests whether the population variance equals a hypothesized value.' }, { label: 'B', text: 'Testing the population mean', isCorrect: false, explanation: 'Population mean tests use z or t distributions. Chi-squared is specifically for variance testing and goodness-of-fit.' }, { label: 'C', text: 'Estimating correlation coefficients', isCorrect: false, explanation: 'Correlation testing uses t-distribution. Chi-squared tests variance, independence, and distributional fit.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q21', questionText: 'The F-distribution is primarily used for:', answerChoices: [{ label: 'A', text: 'Testing the equality of two population variances', isCorrect: true, explanation: 'The F-test statistic = s1^2/s2^2 follows an F-distribution under the null hypothesis of equal variances. It is also used in ANOVA and regression analysis for testing joint significance.' }, { label: 'B', text: 'Estimating population means', isCorrect: false, explanation: 'Mean estimation uses z or t distributions. The F-distribution is for comparing variances or testing groups of coefficients.' }, { label: 'C', text: 'Constructing confidence intervals for proportions', isCorrect: false, explanation: 'Proportions use the normal approximation for large samples. F-distribution handles variance comparisons.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q22', questionText: 'Time-period bias in financial research refers to:', answerChoices: [{ label: 'A', text: 'Results that are specific to the particular time period studied and may not generalize', isCorrect: true, explanation: 'A strategy tested during a bull market may not work in bear markets. Results from 2010-2020 may not apply to other decades. The specific historical context limits generalizability of findings.' }, { label: 'B', text: 'Always using the longest possible data period', isCorrect: false, explanation: 'Using long periods can help but may also include structural breaks. Time-period bias is about results being contingent on the specific period chosen.' }, { label: 'C', text: 'Measuring returns at the wrong frequency', isCorrect: false, explanation: 'Return measurement frequency is a methodological choice, not time-period bias which concerns the specific calendar period selected.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q23', questionText: 'The bootstrap method is classified as a:', answerChoices: [{ label: 'A', text: 'Resampling technique that estimates sampling distributions without parametric assumptions', isCorrect: true, explanation: 'Bootstrap is non-parametric: it uses the empirical distribution (the data itself) as the source for resampling. No assumptions about normality or other distributions are needed for the underlying data.' }, { label: 'B', text: 'Parametric estimation method requiring normality', isCorrect: false, explanation: 'Bootstrap is specifically non-parametric. It is used when parametric assumptions may not hold.' }, { label: 'C', text: 'A method that requires very small sample sizes', isCorrect: false, explanation: 'Bootstrap works with any sample size but is most valuable when the sample is too small for asymptotic (large-sample) theory to apply reliably.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q24', questionText: 'The jackknife estimator works by:', answerChoices: [{ label: 'A', text: 'Systematically leaving out one observation at a time and recalculating the statistic', isCorrect: true, explanation: 'Jackknife creates n samples of size n-1 by removing each observation once. The variation in the statistic across leave-one-out samples estimates standard error and detects influential observations.' }, { label: 'B', text: 'Adding random noise to each observation', isCorrect: false, explanation: 'Adding noise describes jittering or perturbation methods, not the jackknife which systematically removes observations.' }, { label: 'C', text: 'Doubling the sample size artificially', isCorrect: false, explanation: 'Jackknife reduces the effective sample (to n-1) for each subsample. It does not increase sample size.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q25', questionText: 'A desirable property of an estimator that combines unbiasedness and minimum variance is called:', answerChoices: [{ label: 'A', text: 'BLUE (Best Linear Unbiased Estimator) in the context of regression', isCorrect: true, explanation: 'BLUE means: Best (minimum variance), Linear (linear function of the data), Unbiased (expected value equals parameter), Estimator. OLS achieves BLUE under Gauss-Markov assumptions.' }, { label: 'B', text: 'Robustness', isCorrect: false, explanation: 'Robustness means performance is maintained when assumptions are violated. BLUE specifically refers to minimum variance among linear unbiased estimators.' }, { label: 'C', text: 'Sufficiency', isCorrect: false, explanation: 'Sufficiency means the statistic captures all information in the data about the parameter. It is related but different from BLUE.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q26', questionText: 'The width of a confidence interval is determined by:', answerChoices: [{ label: 'A', text: 'The confidence level, sample size, and variability in the data', isCorrect: true, explanation: 'Width = 2 x critical value x SE = 2 x z_(alpha/2) x sigma/sqrt(n). Higher confidence (larger z), more variability (larger sigma), or smaller sample (smaller n) all widen the interval.' }, { label: 'B', text: 'Only the sample mean', isCorrect: false, explanation: 'The sample mean centers the interval but does not determine its width. Width depends on variability, sample size, and confidence level.' }, { label: 'C', text: 'The population parameter value', isCorrect: false, explanation: 'The parameter is unknown (thats why we build CIs). Width is determined by sample characteristics and desired confidence level.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m7-q27', questionText: 'When the population distribution is non-normal and sample size is small (n < 30), the analyst should:', answerChoices: [{ label: 'A', text: 'Use nonparametric methods or bootstrap techniques rather than standard z or t intervals', isCorrect: true, explanation: 'With non-normal populations and small samples, CLT does not apply well. Nonparametric methods (sign test, Wilcoxon) or bootstrap intervals provide valid inference without normality assumptions.' }, { label: 'B', text: 'Always use the z-distribution', isCorrect: false, explanation: 'The z-distribution requires either known variance with normality or CLT approximation (large n). Neither condition is met here.' }, { label: 'C', text: 'Ignore the non-normality and proceed with standard methods', isCorrect: false, explanation: 'Ignoring non-normality with small samples can produce unreliable confidence intervals and misleading hypothesis test results.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Estimation and Inference', provider: 'cfa-portal', questionSourceFile: null },
];

// Module 8: Hypothesis Testing (43 questions)
const module8Questions: Question[] = [
  { id: 'qm-m8-q1', questionText: 'The null hypothesis (H0) is best described as:', answerChoices: [{ label: 'A', text: 'The hypothesis of no effect or no difference that is tested for possible rejection', isCorrect: true, explanation: 'H0 is the status quo hypothesis. We assume it is true and look for evidence against it. Rejection requires sufficient statistical evidence, which protects against false claims of effects.' }, { label: 'B', text: 'The hypothesis the researcher hopes to prove', isCorrect: false, explanation: 'The researcher hopes to prove the alternative hypothesis (Ha). The null is what we try to reject, not support.' }, { label: 'C', text: 'A hypothesis that is always true', isCorrect: false, explanation: 'The null may or may not be true. We test whether the evidence is strong enough to reject it, without knowing its truth with certainty.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q2', questionText: 'A Type I error occurs when:', answerChoices: [{ label: 'A', text: 'The null hypothesis is true but is rejected (false positive)', isCorrect: true, explanation: 'Type I error = rejecting a true null = concluding there is an effect when there is none. The significance level (alpha) is the maximum acceptable probability of Type I error.' }, { label: 'B', text: 'The null hypothesis is false but is not rejected (false negative)', isCorrect: false, explanation: 'This describes a Type II error (beta): failing to detect a real effect. Type I is about incorrectly rejecting truth.' }, { label: 'C', text: 'The sample size is too small', isCorrect: false, explanation: 'Small sample size reduces power (increases Type II error probability) but does not define Type I error itself.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q3', questionText: 'The p-value of a hypothesis test represents:', answerChoices: [{ label: 'A', text: 'The probability of obtaining results at least as extreme as observed, assuming the null hypothesis is true', isCorrect: true, explanation: 'p-value = P(data this extreme or more | H0 true). Small p-values indicate the observed data is unlikely under H0, providing evidence against H0. Reject H0 when p-value < alpha.' }, { label: 'B', text: 'The probability that the null hypothesis is true', isCorrect: false, explanation: 'This is a common misinterpretation. The p-value is about the data given H0, not about H0 given the data (which requires Bayesian analysis).' }, { label: 'C', text: 'The probability of a Type II error', isCorrect: false, explanation: 'Type II error probability (beta) is about failing to reject a false null. The p-value relates to the observed data under the null hypothesis.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q4', questionText: 'Statistical power of a hypothesis test is defined as:', answerChoices: [{ label: 'A', text: 'The probability of correctly rejecting a false null hypothesis (1 - beta)', isCorrect: true, explanation: 'Power = P(reject H0 | H0 is false) = 1 - P(Type II error). Higher power means better ability to detect real effects. Power increases with sample size, effect size, and significance level.' }, { label: 'B', text: 'The probability of a Type I error', isCorrect: false, explanation: 'Type I error probability is alpha (significance level). Power relates to Type II error: Power = 1 - beta.' }, { label: 'C', text: 'The sample size divided by the population size', isCorrect: false, explanation: 'This ratio is the sampling fraction, unrelated to statistical power which measures detection ability.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q5', questionText: 'A two-tailed test at the 5% significance level rejects H0 when:', answerChoices: [{ label: 'A', text: 'The test statistic falls in either the upper 2.5% or lower 2.5% of the distribution', isCorrect: true, explanation: 'Two-tailed splits alpha equally between both tails: 5%/2 = 2.5% in each tail. For z-test, reject if |z| > 1.96. This tests for effects in either direction.' }, { label: 'B', text: 'The test statistic falls in the upper 5% only', isCorrect: false, explanation: 'Upper 5% only is a one-tailed (right-tail) test. A two-tailed test allocates 2.5% to each tail.' }, { label: 'C', text: 'The p-value is greater than 0.05', isCorrect: false, explanation: 'p-value > alpha means we fail to reject H0. Rejection requires p-value < alpha.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q6', questionText: 'The test statistic for a hypothesis test about a population mean with known variance is:', answerChoices: [{ label: 'A', text: 'z = (sample mean - hypothesized mean) / (sigma / sqrt(n))', isCorrect: true, explanation: 'The z-statistic measures how many standard errors the sample mean is from the hypothesized value. Larger absolute values provide stronger evidence against H0.' }, { label: 'B', text: 'The sample mean minus the population mean', isCorrect: false, explanation: 'The raw difference must be standardized by dividing by the standard error to create a z-statistic with a known distribution.' }, { label: 'C', text: 'The sample variance divided by n', isCorrect: false, explanation: 'This would be the variance of the sample mean, not a test statistic. The test statistic standardizes the difference between observed and hypothesized values.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q7', questionText: 'When testing at alpha = 0.05 with a sample of n = 25 and unknown population variance, the critical value comes from:', answerChoices: [{ label: 'A', text: 'A t-distribution with 24 degrees of freedom', isCorrect: true, explanation: 'With unknown variance and small sample from a normal population, use t with df = n - 1 = 24. The t-critical value is slightly larger than z-critical (about 2.064 vs 1.96 for two-tailed 5%).' }, { label: 'B', text: 'A standard normal (z) distribution', isCorrect: false, explanation: 'Standard normal is used when population variance is known. With unknown variance and n = 25, the t-distribution is appropriate.' }, { label: 'C', text: 'A chi-squared distribution with 25 degrees of freedom', isCorrect: false, explanation: 'Chi-squared is used for variance testing, not mean testing. And degrees of freedom for mean tests are n - 1, not n.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q8', questionText: 'A one-tailed test is appropriate when:', answerChoices: [{ label: 'A', text: 'The alternative hypothesis specifies a direction (greater than or less than)', isCorrect: true, explanation: 'One-tailed tests detect effects in one direction only. Ha: mu > mu0 or Ha: mu < mu0. All alpha is in one tail, making it easier to detect effects in that specific direction.' }, { label: 'B', text: 'The researcher has no prior expectation about direction', isCorrect: false, explanation: 'No directional expectation calls for a two-tailed test that can detect effects in either direction.' }, { label: 'C', text: 'The sample size is exactly one', isCorrect: false, explanation: 'Sample size of one is insufficient for most statistical tests. One-tailed vs two-tailed depends on the hypothesis, not sample size.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q9', questionText: 'Increasing the sample size while holding alpha constant will:', answerChoices: [{ label: 'A', text: 'Increase the power of the test and reduce the probability of Type II error', isCorrect: true, explanation: 'Larger samples provide more precise estimates (smaller SE), making it easier to detect true differences. Power = 1 - beta increases, and beta (Type II error probability) decreases.' }, { label: 'B', text: 'Increase the probability of Type I error', isCorrect: false, explanation: 'Type I error probability equals alpha, which is held constant by assumption. Larger samples do not affect alpha.' }, { label: 'C', text: 'Have no effect on the test outcome', isCorrect: false, explanation: 'Larger samples can turn non-significant results into significant ones by reducing standard error and increasing the test statistic magnitude.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q10', questionText: 'The decision rule for a hypothesis test compares:', answerChoices: [{ label: 'A', text: 'The calculated test statistic to the critical value(s) determined by the significance level', isCorrect: true, explanation: 'If |test statistic| > critical value (two-tailed), reject H0. The critical value creates the boundary of the rejection region based on the desired alpha level.' }, { label: 'B', text: 'The sample mean to the population mean directly', isCorrect: false, explanation: 'Raw comparison ignores sampling variability. We standardize through the test statistic and compare to a distributional critical value.' }, { label: 'C', text: 'Two different sample sizes', isCorrect: false, explanation: 'Hypothesis testing compares a test statistic to a critical value, not sample sizes to each other.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q11', questionText: 'Statistical significance does not necessarily imply economic significance because:', answerChoices: [{ label: 'A', text: 'A statistically significant result may be too small to be practically important after transaction costs', isCorrect: true, explanation: 'With large samples, even tiny effects become statistically significant. A 0.01% excess return may be significant with enough data but worthless after trading costs. Practical importance requires considering magnitude and costs.' }, { label: 'B', text: 'Statistical significance is always more important than economic significance', isCorrect: false, explanation: 'For investment decisions, economic significance (net profitability) matters more than statistical significance (whether the effect is non-zero).' }, { label: 'C', text: 'Economic significance requires a p-value of zero', isCorrect: false, explanation: 'No result ever has p-value = 0. Economic significance is about practical importance of the magnitude, not about achieving perfect statistical certainty.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q12', questionText: 'For a paired difference test, the test statistic is calculated using:', answerChoices: [{ label: 'A', text: 'The mean of the paired differences divided by the standard error of the differences', isCorrect: true, explanation: 't = d-bar / (s_d / sqrt(n)), where d-bar is the mean difference and s_d is the standard deviation of differences. Pairing controls for subject-specific effects (before/after, twins, etc.).' }, { label: 'B', text: 'The difference between two independent sample means', isCorrect: false, explanation: 'Independent sample means require a different formula. Paired tests use within-pair differences, which is more powerful when pairs are correlated.' }, { label: 'C', text: 'The ratio of two sample variances', isCorrect: false, explanation: 'Variance ratio is the F-test for equality of variances, not a paired difference test.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q13', questionText: 'The significance level (alpha) represents:', answerChoices: [{ label: 'A', text: 'The maximum probability of Type I error that the researcher is willing to accept', isCorrect: true, explanation: 'Alpha sets the threshold for rejection. At alpha = 5%, we accept up to a 5% chance of falsely rejecting a true null. Lower alpha makes the test more conservative (harder to reject H0).' }, { label: 'B', text: 'The probability that the test is correct', isCorrect: false, explanation: 'Alpha is the error rate, not the accuracy rate. The probability of a correct decision depends on whether H0 is true or false.' }, { label: 'C', text: 'The sample size requirement', isCorrect: false, explanation: 'Alpha is chosen by the researcher before testing. Sample size is determined separately based on desired power and effect size.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q14', questionText: 'A test of whether a portfolio manager generates alpha uses the hypotheses:', answerChoices: [{ label: 'A', text: 'H0: alpha = 0 versus Ha: alpha > 0 (one-tailed test)', isCorrect: true, explanation: 'We test whether the manager adds value above the benchmark. H0 assumes no skill (alpha = 0). Ha specifies a positive direction since we seek evidence of positive alpha (outperformance).' }, { label: 'B', text: 'H0: alpha > 0 versus Ha: alpha = 0', isCorrect: false, explanation: 'This reverses the hypotheses. H0 should contain the equality condition. The null is always the no-effect hypothesis.' }, { label: 'C', text: 'H0: alpha = 1 versus Ha: alpha = 0', isCorrect: false, explanation: 'Alpha represents excess return, and 100% (alpha = 1) is not a meaningful null hypothesis for manager testing.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q15', questionText: 'The relationship between confidence intervals and hypothesis tests is:', answerChoices: [{ label: 'A', text: 'Failing to reject H0 at alpha corresponds to the hypothesized value falling within the (1-alpha) confidence interval', isCorrect: true, explanation: 'A 95% CI contains all values that would not be rejected at the 5% level. If the hypothesized value is inside the CI, the test does not reject. If outside, it rejects. They are mathematically equivalent.' }, { label: 'B', text: 'They are completely unrelated statistical tools', isCorrect: false, explanation: 'Confidence intervals and hypothesis tests are duals of each other, providing equivalent information in different formats.' }, { label: 'C', text: 'Confidence intervals always give narrower conclusions', isCorrect: false, explanation: 'CI gives more information (a range of plausible values), not narrower conclusions. They are complementary to hypothesis tests.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q16', questionText: 'To test whether two populations have equal means with independent samples and unequal variances, the appropriate test is:', answerChoices: [{ label: 'A', text: 'Welch t-test (approximate t-test with modified degrees of freedom)', isCorrect: true, explanation: 'The Welch t-test does not assume equal variances. It uses s1^2/n1 + s2^2/n2 for the standard error and a complex formula for approximate degrees of freedom (Welch-Satterthwaite).' }, { label: 'B', text: 'Paired t-test', isCorrect: false, explanation: 'Paired tests require matched/dependent observations, not independent samples from two populations.' }, { label: 'C', text: 'Z-test with known variances', isCorrect: false, explanation: 'The z-test requires known population variances. When variances are unknown and unequal, the Welch t-test is appropriate.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q17', questionText: 'The chi-squared test for variance tests H0: sigma^2 = sigma0^2. The test statistic is:', answerChoices: [{ label: 'A', text: '(n-1) x s^2 / sigma0^2, which follows a chi-squared distribution with n-1 degrees of freedom', isCorrect: true, explanation: 'Chi-sq = (n-1)s^2/sigma0^2. Under H0, this follows chi-sq(n-1). The chi-squared distribution is right-skewed and non-negative, matching variance properties.' }, { label: 'B', text: 's / sigma0, which follows a normal distribution', isCorrect: false, explanation: 'This ratio does not follow a standard distribution. The chi-squared test uses the quadratic form (n-1)s^2/sigma0^2.' }, { label: 'C', text: 'n x s^2 / sigma0^2, which follows an F-distribution', isCorrect: false, explanation: 'F-distribution involves a ratio of two chi-squared variables. Single variance testing uses chi-squared directly with (n-1) in the numerator.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q18', questionText: 'Multiple testing corrections (like Bonferroni) are needed when:', answerChoices: [{ label: 'A', text: 'Conducting many hypothesis tests simultaneously to control the overall family-wise error rate', isCorrect: true, explanation: 'With k independent tests at alpha, the probability of at least one false rejection is 1-(1-alpha)^k. Bonferroni uses alpha/k per test to maintain the overall error rate at alpha. This prevents spurious discoveries.' }, { label: 'B', text: 'The sample size is very large', isCorrect: false, explanation: 'Large samples do not require multiple testing corrections. The correction addresses the increased false positive rate from testing many hypotheses.' }, { label: 'C', text: 'Only one hypothesis is being tested', isCorrect: false, explanation: 'A single test does not need correction. Multiple testing corrections apply specifically when many tests are conducted simultaneously.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q19', questionText: 'Failing to reject the null hypothesis means:', answerChoices: [{ label: 'A', text: 'There is insufficient evidence to conclude the alternative hypothesis is true', isCorrect: true, explanation: 'Failure to reject is not proof of H0. It means the data does not provide strong enough evidence against H0. The effect may exist but be too small to detect with the given sample size.' }, { label: 'B', text: 'The null hypothesis has been proven true', isCorrect: false, explanation: 'Hypothesis tests cannot prove H0 true. They can only reject or fail to reject. Absence of evidence is not evidence of absence.' }, { label: 'C', text: 'The study was conducted incorrectly', isCorrect: false, explanation: 'A well-conducted study can legitimately fail to reject H0 if the effect is small or the sample size is insufficient for detection.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q20', questionText: 'The F-test for equality of two variances uses the test statistic:', answerChoices: [{ label: 'A', text: 'The ratio of the larger sample variance to the smaller sample variance', isCorrect: true, explanation: 'F = s1^2/s2^2 (with the larger in the numerator by convention). Under H0: sigma1^2 = sigma2^2, this follows an F-distribution with (n1-1, n2-1) degrees of freedom.' }, { label: 'B', text: 'The difference between the two sample variances', isCorrect: false, explanation: 'The difference of variances does not have a standard sampling distribution. The ratio (F-statistic) has the well-known F-distribution under the null.' }, { label: 'C', text: 'The product of the two sample variances', isCorrect: false, explanation: 'Product of variances has no standard distribution or interpretation as a test statistic.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q21', questionText: 'Effect size in hypothesis testing measures:', answerChoices: [{ label: 'A', text: 'The practical magnitude of the difference or relationship, independent of sample size', isCorrect: true, explanation: 'Effect size (e.g., Cohens d, R-squared) measures how large the detected effect is. Unlike p-values, effect sizes do not grow with sample size and directly address practical importance.' }, { label: 'B', text: 'The probability of rejecting the null hypothesis', isCorrect: false, explanation: 'Probability of rejection relates to power (if H0 is false) or alpha (if H0 is true). Effect size measures magnitude, not probability.' }, { label: 'C', text: 'The sample size needed for the study', isCorrect: false, explanation: 'Effect size is an input to sample size calculations, but is itself a measure of magnitude, not a sample size.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q22', questionText: 'When testing H0: mu >= 10 versus Ha: mu < 10, this is a:', answerChoices: [{ label: 'A', text: 'One-tailed (left-tail) test', isCorrect: true, explanation: 'The alternative Ha: mu < 10 specifies a direction (left/lower). The rejection region is entirely in the left tail. We reject H0 only if the sample mean is sufficiently below 10.' }, { label: 'B', text: 'Two-tailed test', isCorrect: false, explanation: 'Two-tailed tests have Ha: mu != 10 (not equal). Here Ha specifies mu < 10, which is one direction only.' }, { label: 'C', text: 'One-tailed (right-tail) test', isCorrect: false, explanation: 'Right-tail tests have Ha: mu > value. Here the alternative is mu < 10, so the rejection region is in the left tail.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q23', questionText: 'A researcher finds a p-value of 0.03. At the 1% significance level, the decision is to:', answerChoices: [{ label: 'A', text: 'Fail to reject H0 because p-value (0.03) > alpha (0.01)', isCorrect: true, explanation: 'We reject H0 only when p-value < alpha. Here 0.03 > 0.01, so we do not have sufficient evidence at the 1% level. Note: we would reject at 5% level since 0.03 < 0.05.' }, { label: 'B', text: 'Reject H0', isCorrect: false, explanation: 'Rejection requires p-value < alpha. Since 0.03 > 0.01, we cannot reject at the 1% significance level.' }, { label: 'C', text: 'Conclude the test is invalid', isCorrect: false, explanation: 'A p-value of 0.03 is a valid result. It simply does not meet the stringent 1% threshold for rejection.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q24', questionText: 'The power of a test can be increased by all of the following EXCEPT:', answerChoices: [{ label: 'A', text: 'Decreasing the significance level (alpha)', isCorrect: true, explanation: 'Decreasing alpha makes the test more conservative (harder to reject), which reduces power. All other options (increasing n, larger effect size, one-tailed test, reducing variability) increase power.' }, { label: 'B', text: 'Increasing the sample size', isCorrect: false, explanation: 'Larger samples provide more precise estimates and larger test statistics, directly increasing power.' }, { label: 'C', text: 'Using a one-tailed test instead of two-tailed', isCorrect: false, explanation: 'One-tailed concentrates all alpha in one direction, giving more rejection region and higher power for effects in that direction.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q25', questionText: 'In testing whether the variance of portfolio returns equals a target level, we use the:', answerChoices: [{ label: 'A', text: 'Chi-squared test because variance testing requires a chi-squared distribution', isCorrect: true, explanation: 'The chi-squared distribution arises naturally when testing variance: chi-sq = (n-1)s^2/sigma0^2. It is non-negative and right-skewed, matching the properties of variance estimates.' }, { label: 'B', text: 'Z-test because the normal distribution applies', isCorrect: false, explanation: 'Z-tests apply to mean testing with known variance. Variance testing uses chi-squared or F-distributions.' }, { label: 'C', text: 'T-test with n-1 degrees of freedom', isCorrect: false, explanation: 'T-tests are for mean testing with unknown variance. Chi-squared is used for testing the variance itself.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q26', questionText: 'A Type II error in evaluating a trading strategy means:', answerChoices: [{ label: 'A', text: 'Concluding the strategy does not work when it actually does (missing a profitable opportunity)', isCorrect: true, explanation: 'Type II error fails to reject H0 (no alpha) when Ha is true (strategy works). The investor misses a genuine opportunity because the test lacked power to detect it.' }, { label: 'B', text: 'Concluding the strategy works when it does not (pursuing a bad strategy)', isCorrect: false, explanation: 'This describes Type I error: rejecting a true null and implementing a strategy that actually has no alpha.' }, { label: 'C', text: 'The trading costs exceed the alpha', isCorrect: false, explanation: 'Transaction costs relate to economic significance, not to the statistical definition of Type II error.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q27', questionText: 'The test statistic for testing whether a correlation coefficient equals zero is:', answerChoices: [{ label: 'A', text: 't = r x sqrt(n-2) / sqrt(1-r^2), with n-2 degrees of freedom', isCorrect: true, explanation: 'Under H0: rho = 0, this t-statistic tests whether the sample correlation is significantly different from zero. It follows a t-distribution with n-2 degrees of freedom.' }, { label: 'B', text: 'The correlation coefficient itself', isCorrect: false, explanation: 'The correlation coefficient ranges from -1 to +1 and does not have a t-distribution. It must be transformed into a test statistic with a known distribution.' }, { label: 'C', text: 'The square of the correlation coefficient (R-squared)', isCorrect: false, explanation: 'R-squared measures explanatory power but is not the appropriate test statistic for testing significance of correlation.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q28', questionText: 'When the test statistic falls in the acceptance region (fails to reject H0):', answerChoices: [{ label: 'A', text: 'The data is consistent with the null hypothesis but does not prove it true', isCorrect: true, explanation: 'Non-rejection means the data does not provide enough evidence to conclude Ha. H0 remains a possibility but is not proven. A larger sample or different test might reach a different conclusion.' }, { label: 'B', text: 'The null hypothesis is proven true with certainty', isCorrect: false, explanation: 'Statistical tests cannot prove hypotheses true. They only provide evidence for or against, with associated probability of error.' }, { label: 'C', text: 'The alternative hypothesis is impossible', isCorrect: false, explanation: 'The alternative may still be true; the test simply failed to detect it (possibly due to insufficient power).' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q29', questionText: 'The steps of hypothesis testing in order are:', answerChoices: [{ label: 'A', text: 'State hypotheses, select significance level, calculate test statistic, make decision', isCorrect: true, explanation: 'The proper sequence: (1) state H0 and Ha, (2) choose alpha and determine critical value, (3) collect data and compute test statistic, (4) compare to critical value (or p-value to alpha) and conclude.' }, { label: 'B', text: 'Collect data, then decide what to test', isCorrect: false, explanation: 'Choosing hypotheses after seeing data introduces bias. Hypotheses must be specified before examining results (to avoid data snooping).' }, { label: 'C', text: 'Calculate the p-value, then choose the significance level', isCorrect: false, explanation: 'Choosing alpha after computing the p-value allows gaming the result. Alpha must be set before testing to maintain the error rate guarantee.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q30', questionText: 'A test of whether two populations have equal variances uses:', answerChoices: [{ label: 'A', text: 'The F-test with the ratio of sample variances as the test statistic', isCorrect: true, explanation: 'F = s1^2/s2^2 follows an F(n1-1, n2-1) distribution under H0: sigma1^2 = sigma2^2. This test is important before choosing between pooled and Welch t-tests for mean comparison.' }, { label: 'B', text: 'The t-test comparing sample means', isCorrect: false, explanation: 'T-tests compare means, not variances. Variance equality is tested separately using the F-distribution.' }, { label: 'C', text: 'The z-test with known population parameters', isCorrect: false, explanation: 'Z-tests for variance do not exist in the standard framework. Variance testing uses F and chi-squared distributions.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q31', questionText: 'In a hypothesis test with high power (e.g., 0.95), the probability of Type II error is:', answerChoices: [{ label: 'A', text: '0.05 (since beta = 1 - power)', isCorrect: true, explanation: 'Power = 1 - beta, so beta = 1 - power = 1 - 0.95 = 0.05. High power (95%) means only a 5% chance of failing to detect a real effect. This is a well-designed test.' }, { label: 'B', text: '0.95', isCorrect: false, explanation: '0.95 is the power (probability of correct rejection), not the Type II error rate.' }, { label: 'C', text: 'Cannot be determined from the given information', isCorrect: false, explanation: 'Given power = 0.95, we can directly calculate beta = 1 - 0.95 = 0.05.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q32', questionText: 'An analyst tests whether the mean return of a fund exceeds 5% using H0: mu <= 5% and Ha: mu > 5%. With a test statistic of 2.3 and critical value of 1.645, the conclusion is:', answerChoices: [{ label: 'A', text: 'Reject H0 because the test statistic (2.3) exceeds the critical value (1.645)', isCorrect: true, explanation: 'For a right-tail test, reject when test statistic > critical value. Here 2.3 > 1.645, so we have sufficient evidence that the mean return exceeds 5% at the given significance level.' }, { label: 'B', text: 'Fail to reject H0', isCorrect: false, explanation: 'We reject when the test statistic exceeds the critical value. Since 2.3 > 1.645, we do reject H0.' }, { label: 'C', text: 'The test is inconclusive', isCorrect: false, explanation: 'The test gives a clear conclusion: the statistic is in the rejection region, so we reject H0 in favor of Ha.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q33', questionText: 'The tradeoff between Type I and Type II errors is that:', answerChoices: [{ label: 'A', text: 'Reducing the probability of one type of error increases the probability of the other, holding sample size constant', isCorrect: true, explanation: 'For a fixed sample size, lowering alpha (less Type I error) raises beta (more Type II error) because the acceptance region expands, making it harder to reject even when H0 is false.' }, { label: 'B', text: 'Both can be reduced simultaneously by lowering alpha', isCorrect: false, explanation: 'Lowering alpha reduces Type I error but increases Type II error. Only increasing sample size can reduce both simultaneously.' }, { label: 'C', text: 'They are independent of each other', isCorrect: false, explanation: 'They are inversely related for a given sample size. The rejection region cannot simultaneously become narrower (less Type I) and more sensitive (less Type II).' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q34', questionText: 'A non-parametric test is preferred over a parametric test when:', answerChoices: [{ label: 'A', text: 'The data violates the assumptions required by parametric tests (e.g., non-normal, ordinal data)', isCorrect: true, explanation: 'Non-parametric tests (sign test, Wilcoxon, Mann-Whitney) make fewer distributional assumptions. They work with ordinal data, small samples from non-normal populations, and are robust to outliers.' }, { label: 'B', text: 'The sample size is very large', isCorrect: false, explanation: 'Large samples actually favor parametric tests because CLT ensures approximately normal sampling distributions.' }, { label: 'C', text: 'The researcher wants maximum statistical power', isCorrect: false, explanation: 'Parametric tests generally have more power when their assumptions are met. Non-parametric tests trade some power for robustness.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q35', questionText: 'The Wilcoxon signed-rank test is the non-parametric alternative to:', answerChoices: [{ label: 'A', text: 'The paired t-test for matched samples', isCorrect: true, explanation: 'Wilcoxon signed-rank uses ranks of absolute differences rather than the differences themselves. It does not require normally distributed differences, making it suitable for small samples from non-normal populations.' }, { label: 'B', text: 'The F-test for variances', isCorrect: false, explanation: 'There is no standard non-parametric equivalent of the F-test. Wilcoxon signed-rank addresses location (central tendency), not dispersion.' }, { label: 'C', text: 'The chi-squared test for independence', isCorrect: false, explanation: 'Chi-squared for independence is already non-parametric. Wilcoxon signed-rank is the non-parametric version of paired t-test.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q36', questionText: 'When testing at alpha = 0.05, a result with p-value = 0.001 suggests:', answerChoices: [{ label: 'A', text: 'Very strong evidence against H0, and H0 should be rejected', isCorrect: true, explanation: 'p = 0.001 is far below alpha = 0.05, indicating the observed result is extremely unlikely under H0. This provides very strong evidence against the null hypothesis.' }, { label: 'B', text: 'Marginal evidence, and the decision could go either way', isCorrect: false, explanation: 'Marginal evidence would be a p-value near alpha (e.g., 0.04 or 0.06). p = 0.001 is decisively in the rejection region.' }, { label: 'C', text: 'The null hypothesis is certainly false', isCorrect: false, explanation: 'No p-value can prove H0 false with certainty. But p = 0.001 provides very strong evidence against it.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q37', questionText: 'The Mann-Whitney U test is the non-parametric alternative to:', answerChoices: [{ label: 'A', text: 'The independent samples t-test for comparing two population means', isCorrect: true, explanation: 'Mann-Whitney compares medians/distributions of two independent groups using ranks rather than raw values. It does not require normal populations and works with ordinal data.' }, { label: 'B', text: 'The paired t-test', isCorrect: false, explanation: 'The paired equivalent is the Wilcoxon signed-rank test. Mann-Whitney is for independent (unpaired) samples.' }, { label: 'C', text: 'Analysis of variance (ANOVA)', isCorrect: false, explanation: 'The Kruskal-Wallis test is the non-parametric alternative to one-way ANOVA. Mann-Whitney handles only two groups.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q38', questionText: 'A confidence interval that does not contain zero for the difference between two means suggests:', answerChoices: [{ label: 'A', text: 'The difference is statistically significant at the corresponding alpha level', isCorrect: true, explanation: 'If zero is not in the CI for the difference, the hypothesis test would reject H0: mu1 - mu2 = 0 at the same alpha. The CI and test agree: there is a statistically significant difference.' }, { label: 'B', text: 'The means are equal', isCorrect: false, explanation: 'If the CI excludes zero, the means are statistically different, not equal.' }, { label: 'C', text: 'The test has low power', isCorrect: false, explanation: 'Excluding zero from the CI indicates sufficient power was available to detect the difference. Low power would result in wide CIs that include zero.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q39', questionText: 'The Kruskal-Wallis test is used to:', answerChoices: [{ label: 'A', text: 'Compare medians across three or more independent groups when normality cannot be assumed', isCorrect: true, explanation: 'Kruskal-Wallis is the non-parametric alternative to one-way ANOVA. It ranks all observations together and tests whether the groups have different rank distributions, without requiring normal populations.' }, { label: 'B', text: 'Test for correlation between two variables', isCorrect: false, explanation: 'Correlation testing uses Pearson or Spearman coefficients with appropriate tests, not Kruskal-Wallis.' }, { label: 'C', text: 'Compare variances between two groups', isCorrect: false, explanation: 'Variance comparison uses F-test or Levene test. Kruskal-Wallis compares locations (medians) across multiple groups.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q40', questionText: 'The concept of practical significance suggests that analysts should:', answerChoices: [{ label: 'A', text: 'Consider whether statistically significant results are large enough to matter for decision-making', isCorrect: true, explanation: 'A trading strategy with statistically significant but tiny alpha (e.g., 0.01% monthly) may not cover transaction costs. Practical significance asks: Is the effect large enough to be economically meaningful?' }, { label: 'B', text: 'Ignore p-values entirely', isCorrect: false, explanation: 'P-values provide useful information about whether an effect exists. Practical significance supplements, not replaces, statistical significance.' }, { label: 'C', text: 'Always use the largest possible sample size', isCorrect: false, explanation: 'Large samples can detect tiny effects that lack practical importance. The point is to evaluate magnitude, not just significance.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q41', questionText: 'The sign test is the simplest non-parametric test for:', answerChoices: [{ label: 'A', text: 'Testing whether the median of a population equals a hypothesized value', isCorrect: true, explanation: 'The sign test counts observations above and below the hypothesized median and uses the binomial distribution to determine if the split is significantly unbalanced. It only requires ordinal data.' }, { label: 'B', text: 'Comparing the means of three groups', isCorrect: false, explanation: 'Three-group comparison uses ANOVA or Kruskal-Wallis. The sign test is for one-sample or paired comparisons.' }, { label: 'C', text: 'Testing for linear regression significance', isCorrect: false, explanation: 'Regression significance testing uses F-tests and t-tests, not the sign test.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q42', questionText: 'When sample size is very large, hypothesis tests become:', answerChoices: [{ label: 'A', text: 'More likely to reject H0 even for trivially small effects that lack practical importance', isCorrect: true, explanation: 'Standard error = sigma/sqrt(n) shrinks with large n, making even tiny deviations from H0 statistically significant. This is why effect size and practical significance must complement p-values.' }, { label: 'B', text: 'Less reliable', isCorrect: false, explanation: 'Large samples are more reliable in the statistical sense. The issue is that they may detect effects too small to matter practically.' }, { label: 'C', text: 'Unable to reject H0 regardless of the true effect', isCorrect: false, explanation: 'Large samples make rejection easier, not harder. With enough data, even minute effects become significant.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m8-q43', questionText: 'The Runs test is used to test:', answerChoices: [{ label: 'A', text: 'Whether a sequence of observations is random (no pattern or serial dependence)', isCorrect: true, explanation: 'A run is a consecutive sequence of the same type (e.g., positive returns). Too few runs suggest trending; too many suggest mean-reversion. The test detects non-randomness in sequences.' }, { label: 'B', text: 'Whether two variables are correlated', isCorrect: false, explanation: 'Correlation tests use Pearson or Spearman statistics. The Runs test examines randomness of a single sequence.' }, { label: 'C', text: 'Whether the population mean equals a specific value', isCorrect: false, explanation: 'Mean testing uses z or t tests. The Runs test specifically addresses randomness/independence of a sequence.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Hypothesis Testing', provider: 'cfa-portal', questionSourceFile: null },
];

// Module 9: Parametric and Non-Parametric Tests of Independence (7 questions)
const module9Questions: Question[] = [
  { id: 'qm-m9-q1', questionText: 'The chi-squared test of independence tests whether:', answerChoices: [{ label: 'A', text: 'Two categorical variables are related or independent of each other', isCorrect: true, explanation: 'The chi-squared independence test compares observed frequencies in a contingency table to expected frequencies under independence. Large deviations indicate the variables are associated.' }, { label: 'B', text: 'A continuous variable is normally distributed', isCorrect: false, explanation: 'Testing for normality uses the chi-squared goodness-of-fit test or Jarque-Bera test, not the independence test.' }, { label: 'C', text: 'Two population means are equal', isCorrect: false, explanation: 'Mean comparison uses t-tests or z-tests. Chi-squared independence test works with categorical (count) data.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Parametric and Non-Parametric Tests of Independence', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m9-q2', questionText: 'The degrees of freedom for a chi-squared test of independence with r rows and c columns is:', answerChoices: [{ label: 'A', text: '(r-1) x (c-1)', isCorrect: true, explanation: 'df = (rows-1)(columns-1). For a 3x4 table: df = 2 x 3 = 6. This accounts for the constraints imposed by fixed row and column totals in the contingency table.' }, { label: 'B', text: 'r x c', isCorrect: false, explanation: 'r x c is the total number of cells. Degrees of freedom must subtract constraints from row totals, column totals, and the grand total.' }, { label: 'C', text: 'r + c - 1', isCorrect: false, explanation: 'This formula is used for other statistics. Chi-squared independence uses the product formula (r-1)(c-1).' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Parametric and Non-Parametric Tests of Independence', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m9-q3', questionText: 'The expected frequency for a cell in a contingency table under the null hypothesis of independence equals:', answerChoices: [{ label: 'A', text: '(Row total x Column total) / Grand total', isCorrect: true, explanation: 'Under independence, P(row i AND column j) = P(row i) x P(column j). Expected count = n x P(row i) x P(column j) = (row total x column total) / grand total.' }, { label: 'B', text: 'The observed frequency divided by 2', isCorrect: false, explanation: 'Dividing observed by 2 has no statistical basis. Expected frequencies depend on marginal totals under the independence assumption.' }, { label: 'C', text: 'The grand total divided by the number of cells', isCorrect: false, explanation: 'This gives equal expected frequencies in all cells, which is only correct when all row and column totals are equal.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Parametric and Non-Parametric Tests of Independence', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m9-q4', questionText: 'The chi-squared test statistic is calculated as:', answerChoices: [{ label: 'A', text: 'The sum of (Observed - Expected)^2 / Expected across all cells', isCorrect: true, explanation: 'Chi-sq = sum[(O_i - E_i)^2 / E_i]. This measures total squared standardized deviation from expected. Large values indicate observed data significantly departs from the independence assumption.' }, { label: 'B', text: 'The sum of Observed minus Expected', isCorrect: false, explanation: 'Simple differences always sum to zero. Squaring and dividing by expected standardizes and accumulates departures.' }, { label: 'C', text: 'The maximum observed frequency', isCorrect: false, explanation: 'A single cell frequency cannot measure overall departure from independence. The test uses information from all cells.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Parametric and Non-Parametric Tests of Independence', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m9-q5', questionText: 'Spearman rank correlation is a non-parametric measure of:', answerChoices: [{ label: 'A', text: 'The monotonic relationship between two variables based on their ranks', isCorrect: true, explanation: 'Spearman correlation applies Pearson formula to the ranks of data rather than raw values. It detects any monotonic (consistently increasing or decreasing) relationship, not just linear ones.' }, { label: 'B', text: 'The linear relationship between two normally distributed variables', isCorrect: false, explanation: 'Linear relationship between normal variables is measured by Pearson correlation. Spearman uses ranks and detects monotonic (not just linear) associations.' }, { label: 'C', text: 'The causal relationship between two variables', isCorrect: false, explanation: 'No correlation measure (parametric or non-parametric) establishes causation. Spearman measures association strength and direction.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Parametric and Non-Parametric Tests of Independence', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m9-q6', questionText: 'A requirement for valid use of the chi-squared test is that:', answerChoices: [{ label: 'A', text: 'Expected frequencies in each cell should be at least 5', isCorrect: true, explanation: 'The chi-squared approximation works when expected counts are sufficiently large (rule of thumb: all cells >= 5). With small expected frequencies, the approximation is poor and Fishers exact test should be used.' }, { label: 'B', text: 'All observed frequencies must be equal', isCorrect: false, explanation: 'Equal observed frequencies would suggest independence (null is true). The test does not require equal observations; it compares observed to expected.' }, { label: 'C', text: 'The data must be continuous', isCorrect: false, explanation: 'Chi-squared tests work with categorical (count) data. Continuous data must first be categorized before using chi-squared tests.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Parametric and Non-Parametric Tests of Independence', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m9-q7', questionText: 'The parametric test of independence between two continuous variables typically uses:', answerChoices: [{ label: 'A', text: 'A t-test on the Pearson correlation coefficient to determine if rho equals zero', isCorrect: true, explanation: 'The t-statistic = r*sqrt(n-2)/sqrt(1-r^2) tests H0: rho = 0. This parametric test assumes bivariate normality and linear relationship between the variables.' }, { label: 'B', text: 'Only the chi-squared test on raw data', isCorrect: false, explanation: 'Chi-squared is for categorical data. Testing independence of continuous variables uses correlation-based t-tests or F-tests.' }, { label: 'C', text: 'A comparison of means', isCorrect: false, explanation: 'Comparing means tests whether groups differ on average, not whether two continuous variables are related (independent).' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Parametric and Non-Parametric Tests of Independence', provider: 'cfa-portal', questionSourceFile: null },
];

// Module 10: Simple Linear Regression (49 questions)
const module10Questions: Question[] = [
  { id: 'qm-m10-q1', questionText: 'In simple linear regression, the dependent variable is modeled as:', answerChoices: [{ label: 'A', text: 'A linear function of one independent variable plus an error term', isCorrect: true, explanation: 'Y = b0 + b1*X + epsilon. The model assumes a linear relationship between Y and X, with random error capturing everything not explained by the linear relationship.' }, { label: 'B', text: 'An exponential function of multiple variables', isCorrect: false, explanation: 'Exponential functions are non-linear models. Simple linear regression uses exactly one independent variable in a linear equation.' }, { label: 'C', text: 'The average of all independent variables', isCorrect: false, explanation: 'Simple regression has only one independent variable and models a directional relationship, not an average.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q2', questionText: 'The ordinary least squares (OLS) method minimizes:', answerChoices: [{ label: 'A', text: 'The sum of squared residuals (differences between observed and predicted Y values)', isCorrect: true, explanation: 'OLS minimizes sum(Y_i - Y_hat_i)^2. This criterion produces the best linear unbiased estimator (BLUE) under Gauss-Markov assumptions. Squaring ensures positive and negative residuals do not cancel.' }, { label: 'B', text: 'The sum of absolute residuals', isCorrect: false, explanation: 'Minimizing absolute residuals gives the least absolute deviations (LAD) estimator, not OLS. LAD is more robust to outliers but less efficient.' }, { label: 'C', text: 'The maximum residual', isCorrect: false, explanation: 'Minimizing the maximum residual is minimax regression, not OLS. OLS minimizes the sum of all squared residuals.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q3', questionText: 'The coefficient of determination (R-squared) measures:', answerChoices: [{ label: 'A', text: 'The proportion of variance in the dependent variable explained by the independent variable', isCorrect: true, explanation: 'R^2 = 1 - RSS/TSS = explained variance / total variance. R^2 of 0.75 means 75% of the variation in Y is accounted for by the linear relationship with X.' }, { label: 'B', text: 'The slope of the regression line', isCorrect: false, explanation: 'The slope (b1) measures the change in Y per unit change in X. R-squared measures explanatory power, not slope magnitude.' }, { label: 'C', text: 'The probability that the model is correct', isCorrect: false, explanation: 'R-squared does not measure model correctness probability. It measures fit quality as the proportion of explained variance.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q4', questionText: 'The slope coefficient (b1) in a simple linear regression represents:', answerChoices: [{ label: 'A', text: 'The expected change in Y for a one-unit change in X, holding all else constant', isCorrect: true, explanation: 'b1 = delta_Y / delta_X. It quantifies the marginal effect of X on Y. In simple regression, there are no other variables to hold constant, but the interpretation extends to multiple regression.' }, { label: 'B', text: 'The value of Y when X equals zero', isCorrect: false, explanation: 'The value of Y when X = 0 is the intercept (b0), not the slope.' }, { label: 'C', text: 'The correlation between X and Y', isCorrect: false, explanation: 'Correlation is unitless and bounded [-1,1]. The slope has units of Y per X and is unbounded. They are related: b1 = r * (Sy/Sx).' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q5', questionText: 'The standard error of the estimate (SEE) in regression measures:', answerChoices: [{ label: 'A', text: 'The typical size of the prediction error (residual) in the units of the dependent variable', isCorrect: true, explanation: 'SEE = sqrt(RSS/(n-2)). It estimates the standard deviation of the error term. Smaller SEE means the regression predictions are more precise. It is in the same units as Y.' }, { label: 'B', text: 'The precision of the slope estimate', isCorrect: false, explanation: 'Precision of the slope is measured by the standard error of b1, not by SEE (though they are related).' }, { label: 'C', text: 'The correlation coefficient squared', isCorrect: false, explanation: 'R-squared and SEE are related (both measure fit) but SEE is a dispersion measure in Y-units, while R-squared is a proportion.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q6', questionText: 'The t-test for the slope coefficient tests:', answerChoices: [{ label: 'A', text: 'H0: b1 = 0 (no linear relationship between X and Y)', isCorrect: true, explanation: 't = b1 / SE(b1). If we cannot reject H0: b1 = 0, there is no statistically significant linear relationship. The test uses n-2 degrees of freedom for simple regression.' }, { label: 'B', text: 'Whether R-squared equals 1', isCorrect: false, explanation: 'R-squared = 1 means perfect fit. The t-test checks if the slope is significantly different from zero, not if fit is perfect.' }, { label: 'C', text: 'Whether the intercept is positive', isCorrect: false, explanation: 'A separate t-test can test the intercept, but the primary regression significance test focuses on the slope.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q7', questionText: 'The residual in a regression is:', answerChoices: [{ label: 'A', text: 'The difference between the actual observed Y value and the predicted Y value from the regression', isCorrect: true, explanation: 'Residual = Y_i - Y_hat_i = observed - predicted. Residuals estimate the true errors. They should be random, normally distributed, and have no pattern if model assumptions hold.' }, { label: 'B', text: 'The slope of the regression line', isCorrect: false, explanation: 'The slope is a coefficient estimate, not a residual. Residuals are the unexplained portions of individual observations.' }, { label: 'C', text: 'Always positive', isCorrect: false, explanation: 'Residuals can be positive (under-prediction) or negative (over-prediction). Their sum equals zero in OLS.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q8', questionText: 'The assumption of homoscedasticity in regression means:', answerChoices: [{ label: 'A', text: 'The variance of the error term is constant across all values of the independent variable', isCorrect: true, explanation: 'Homoscedasticity (constant variance) means Var(epsilon|X) = sigma^2 for all X. Violation (heteroscedasticity) does not bias estimates but invalidates standard error calculations and confidence intervals.' }, { label: 'B', text: 'The errors are normally distributed', isCorrect: false, explanation: 'Normal errors is a separate assumption. Homoscedasticity specifically requires constant error variance, not a particular distributional shape.' }, { label: 'C', text: 'The independent variable is measured without error', isCorrect: false, explanation: 'Measurement in X without error is a separate assumption. Homoscedasticity concerns the variance of Y around the regression line.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q9', questionText: 'Heteroscedasticity in a regression model causes:', answerChoices: [{ label: 'A', text: 'Standard errors of coefficients to be unreliable, leading to incorrect hypothesis tests', isCorrect: true, explanation: 'With non-constant variance, OLS estimates remain unbiased but standard errors are wrong. t-statistics and confidence intervals become unreliable. Use robust (White) standard errors or GLS to correct.' }, { label: 'B', text: 'The slope estimate to be biased', isCorrect: false, explanation: 'OLS slope remains unbiased under heteroscedasticity. Only standard errors and efficiency are affected.' }, { label: 'C', text: 'R-squared to always equal zero', isCorrect: false, explanation: 'Heteroscedasticity does not affect R-squared directly. The model can still explain substantial variance even with non-constant error variance.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q10', questionText: 'The ANOVA table in regression decomposes total variation into:', answerChoices: [{ label: 'A', text: 'Explained variation (regression sum of squares) and unexplained variation (residual sum of squares)', isCorrect: true, explanation: 'TSS = RSS(regression) + RSS(residual). ANOVA partitions total variance in Y into the portion explained by X and the unexplained remainder. F-test evaluates if explained portion is significant.' }, { label: 'B', text: 'Between-group and within-group variation', isCorrect: false, explanation: 'This terminology applies to one-way ANOVA for group comparisons. Regression ANOVA uses explained (regression) and unexplained (residual) variation.' }, { label: 'C', text: 'Systematic and random error only', isCorrect: false, explanation: 'While conceptually related, the specific ANOVA decomposition in regression separates model-explained variation from residual variation.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q11', questionText: 'The F-statistic in simple regression ANOVA tests:', answerChoices: [{ label: 'A', text: 'Whether the overall regression model is statistically significant (equivalent to t-test for slope in simple regression)', isCorrect: true, explanation: 'F = MSR/MSE. In simple regression, F = t^2 for the slope test, so they are equivalent. A significant F means at least one independent variable (the only one) explains significant variation in Y.' }, { label: 'B', text: 'Whether each individual coefficient is zero', isCorrect: false, explanation: 'Individual coefficient tests use t-statistics. In multiple regression, F tests joint significance while t-tests test individual coefficients.' }, { label: 'C', text: 'Whether the residuals are normally distributed', isCorrect: false, explanation: 'Normality of residuals is tested by Jarque-Bera or Shapiro-Wilk tests, not by the regression F-statistic.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q12', questionText: 'The confidence interval for a predicted Y value is widest when:', answerChoices: [{ label: 'A', text: 'X is far from the mean of X (extrapolation beyond the data range)', isCorrect: true, explanation: 'Prediction uncertainty increases with distance from X-bar because the regression line pivots around the mean point. Predictions at extreme X values have larger standard errors and wider confidence intervals.' }, { label: 'B', text: 'X equals the mean of X', isCorrect: false, explanation: 'At X-bar, the prediction interval is narrowest because there is no additional uncertainty from estimating the slope at that point.' }, { label: 'C', text: 'The sample size is very large', isCorrect: false, explanation: 'Larger samples narrow all confidence intervals. Width increases with distance from the mean and decreases with sample size.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q13', questionText: 'Serial correlation (autocorrelation) in regression residuals means:', answerChoices: [{ label: 'A', text: 'Residuals at one time period are correlated with residuals at adjacent time periods', isCorrect: true, explanation: 'Autocorrelation violates the assumption of independent errors. Positive autocorrelation means a positive residual is likely followed by another positive residual. Common in time series data.' }, { label: 'B', text: 'The independent variable is correlated with itself', isCorrect: false, explanation: 'Autocorrelation in residuals is about error terms being related across time, not about X being correlated with itself.' }, { label: 'C', text: 'The R-squared is exactly 1', isCorrect: false, explanation: 'Perfect R-squared means zero residuals, making autocorrelation undefined. Autocorrelation occurs when residuals exist but are not independent.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q14', questionText: 'The Durbin-Watson statistic is used to detect:', answerChoices: [{ label: 'A', text: 'First-order autocorrelation in regression residuals', isCorrect: true, explanation: 'DW ranges from 0 to 4. DW near 2 suggests no autocorrelation. DW near 0 indicates positive autocorrelation; DW near 4 indicates negative autocorrelation. It tests for AR(1) pattern in residuals.' }, { label: 'B', text: 'Heteroscedasticity', isCorrect: false, explanation: 'Heteroscedasticity is detected by Breusch-Pagan or White tests. Durbin-Watson specifically tests for serial correlation.' }, { label: 'C', text: 'Multicollinearity', isCorrect: false, explanation: 'Multicollinearity is detected by VIF (Variance Inflation Factor) or correlation matrices. DW addresses autocorrelation only.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q15', questionText: 'If the Durbin-Watson statistic equals approximately 2, this suggests:', answerChoices: [{ label: 'A', text: 'No significant first-order autocorrelation in the residuals', isCorrect: true, explanation: 'DW = 2(1 - r), where r is the first-order autocorrelation of residuals. When r = 0 (no autocorrelation), DW = 2. Values significantly above or below 2 indicate autocorrelation.' }, { label: 'B', text: 'Perfect positive autocorrelation', isCorrect: false, explanation: 'Perfect positive autocorrelation gives DW near 0. DW = 2 indicates no autocorrelation.' }, { label: 'C', text: 'The model has no explanatory power', isCorrect: false, explanation: 'DW measures residual patterns, not explanatory power. R-squared measures explanatory power.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q16', questionText: 'The Gauss-Markov theorem states that OLS estimators are BLUE when:', answerChoices: [{ label: 'A', text: 'The classical assumptions hold: linearity, random sampling, no perfect collinearity, zero conditional mean of errors, and homoscedasticity', isCorrect: true, explanation: 'Under these assumptions, OLS produces the Best (minimum variance) Linear Unbiased Estimators. No other linear unbiased estimator has smaller sampling variance.' }, { label: 'B', text: 'The errors are normally distributed', isCorrect: false, explanation: 'Normality is not required for BLUE. It is needed for exact distribution of test statistics in small samples, but BLUE holds without normality.' }, { label: 'C', text: 'The sample size exceeds 100', isCorrect: false, explanation: 'BLUE holds for any sample size given the assumptions. Large samples provide asymptotic properties but BLUE is a finite-sample result.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q17', questionText: 'A high R-squared value in a regression does NOT necessarily mean:', answerChoices: [{ label: 'A', text: 'That the independent variable causes changes in the dependent variable', isCorrect: true, explanation: 'Correlation/regression measures association, not causation. High R-squared can result from spurious correlation, omitted variables, or reverse causality. Causation requires controlled experiments or causal inference methods.' }, { label: 'B', text: 'That the model explains much of the variation in Y', isCorrect: false, explanation: 'High R-squared does mean high explanatory power. R-squared directly measures the proportion of Y variance explained.' }, { label: 'C', text: 'That the slope is statistically significant', isCorrect: false, explanation: 'High R-squared in simple regression implies a significant slope (they are mathematically linked: R^2 = r^2, and significant r implies significant slope).' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q18', questionText: 'The regression line always passes through:', answerChoices: [{ label: 'A', text: 'The point (X-bar, Y-bar), the means of X and Y', isCorrect: true, explanation: 'By construction of OLS, the regression line passes through the centroid of the data. This is because the sum of residuals equals zero, which forces the line through the mean point.' }, { label: 'B', text: 'The origin (0, 0)', isCorrect: false, explanation: 'The line passes through the origin only if the intercept is zero. Generally, b0 is non-zero and the line does not pass through the origin.' }, { label: 'C', text: 'All observed data points', isCorrect: false, explanation: 'The line passes through all points only if R-squared = 1 (perfect fit). Generally, residuals are non-zero.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q19', questionText: 'The prediction interval for an individual Y value is wider than the confidence interval for the mean Y at the same X because:', answerChoices: [{ label: 'A', text: 'It includes both the uncertainty in estimating the regression line and the individual error term variability', isCorrect: true, explanation: 'Prediction interval accounts for: (1) estimation error in the line (same as CI for mean), PLUS (2) the inherent scatter of individual observations around the line. The extra sigma^2 term makes it wider.' }, { label: 'B', text: 'Prediction intervals use a larger critical value', isCorrect: false, explanation: 'Both use the same t critical value. The difference is in the standard error formula, which adds the error term variance for prediction intervals.' }, { label: 'C', text: 'Individual values are always more variable than means', isCorrect: false, explanation: 'While this intuition is correct, the specific reason for wider prediction intervals is the additional error variance component in the formula.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q20', questionText: 'In simple regression, the relationship between correlation (r) and R-squared is:', answerChoices: [{ label: 'A', text: 'R-squared equals the square of the correlation coefficient', isCorrect: true, explanation: 'R^2 = r^2 in simple regression. If r = 0.8, R-squared = 0.64 (64% of variance explained). The sign of r gives the direction; R-squared gives explanatory power.' }, { label: 'B', text: 'R-squared equals the square root of correlation', isCorrect: false, explanation: 'This reverses the relationship. Correlation is the square root of R-squared (with appropriate sign), not the other way.' }, { label: 'C', text: 'They are unrelated', isCorrect: false, explanation: 'In simple regression, they are directly linked: R^2 = r^2. This relationship is specific to one independent variable.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q21', questionText: 'The intercept (b0) in a regression equation represents:', answerChoices: [{ label: 'A', text: 'The predicted value of Y when X equals zero', isCorrect: true, explanation: 'b0 = Y_hat when X = 0. In many contexts this has no practical meaning (e.g., predicting returns when market return is zero may be outside the data range), but mathematically it anchors the line.' }, { label: 'B', text: 'The rate of change in Y per unit change in X', isCorrect: false, explanation: 'The rate of change is the slope (b1), not the intercept. The intercept is the Y-axis crossing point.' }, { label: 'C', text: 'The average of all residuals', isCorrect: false, explanation: 'The average of residuals is always zero in OLS. The intercept ensures this property by positioning the line through the mean.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q22', questionText: 'Assumptions of the classical linear regression model include all of the following EXCEPT:', answerChoices: [{ label: 'A', text: 'The independent variable must be normally distributed', isCorrect: true, explanation: 'Classical assumptions require linearity, independent errors, homoscedasticity, no autocorrelation, and normal errors. X can have any distribution; it is treated as fixed or exogenous. Normality applies to errors, not X.' }, { label: 'B', text: 'Homoscedasticity (constant error variance)', isCorrect: false, explanation: 'Constant error variance is indeed a classical assumption, required for valid standard errors and BLUE property.' }, { label: 'C', text: 'No autocorrelation in the error terms', isCorrect: false, explanation: 'Independent errors (no serial correlation) is a key classical assumption, especially important for time series data.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q23', questionText: 'A regression with all insignificant individual coefficients but a significant overall F-test most likely indicates:', answerChoices: [{ label: 'A', text: 'Multicollinearity among the independent variables (in multiple regression)', isCorrect: true, explanation: 'Multicollinearity inflates individual standard errors (making t-tests insignificant) while the variables jointly still explain significant variation (F-test significant). Correlated predictors share explanatory power.' }, { label: 'B', text: 'A perfectly specified model', isCorrect: false, explanation: 'Conflicting F and t results suggest model problems (multicollinearity), not a well-specified model.' }, { label: 'C', text: 'Too few observations', isCorrect: false, explanation: 'Small samples reduce power for all tests equally. The specific pattern of significant F with insignificant t-tests points to multicollinearity.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q24', questionText: 'The slope coefficient b1 in simple regression can be calculated as:', answerChoices: [{ label: 'A', text: 'Cov(X,Y) / Var(X)', isCorrect: true, explanation: 'b1 = sum[(X_i - X_bar)(Y_i - Y_bar)] / sum[(X_i - X_bar)^2] = Cov(X,Y)/Var(X). This shows the slope is determined by how X and Y co-vary relative to X variation alone.' }, { label: 'B', text: 'Var(Y) / Cov(X,Y)', isCorrect: false, explanation: 'This inverts part of the formula. The slope divides covariance by the variance of X (not Y).' }, { label: 'C', text: 'The sum of X times Y', isCorrect: false, explanation: 'Simple products do not account for means or standardization. The correct formula uses deviations from means.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q25', questionText: 'Influential observations in regression are identified by:', answerChoices: [{ label: 'A', text: 'High leverage (extreme X values) combined with large residuals', isCorrect: true, explanation: 'Influential points substantially change the regression results when removed. They have high leverage (far from X-bar) AND poorly fit the existing pattern (large residuals). Cooks distance quantifies combined influence.' }, { label: 'B', text: 'Being close to the regression line', isCorrect: false, explanation: 'Points close to the line have small residuals and minimal influence. Influential points are far from where the line would be without them.' }, { label: 'C', text: 'Having Y values close to the mean', isCorrect: false, explanation: 'Y near Y-bar means the point is not unusual in the Y dimension. Influence depends on both X leverage and residual size.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q26', questionText: 'The total sum of squares (TSS) in regression equals:', answerChoices: [{ label: 'A', text: 'The sum of squared deviations of Y from its mean: sum(Y_i - Y_bar)^2', isCorrect: true, explanation: 'TSS measures total variability in Y before any explanation by X. It decomposes into ESS (explained by regression) + RSS (unexplained residuals). R^2 = ESS/TSS.' }, { label: 'B', text: 'The sum of squared predicted values', isCorrect: false, explanation: 'Squared predicted values measure the level of predictions, not the variability that TSS captures.' }, { label: 'C', text: 'The number of observations times the variance', isCorrect: false, explanation: 'TSS = (n-1) x variance (sample variance uses n-1 denominator), not n x variance.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q27', questionText: 'When the Durbin-Watson statistic is close to 0, it indicates:', answerChoices: [{ label: 'A', text: 'Strong positive autocorrelation in the residuals', isCorrect: true, explanation: 'DW near 0 means consecutive residuals are highly positively correlated (a positive residual tends to follow a positive residual). This is common in trending time series where the model misses a systematic pattern.' }, { label: 'B', text: 'No autocorrelation', isCorrect: false, explanation: 'No autocorrelation corresponds to DW near 2. DW near 0 is the extreme positive autocorrelation case.' }, { label: 'C', text: 'Strong negative autocorrelation', isCorrect: false, explanation: 'Negative autocorrelation gives DW near 4 (residuals alternate in sign). DW near 0 indicates positive autocorrelation.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q28', questionText: 'The standard error of the slope coefficient depends on:', answerChoices: [{ label: 'A', text: 'The standard error of the estimate, sample size, and variability of X', isCorrect: true, explanation: 'SE(b1) = SEE / sqrt(sum(X_i - X_bar)^2). Slope precision improves with: lower SEE (tighter fit), more observations, and greater spread in X (more information about the X-Y relationship).' }, { label: 'B', text: 'Only the sample size', isCorrect: false, explanation: 'While larger n reduces SE(b1), it also depends on the regression fit quality (SEE) and the variability in X values.' }, { label: 'C', text: 'The intercept value', isCorrect: false, explanation: 'The intercept value does not directly determine the precision of the slope estimate.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q29', questionText: 'A residual plot that shows a funnel shape (increasing spread) indicates:', answerChoices: [{ label: 'A', text: 'Heteroscedasticity - the error variance increases with X (or fitted values)', isCorrect: true, explanation: 'Funnel/cone-shaped residuals mean variance is not constant. As X increases, residuals become more dispersed. This violates the homoscedasticity assumption and requires correction (robust SEs or transformation).' }, { label: 'B', text: 'Perfect model specification', isCorrect: false, explanation: 'Perfect specification would show random scatter with no pattern. A funnel shape is a clear pattern indicating assumption violation.' }, { label: 'C', text: 'Normally distributed errors', isCorrect: false, explanation: 'Normal errors with constant variance would produce a uniform band. A funnel contradicts constant variance.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q30', questionText: 'The correlation coefficient in simple regression is related to the slope by:', answerChoices: [{ label: 'A', text: 'b1 = r x (standard deviation of Y / standard deviation of X)', isCorrect: true, explanation: 'The slope equals correlation times the ratio of standard deviations: b1 = r x (Sy/Sx). This shows the slope is the correlation scaled by relative variability. If X and Y have equal variance, b1 = r.' }, { label: 'B', text: 'b1 = r / n', isCorrect: false, explanation: 'Dividing correlation by sample size has no statistical basis. The correct scaling involves the ratio of standard deviations.' }, { label: 'C', text: 'b1 = r^2', isCorrect: false, explanation: 'r^2 is R-squared (proportion of explained variance), not the slope coefficient.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q31', questionText: 'Transforming the dependent variable using natural log (log-linear model) changes the interpretation of b1 to:', answerChoices: [{ label: 'A', text: 'A one-unit increase in X leads to approximately a b1 x 100 percent change in Y', isCorrect: true, explanation: 'In ln(Y) = b0 + b1*X, b1 represents the proportional (percentage) change in Y per unit change in X. If b1 = 0.05, a one-unit increase in X increases Y by approximately 5%.' }, { label: 'B', text: 'The same unit-change interpretation as a linear model', isCorrect: false, explanation: 'Log transformation changes the interpretation from absolute change to proportional change. The units of measurement for the slope are different.' }, { label: 'C', text: 'An elasticity', isCorrect: false, explanation: 'Elasticity (percent change in Y per percent change in X) requires log-log model (ln(Y) = b0 + b1*ln(X)). Log-linear gives semi-elasticity.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q32', questionText: 'In the Capital Asset Pricing Model (CAPM) regression Ri - Rf = alpha + beta(Rm - Rf) + epsilon, the slope represents:', answerChoices: [{ label: 'A', text: 'The systematic risk (beta) of the asset relative to the market', isCorrect: true, explanation: 'Beta measures the sensitivity of asset excess returns to market excess returns. Beta = 1.5 means the asset moves 1.5% for every 1% market move. It quantifies systematic risk.' }, { label: 'B', text: 'The risk-free rate', isCorrect: false, explanation: 'The risk-free rate is subtracted from returns. The slope captures the assets sensitivity to market movements.' }, { label: 'C', text: 'The total return on the asset', isCorrect: false, explanation: 'Total return is the dependent variable (left side). The slope measures the relationship between asset and market excess returns.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q33', questionText: 'A log-log regression model (ln Y = b0 + b1 ln X) gives slope b1 the interpretation of:', answerChoices: [{ label: 'A', text: 'The elasticity: a 1% change in X is associated with a b1% change in Y', isCorrect: true, explanation: 'In log-log models, b1 is the elasticity of Y with respect to X. If b1 = 0.8, a 1% increase in X leads to a 0.8% increase in Y. Elasticity is constant across all values of X.' }, { label: 'B', text: 'The absolute change in Y per unit change in X', isCorrect: false, explanation: 'Absolute change interpretation applies to linear (level-level) models. Log-log provides percentage-to-percentage interpretation.' }, { label: 'C', text: 'The probability that Y increases when X increases', isCorrect: false, explanation: 'Probability interpretation applies to logistic regression, not log-log linear regression.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q34', questionText: 'Omitted variable bias occurs when:', answerChoices: [{ label: 'A', text: 'A relevant variable is excluded from the model and is correlated with an included variable', isCorrect: true, explanation: 'If the omitted variable affects Y AND correlates with X, then X captures the effect of the omitted variable, biasing b1. The bias direction depends on the correlations between the omitted, included, and dependent variables.' }, { label: 'B', text: 'Too many variables are included in the model', isCorrect: false, explanation: 'Including irrelevant variables reduces efficiency but does not cause bias (coefficients remain unbiased but have larger standard errors).' }, { label: 'C', text: 'The sample size is too large', isCorrect: false, explanation: 'Large samples reduce estimation error but cannot fix the fundamental bias from model misspecification (omitted variables).' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q35', questionText: 'The coefficient of determination (R-squared) can only be between:', answerChoices: [{ label: 'A', text: '0 and 1 (inclusive) in standard OLS with an intercept', isCorrect: true, explanation: 'R^2 = 1 - RSS/TSS. Since RSS <= TSS (regression cannot explain negative variance), R^2 is bounded by [0,1]. Zero means X explains nothing; 1 means perfect fit.' }, { label: 'B', text: '-1 and +1', isCorrect: false, explanation: 'Correlation ranges from -1 to +1, but R-squared (correlation squared) is always non-negative, ranging 0 to 1.' }, { label: 'C', text: '0 and infinity', isCorrect: false, explanation: 'R-squared is a proportion and cannot exceed 1 (100% of variance explained is the maximum).' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q36', questionText: 'The Breusch-Pagan test is used to detect:', answerChoices: [{ label: 'A', text: 'Heteroscedasticity in regression residuals', isCorrect: true, explanation: 'Breusch-Pagan regresses squared residuals on the independent variables. Significant results indicate that error variance depends on X (heteroscedasticity), violating the constant variance assumption.' }, { label: 'B', text: 'Autocorrelation in residuals', isCorrect: false, explanation: 'Autocorrelation is detected by Durbin-Watson or Breusch-Godfrey tests, not Breusch-Pagan.' }, { label: 'C', text: 'Non-normality of residuals', isCorrect: false, explanation: 'Non-normality is detected by Jarque-Bera, Shapiro-Wilk, or Q-Q plots. Breusch-Pagan specifically tests variance constancy.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q37', questionText: 'White-corrected (heteroscedasticity-consistent) standard errors:', answerChoices: [{ label: 'A', text: 'Provide valid hypothesis tests and confidence intervals even when heteroscedasticity is present', isCorrect: true, explanation: 'White robust standard errors adjust for non-constant error variance without assuming a specific form of heteroscedasticity. OLS coefficients remain unchanged; only the standard errors are corrected.' }, { label: 'B', text: 'Change the coefficient estimates', isCorrect: false, explanation: 'White correction only adjusts standard errors, not the coefficient estimates. The OLS estimates remain the same.' }, { label: 'C', text: 'Eliminate heteroscedasticity from the data', isCorrect: false, explanation: 'Heteroscedasticity still exists in the data. White SEs simply account for it in inference, providing valid tests despite its presence.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q38', questionText: 'A regression model used for forecasting is most reliable when:', answerChoices: [{ label: 'A', text: 'The forecast is within the range of X values used to estimate the model (interpolation)', isCorrect: true, explanation: 'Extrapolation beyond the observed X range is risky because the linear relationship may not hold outside the data. Interpolation stays within validated territory where the model has proven fit.' }, { label: 'B', text: 'The forecast X value is far from any observed value', isCorrect: false, explanation: 'Far from observed values is extrapolation, which increases prediction uncertainty and risk of model breakdown.' }, { label: 'C', text: 'R-squared is exactly 1.0', isCorrect: false, explanation: 'Perfect R-squared often indicates overfitting or a tautological relationship, not necessarily better forecasting ability.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q39', questionText: 'In the context of regression, a lurking variable is:', answerChoices: [{ label: 'A', text: 'An unobserved variable that drives both X and Y, creating a spurious correlation between them', isCorrect: true, explanation: 'A lurking (confounding) variable causes both X and Y to move together without X actually causing Y. For example, economic growth may drive both ice cream sales and drowning deaths.' }, { label: 'B', text: 'An observation with a large residual', isCorrect: false, explanation: 'Large residuals identify outliers or poorly fit points, not lurking variables which are unmeasured confounders.' }, { label: 'C', text: 'The intercept term in the equation', isCorrect: false, explanation: 'The intercept is a model parameter, not a lurking variable. Lurking variables are unobserved influences outside the model.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q40', questionText: 'The assumptions required for valid inference (t-tests, F-tests) in regression include error terms that are:', answerChoices: [{ label: 'A', text: 'Independent, identically distributed (iid) normal with mean zero and constant variance', isCorrect: true, explanation: 'For valid small-sample inference, errors must be: (1) independent (no autocorrelation), (2) normally distributed, (3) mean zero (unbiased), (4) constant variance (homoscedastic). Large samples relax normality via CLT.' }, { label: 'B', text: 'Always positive', isCorrect: false, explanation: 'Errors must have mean zero, meaning they can be positive or negative with roughly equal frequency.' }, { label: 'C', text: 'Perfectly correlated with X', isCorrect: false, explanation: 'Errors must be uncorrelated with X (exogeneity assumption). Correlation between errors and X causes endogeneity bias.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q41', questionText: 'Remedies for positive serial correlation in regression include:', answerChoices: [{ label: 'A', text: 'Adding lagged variables, using first differences, or applying generalized least squares', isCorrect: true, explanation: 'Serial correlation often indicates missing dynamics. Remedies include: adding lagged Y or X, differencing the data, using Newey-West standard errors, or GLS (Cochrane-Orcutt procedure).' }, { label: 'B', text: 'Increasing the significance level', isCorrect: false, explanation: 'Changing alpha does not fix the underlying violation. It only changes the decision threshold without addressing the autocorrelation problem.' }, { label: 'C', text: 'Removing the intercept from the model', isCorrect: false, explanation: 'Removing the intercept does not address serial correlation and can create other problems (residuals no longer sum to zero).' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q42', questionText: 'The adjusted R-squared differs from R-squared in that it:', answerChoices: [{ label: 'A', text: 'Penalizes for adding variables that do not improve the model, and can decrease when irrelevant variables are added', isCorrect: true, explanation: 'Adj R^2 = 1 - [(1-R^2)(n-1)/(n-k-1)]. It adjusts for degrees of freedom. Adding a useless variable increases R^2 slightly but decreases adjusted R^2, making it better for model comparison.' }, { label: 'B', text: 'Is always larger than R-squared', isCorrect: false, explanation: 'Adjusted R-squared is always less than or equal to R-squared because it penalizes for model complexity.' }, { label: 'C', text: 'Only applies to simple regression', isCorrect: false, explanation: 'Adjusted R-squared is most useful in multiple regression for comparing models with different numbers of variables.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q43', questionText: 'The Jarque-Bera test checks whether regression residuals are:', answerChoices: [{ label: 'A', text: 'Normally distributed by testing if skewness and excess kurtosis are both zero', isCorrect: true, explanation: 'JB = (n/6)[S^2 + (K-3)^2/4] follows chi-sq(2) under normality. It tests whether the residuals third and fourth moments match the normal distribution (skew=0, kurtosis=3).' }, { label: 'B', text: 'Heteroscedastic', isCorrect: false, explanation: 'Heteroscedasticity is tested by Breusch-Pagan or White tests. Jarque-Bera specifically tests the normality assumption.' }, { label: 'C', text: 'Serially correlated', isCorrect: false, explanation: 'Serial correlation is tested by Durbin-Watson or Breusch-Godfrey. Jarque-Bera focuses on distributional shape (normality).' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q44', questionText: 'Spurious regression is most likely to occur when:', answerChoices: [{ label: 'A', text: 'Both the dependent and independent variables contain unit roots (non-stationary time series)', isCorrect: true, explanation: 'Non-stationary variables that trend over time often show high R-squared and significant t-statistics even without genuine economic relationship. This spurious regression trap is a major issue in time series analysis.' }, { label: 'B', text: 'The sample size is too small', isCorrect: false, explanation: 'Small samples cause imprecision, not spurious regression. Spurious regression is specifically a non-stationarity problem in time series.' }, { label: 'C', text: 'The variables are measured in the same units', isCorrect: false, explanation: 'Same units of measurement do not cause spurious regression. The problem is stochastic trends creating false apparent relationships.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q45', questionText: 'In regression diagnostics, a Q-Q plot is used to assess:', answerChoices: [{ label: 'A', text: 'Whether the residuals follow a normal distribution by comparing quantiles to theoretical normal quantiles', isCorrect: true, explanation: 'Q-Q (quantile-quantile) plots show observed quantiles vs. expected normal quantiles. If residuals are normal, points fall approximately on a straight line. Deviations indicate non-normality (heavy tails, skewness).' }, { label: 'B', text: 'Whether heteroscedasticity is present', isCorrect: false, explanation: 'Heteroscedasticity is assessed with residual vs. fitted value plots or formal tests (Breusch-Pagan), not Q-Q plots.' }, { label: 'C', text: 'The correlation between X and Y', isCorrect: false, explanation: 'Scatterplots of X vs Y assess correlation. Q-Q plots assess distributional shape of residuals.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q46', questionText: 'The consequences of using OLS when errors are autocorrelated include:', answerChoices: [{ label: 'A', text: 'Coefficients are still unbiased but standard errors are understated, leading to inflated t-statistics', isCorrect: true, explanation: 'Positive autocorrelation makes OLS standard errors too small (understated), so t-statistics are too large and we over-reject H0. Coefficients remain unbiased but inference is unreliable.' }, { label: 'B', text: 'Coefficients become biased and inconsistent', isCorrect: false, explanation: 'OLS remains unbiased under autocorrelation (assuming no lagged dependent variable). Only standard errors and efficiency are affected.' }, { label: 'C', text: 'R-squared becomes negative', isCorrect: false, explanation: 'R-squared remains between 0 and 1 regardless of autocorrelation. It may be inflated but cannot become negative in standard OLS.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q47', questionText: 'Leverage in regression analysis measures:', answerChoices: [{ label: 'A', text: 'How far an observations X value is from the mean of X, indicating its potential influence', isCorrect: true, explanation: 'High-leverage points have X values far from X-bar. They have outsized potential to pull the regression line toward them. Leverage ranges from 1/n to 1; values above 2(k+1)/n are considered high.' }, { label: 'B', text: 'The size of the residual for that observation', isCorrect: false, explanation: 'Residual size measures poor fit. Leverage measures the X-space position regardless of the residual. An influential point needs both high leverage and large residual.' }, { label: 'C', text: 'The correlation between two independent variables', isCorrect: false, explanation: 'Correlation between independent variables relates to multicollinearity. Leverage is about individual observation position in X-space.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q48', questionText: 'The model specification error of using a linear model when the true relationship is quadratic leads to:', answerChoices: [{ label: 'A', text: 'Biased coefficient estimates and systematic patterns in the residual plot', isCorrect: true, explanation: 'Wrong functional form creates specification bias: the linear coefficient does not capture the true curvature, and residuals show a U-shape or inverted U-shape pattern revealing the missing non-linearity.' }, { label: 'B', text: 'Only wider confidence intervals with no bias', isCorrect: false, explanation: 'Misspecification causes bias, not just inefficiency. The linear approximation systematically over- or under-estimates at different X ranges.' }, { label: 'C', text: 'Perfect R-squared', isCorrect: false, explanation: 'Misspecification typically reduces R-squared because the wrong functional form cannot capture the true relationship fully.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m10-q49', questionText: 'The sample size required for reliable regression results depends on:', answerChoices: [{ label: 'A', text: 'The number of independent variables, desired power, effect size, and significance level', isCorrect: true, explanation: 'Rule of thumb: at least 30 observations per independent variable for adequate power. More precisely, sample size planning considers the minimum detectable effect, desired alpha and power, and expected R-squared.' }, { label: 'B', text: 'Only the significance level', isCorrect: false, explanation: 'Alpha alone cannot determine needed sample size. The effect magnitude, desired power, and number of parameters also matter.' }, { label: 'C', text: 'The computational capacity of the software', isCorrect: false, explanation: 'Modern software handles any sample size. The requirement is statistical (having enough information to reliably estimate parameters), not computational.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Simple Linear Regression', provider: 'cfa-portal', questionSourceFile: null },
];

// Module 11: Introduction to Big Data Techniques (14 questions)
const module11Questions: Question[] = [
  { id: 'qm-m11-q1', questionText: 'Big data is typically characterized by the "three Vs" which are:', answerChoices: [{ label: 'A', text: 'Volume, Velocity, and Variety', isCorrect: true, explanation: 'Volume (massive amounts), Velocity (rapid generation and processing), and Variety (structured, semi-structured, and unstructured formats). Some frameworks add Veracity (data quality) as a fourth V.' }, { label: 'B', text: 'Value, Verification, and Visualization', isCorrect: false, explanation: 'While these are relevant data concepts, the classic three Vs of big data are Volume, Velocity, and Variety.' }, { label: 'C', text: 'Variables, Vectors, and Validation', isCorrect: false, explanation: 'These are statistical and programming concepts, not the defining characteristics of big data.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q2', questionText: 'Structured data differs from unstructured data in that structured data:', answerChoices: [{ label: 'A', text: 'Is organized in a predefined format (rows and columns) that is easily searchable and analyzable', isCorrect: true, explanation: 'Structured data fits neatly into databases (stock prices, financial statements). Unstructured data (news articles, social media, images) lacks predefined format and requires special processing techniques.' }, { label: 'B', text: 'Is always larger in volume', isCorrect: false, explanation: 'Unstructured data actually accounts for roughly 80-90% of all data generated. Structured data is a smaller but more easily usable portion.' }, { label: 'C', text: 'Cannot be stored in databases', isCorrect: false, explanation: 'Structured data is specifically designed for traditional relational databases. It is the easiest type to store and query.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q3', questionText: 'Machine learning differs from traditional statistical methods primarily because machine learning:', answerChoices: [{ label: 'A', text: 'Focuses on prediction accuracy and pattern recognition rather than inference about population parameters', isCorrect: true, explanation: 'Traditional statistics emphasizes understanding relationships (coefficient interpretation, hypothesis testing). ML prioritizes predictive performance, often at the expense of interpretability, using flexible models that learn patterns from data.' }, { label: 'B', text: 'Never uses mathematical formulas', isCorrect: false, explanation: 'ML heavily uses mathematics (optimization, linear algebra, calculus). The difference is in goals (prediction vs. inference), not in mathematical sophistication.' }, { label: 'C', text: 'Only works with small data sets', isCorrect: false, explanation: 'ML typically excels with large data sets where complex patterns can be learned. Traditional methods often work better with small data.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q4', questionText: 'Overfitting in a machine learning model occurs when:', answerChoices: [{ label: 'A', text: 'The model learns noise in the training data and performs poorly on new unseen data', isCorrect: true, explanation: 'Overfitting means the model is too complex: it memorizes training data (including random noise) rather than learning generalizable patterns. High training accuracy but low test accuracy is the hallmark of overfitting.' }, { label: 'B', text: 'The model is too simple to capture any patterns', isCorrect: false, explanation: 'A model too simple to capture patterns is underfitting, not overfitting. Underfitting has poor performance on both training and test data.' }, { label: 'C', text: 'The training data set is very large', isCorrect: false, explanation: 'Large training sets actually reduce overfitting by providing more examples for the model to learn genuine patterns rather than noise.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q5', questionText: 'Supervised learning algorithms require:', answerChoices: [{ label: 'A', text: 'Labeled training data with known input-output pairs to learn the mapping', isCorrect: true, explanation: 'Supervised learning uses labeled examples (features + known correct answers) to learn predictions. Classification (discrete labels) and regression (continuous targets) are the two main types.' }, { label: 'B', text: 'No training data at all', isCorrect: false, explanation: 'All machine learning requires data. Supervised learning specifically needs labeled data where the correct answer is provided.' }, { label: 'C', text: 'Only time series data', isCorrect: false, explanation: 'Supervised learning works with any type of data (cross-sectional, time series, images, text) as long as labels are available.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q6', questionText: 'Unsupervised learning is used to:', answerChoices: [{ label: 'A', text: 'Discover hidden patterns, groupings, or structure in data without predefined labels', isCorrect: true, explanation: 'Unsupervised learning finds structure without labeled outcomes: clustering (grouping similar items), dimensionality reduction (PCA), and anomaly detection. Useful when labels are unavailable or expensive to obtain.' }, { label: 'B', text: 'Predict known categories with high accuracy', isCorrect: false, explanation: 'Predicting known categories is classification (supervised learning). Unsupervised learning discovers unknown structure.' }, { label: 'C', text: 'Always produce better results than supervised learning', isCorrect: false, explanation: 'When labels are available, supervised learning typically outperforms unsupervised for prediction tasks. Each has appropriate use cases.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q7', questionText: 'Cross-validation is used in machine learning to:', answerChoices: [{ label: 'A', text: 'Assess how well the model generalizes to independent data by repeatedly splitting data into training and validation sets', isCorrect: true, explanation: 'K-fold cross-validation splits data into k parts, trains on k-1, tests on the held-out fold, rotates, and averages performance. This provides a reliable estimate of out-of-sample performance without wasting data.' }, { label: 'B', text: 'Increase the training data size', isCorrect: false, explanation: 'Cross-validation does not add data. It uses existing data more efficiently by rotating training and validation roles.' }, { label: 'C', text: 'Eliminate all model errors', isCorrect: false, explanation: 'No technique eliminates all errors. Cross-validation helps estimate and reduce generalization error through proper model selection.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q8', questionText: 'Natural language processing (NLP) in finance is used to:', answerChoices: [{ label: 'A', text: 'Extract structured information and sentiment from text data like news, filings, and social media', isCorrect: true, explanation: 'NLP processes text data to quantify sentiment, extract events, classify documents, and summarize information. Applications include analyzing earnings calls, SEC filings, news sentiment, and analyst reports.' }, { label: 'B', text: 'Only translate between human languages', isCorrect: false, explanation: 'Translation is one NLP application, but financial NLP focuses on sentiment analysis, information extraction, and text classification for investment insights.' }, { label: 'C', text: 'Process only numerical data', isCorrect: false, explanation: 'NLP specifically handles text (natural language) data. Numerical data is processed by traditional statistical or ML methods.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q9', questionText: 'The bias-variance tradeoff in machine learning means:', answerChoices: [{ label: 'A', text: 'Reducing model bias (underfitting) typically increases variance (overfitting) and vice versa', isCorrect: true, explanation: 'Simple models have high bias (miss patterns) but low variance (stable predictions). Complex models have low bias (capture patterns) but high variance (sensitive to training data). Optimal model balances both.' }, { label: 'B', text: 'More complex models always perform better', isCorrect: false, explanation: 'Beyond optimal complexity, more complex models overfit and perform worse on new data despite fitting training data better.' }, { label: 'C', text: 'Bias and variance are always equal', isCorrect: false, explanation: 'Bias and variance are generally inversely related as model complexity changes. They are rarely equal except at one specific complexity level.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q10', questionText: 'Decision trees in machine learning split data based on:', answerChoices: [{ label: 'A', text: 'Feature values that best separate the data into homogeneous groups (minimize impurity)', isCorrect: true, explanation: 'At each node, the algorithm finds the feature and threshold that best separates classes (classification) or reduces variance (regression). Common criteria include Gini impurity and information gain.' }, { label: 'B', text: 'Random splits without considering data characteristics', isCorrect: false, explanation: 'Random splitting describes random forests partially, but individual decision trees use optimal splits based on data-driven criteria.' }, { label: 'C', text: 'Only continuous numerical features', isCorrect: false, explanation: 'Decision trees handle both continuous and categorical features naturally, which is one of their advantages over many other methods.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q11', questionText: 'Regularization techniques (like LASSO and Ridge) help prevent overfitting by:', answerChoices: [{ label: 'A', text: 'Adding a penalty term to the loss function that shrinks coefficients toward zero', isCorrect: true, explanation: 'LASSO (L1) adds |beta| penalty (can zero out coefficients for variable selection). Ridge (L2) adds beta^2 penalty (shrinks but does not zero). Both constrain model complexity to improve generalization.' }, { label: 'B', text: 'Increasing the number of features', isCorrect: false, explanation: 'Adding features increases complexity and overfitting risk. Regularization constrains complexity in the opposite direction.' }, { label: 'C', text: 'Using only the training data for evaluation', isCorrect: false, explanation: 'Using only training data for evaluation is exactly what leads to overfitting. Regularization constrains the model itself, not the evaluation method.' }], difficulty: 'Hard', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q12', questionText: 'Neural networks are particularly suited for:', answerChoices: [{ label: 'A', text: 'Learning complex non-linear relationships from large amounts of data', isCorrect: true, explanation: 'Neural networks with hidden layers can approximate any continuous function (universal approximation theorem). They excel at complex pattern recognition in large datasets (images, text, speech, financial data).' }, { label: 'B', text: 'Problems with very small data sets and few features', isCorrect: false, explanation: 'Neural networks need large data to train their many parameters. With small data, simpler models (regression, trees) often outperform neural networks.' }, { label: 'C', text: 'Only image recognition tasks', isCorrect: false, explanation: 'While excelling at images (CNNs), neural networks also handle text (RNNs/transformers), tabular data, time series, and many other data types.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q13', questionText: 'The train-test split methodology in machine learning serves to:', answerChoices: [{ label: 'A', text: 'Evaluate model performance on data not used during training to assess generalization ability', isCorrect: true, explanation: 'Holding out test data simulates real-world deployment where the model encounters unseen data. Performance on the test set provides an unbiased estimate of how well the model will perform in practice.' }, { label: 'B', text: 'Double the available training data', isCorrect: false, explanation: 'Splitting actually reduces training data (test portion is withheld). The purpose is honest evaluation, not data augmentation.' }, { label: 'C', text: 'Guarantee that the model achieves 100% accuracy', isCorrect: false, explanation: 'Train-test splits often reveal imperfect performance. Their purpose is honest assessment, which typically shows test performance below training performance.' }], difficulty: 'Easy', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
  { id: 'qm-m11-q14', questionText: 'Clustering algorithms in finance can be applied to:', answerChoices: [{ label: 'A', text: 'Group similar assets, identify market regimes, or segment clients based on behavioral patterns', isCorrect: true, explanation: 'Clustering discovers natural groupings: assets with similar return profiles, market conditions (bull/bear/sideways regimes), or client segments with similar risk preferences and behavior patterns.' }, { label: 'B', text: 'Only predict next-day stock prices', isCorrect: false, explanation: 'Price prediction is supervised learning. Clustering is unsupervised and discovers groupings without predicting specific values.' }, { label: 'C', text: 'Calculate exact fair values for securities', isCorrect: false, explanation: 'Fair value calculation requires pricing models, not clustering. Clustering reveals structure but does not produce valuations.' }], difficulty: 'Medium', subject: 'Quantitative Methods', reading: null, topic: 'Introduction to Big Data Techniques', provider: 'cfa-portal', questionSourceFile: null },
];

